const TOPICS_DATA = [{"id": "rw-info", "section": "Reading & Writing", "code": "RW-01", "title": "Information and Ideas (Thông tin & Ý tưởng)", "weight": "26% phần Reading & Writing (~12–14 câu/đề)", "summary": "Đánh giá khả năng đọc hiểu ý chính, chi tiết tường minh, suy luận hợp lý (Inferences) và sử dụng bằng chứng văn bản hoặc bảng biểu/đồ thị (Command of Evidence).", "theory": {"overview": "Chuyên đề Information and Ideas kiểm tra mức độ hiểu sâu văn bản học thuật (khoa học tự nhiên, khoa học xã hội, lịch sử, văn học). Thí sinh cần nắm bắt luận điểm trung tâm của tác giả, tìm bằng chứng củng cố hoặc phản bác một giả thuyết, và rút ra kết luận logic để hoàn thiện đoạn văn.", "rules": [{"name": "1. Central Ideas & Details (Ý chính & Chi tiết)", "desc": "Ý chính (Main Idea) phải bao quát toàn bộ đoạn văn, không quá hẹp (chỉ nêu 1 ví dụ phụ) và không quá rộng (vượt ra ngoài phạm vi văn bản). Với câu hỏi chi tiết, đáp án đúng luôn là câu diễn đạt lại (paraphrase) thông tin có thật trong bài."}, {"name": "2. Command of Evidence: Textual (Bằng chứng văn bản)", "desc": "Xác định chính xác luận điểm (Claim/Hypothesis) của nhà nghiên cứu, sau đó chọn trích dẫn hoặc phát biểu trực tiếp chứng minh (support) hoặc làm suy yếu (weaken) luận điểm đó."}, {"name": "3. Command of Evidence: Quantitative (Bằng chứng định lượng)", "desc": "Đọc kỹ tiêu đề bảng/biểu đồ, đơn vị trục tung/trục hoành. Đáp án đúng phải đồng thời: (1) Đúng với số liệu trên biểu đồ VÀ (2) Phù hợp với lập luận đang nêu trong đoạn văn."}, {"name": "4. Inferences (Suy luận logic)", "desc": "Điền câu kết luận vào cuối đoạn văn (thường sau 'therefore', 'thus', 'consequently'). Tuyệt đối không suy diễn chủ quan ngoài văn bản; kết luận phải nối khớp các tiền đề đã cho."}], "traps": ["Bẫy 'True to chart, false to claim': Số liệu trích từ bảng hoàn toàn đúng nhưng không liên quan hoặc đi ngược lại luận điểm câu văn yêu cầu.", "Bẫy 'Extreme Language': Các phương án chứa từ tuyệt đối như always, never, completely, prove definitively thường sai trừ khi văn bản gốc khẳng định đúng mức độ đó.", "Bẫy 'Half-Right': Nửa đầu đáp án đúng với bài đọc nhưng nửa sau thêm một chi tiết suy diễn không có căn cứ."], "example": {"passage": "Bioluminescence in deep-sea anglerfish is produced not by the fish itself, but by symbiotic bacteria housed in a dorsal lure called the esca. Because these bacteria cannot be cultured independently in laboratory settings, marine biologists hypothesize that the bacteria rely on specific metabolic compounds provided directly by the host fish.", "question": "Which finding, if true, would most directly support the marine biologists' hypothesis?", "analysis": "Luận điểm cần chứng minh: Vi khuẩn phát quang phụ thuộc vào hợp chất trao đổi chất do cá chủ cung cấp. Do đó, bằng chứng trực tiếp nhất là khi phân tích máu/mô ở vây esca của cá, các nhà khoa học tìm thấy các dưỡng chất đặc thù mà vi khuẩn thiếu hụt gen tự tổng hợp."}}, "exercises": [{"id": "rw-info-q1", "type": "Central Ideas", "passage": "For decades, archaeologists assumed that the monumental stone rings of Göbekli Tepe in modern-day Turkey were constructed exclusively for seasonal ritual gatherings by nomadic hunter-gatherers who lived elsewhere. However, recent excavations have uncovered extensive domestic structures, grinding stones for processing wild grain, and large rainwater cisterns carved into the bedrock, indicating a sustained year-round human presence.", "question": "Which choice best states the main idea of the text?", "options": ["A. Göbekli Tepe was abandoned by nomadic tribes due to severe water shortages.", "B. New archaeological evidence suggests that Göbekli Tepe hosted permanent residents rather than serving solely as a temporary ritual site.", "C. Ancient hunter-gatherers in Turkey invented grain agriculture before building stone monuments.", "D. The stone rings at Göbekli Tepe were primarily used as astronomical calendars rather than religious temples."], "answer": 1, "hint": "Chú ý từ chuyển ý 'However, recent excavations have uncovered... indicating a sustained year-round human presence'.", "explanation": "Đoạn văn đối lập giả thuyết cũ (chỉ là nơi tụ họp nghi lễ theo mùa) với bằng chứng khảo cổ mới (nhà ở, cối xay hạt, bể chứa nước mưa) cho thấy có cư dân sinh sống quanh năm. Do đó đáp án B nêu chính xác ý chính."}, {"id": "rw-info-q2", "type": "Inferences", "passage": "Many urban planners advocate for planting dense tree canopies along city boulevards to reduce street-level temperatures. Yet a study by environmental engineer Dr. Elena Rostova revealed that while wide-canopy trees lower daytime surface temperatures by blocking solar radiation, overly dense canopies over narrow streets can trap heat radiated from asphalt at night, meaning that ______", "question": "Which choice most logically completes the text?", "options": ["A. urban trees are completely ineffective at reducing solar radiation during summer afternoons.", "B. cities should replace all asphalt roads with concrete before planting new boulevard trees.", "C. tree-planting initiatives must account for street width and canopy density to avoid unintended nighttime warming.", "D. narrow streets consistently experience lower nighttime temperatures than wide boulevards do."], "answer": 2, "hint": "Kết hợp cả mặt lợi ban ngày và tác dụng phụ ban đêm khi tán cây quá dày trên đường hẹp.", "explanation": "Nghiên cứu chỉ ra tán cây quá dày trên phố hẹp giữ nhiệt mặt đường vào ban đêm. Suy ra quy hoạch trồng cây đô thị cần tính đến độ rộng đường và mật độ tán lá để tránh làm tăng nhiệt độ ban đêm (Đáp án C)."}, {"id": "rw-info-q3", "type": "Command of Evidence (Textual)", "passage": "Literary critic Marcus Vance argues that in Mary Shelley's 1818 novel Frankenstein, the natural landscape functions not merely as scenic background, but as an active psychological mirror that reflects Victor Frankenstein's fluctuating mental state.", "question": "Which quotation from Frankenstein would most effectively illustrate Vance's claim?", "options": ["A. 'I spent the winter in Geneva, organizing my laboratory notes and corresponding with fellow natural philosophers.'", "B. 'As my guilt over William's death consumed me, the jagged, storm-lashed peaks of Mont Blanc appeared to close in around my carriage like stern judges.'", "C. 'The journey from Ingolstadt to my native town required six days of travel by coach along winding alpine roads.'", "D. 'My father had always encouraged my cousin Elizabeth and me to study languages and geography in our youth.'"], "answer": 1, "hint": "Tìm câu trích dẫn gắn kết trực tiếp cảm xúc nội tâm của Victor với hình ảnh thiên nhiên.", "explanation": "Câu B gắn liền cảm giác tội lỗi nội tâm ('my guilt... consumed me') với cảnh quan núi Mont Blanc bão tố như những vị quan tòa nghiêm khắc ('jagged, storm-lashed peaks... like stern judges'), minh họa trực tiếp luận điểm của Vance."}, {"id": "rw-info-q4", "type": "Command of Evidence (Quantitative)", "passage": "Survey of Commuter Mode Share in Three European Cities (2015 vs. 2023):\n• Amsterdam: Cycling 36% (2015) → 41% (2023) | Public Transit 30% → 28% | Private Car 34% → 31%\n• Copenhagen: Cycling 33% (2015) → 39% (2023) | Public Transit 35% → 34% | Private Car 32% → 27%\n• Lyon: Cycling 8% (2015) → 17% (2023) | Public Transit 42% → 46% | Private Car 50% → 37%\n\nTransportation analysts observed that while Amsterdam and Copenhagen maintained the highest overall cycling rates in 2023, Lyon experienced the most dramatic relative expansion in cycling adoption alongside a simultaneous increase in public transit usage.", "question": "Which data from the survey most directly support the analysts' observation about Lyon?", "options": ["A. Lyon's cycling share more than doubled from 8% to 17%, while its public transit share rose from 42% to 46%.", "B. Amsterdam's cycling share reached 41% in 2023, whereas Lyon's private car share remained at 37%.", "C. Copenhagen reduced its private car usage from 32% to 27% between 2015 and 2023.", "D. Public transit usage in Amsterdam declined from 30% in 2015 to 28% in 2023."], "answer": 0, "hint": "Tìm phương án trích dẫn cả mức tăng tỷ lệ xe đạp và mức tăng giao thông công cộng tại Lyon.", "explanation": "Tại Lyon, tỷ lệ đi xe đạp tăng hơn gấp đôi (từ 8% lên 17%) đồng thời giao thông công cộng tăng từ 42% lên 46%, khớp hoàn toàn với nhận định của các nhà phân tích (Đáp án A)."}, {"id": "rw-info-q5", "type": "Detail Retrieval", "passage": "Unlike conventional lithium-ion batteries, which utilize liquid organic electrolytes that can catch fire if punctured, solid-state batteries employ solid ceramic or polymer electrolytes. Although solid-state designs dramatically improve thermal safety and energy density, their widespread adoption in electric vehicles has been delayed by the formation of microscopic lithium dendrites that crack ceramic separators during rapid charging.", "question": "According to the text, what is the primary technical obstacle currently hindering the widespread adoption of solid-state batteries?", "options": ["A. The high flammability of liquid organic electrolytes when exposed to oxygen.", "B. A lower overall energy density compared to traditional lithium-ion batteries.", "C. Microscopic lithium growths that damage the solid separator during fast charging.", "D. The inability of polymer electrolytes to conduct electricity at room temperature."], "answer": 2, "hint": "Đọc kỹ cụm 'delayed by the formation of microscopic lithium dendrites that crack ceramic separators during rapid charging'.", "explanation": "Văn bản nêu rõ rào cản làm chậm việc ứng dụng rộng rãi là sự hình thành các nhánh tinh thể lithium nhỏ (dendrites) làm nứt lớp ngăn gốm khi sạc nhanh (Đáp án C)."}, {"id": "rw-info-q6", "type": "Command of Evidence (Hypothesis Weakening)", "passage": "Paleontologists long hypothesized that the mass extinction of Pleistocene megafauna in North America roughly 11,000 years ago was driven primarily by rapid climate warming at the end of the Last Glacial Maximum, rather than by human hunting.", "question": "Which finding, if true, would most seriously weaken the paleontologists' hypothesis?", "options": ["A. Fossilized pollen records show that boreal forests expanded northward as glaciers retreated 11,000 years ago.", "B. Megafauna species had survived multiple previous interglacial warming periods of equal or greater intensity prior to human arrival in North America.", "C. Stone spear points crafted by early Clovis hunters have been found at fewer than twenty percent of excavated mammoth sites.", "D. Smaller mammal species such as arctic foxes adapted their foraging ranges during the Pleistocene-Holocene transition."], "answer": 1, "hint": "Nếu biến đổi khí hậu là nguyên nhân chính, tại sao các đợt ấm lên tương tự trước đó lại không làm thú lớn tuyệt chủng?", "explanation": "Nếu các loài thú lớn từng sống sót qua nhiều đợt ấm lên tương tự hoặc khắc nghiệt hơn trước khi con người xuất hiện, thì riêng việc ấm lên khí hậu khó có thể là nguyên nhân chính gây tuyệt chủng (Đáp án B làm suy yếu giả thuyết)."}, {"id": "rw-info-q7", "type": "Inferences", "passage": "In behavioral economics, the 'IKEA effect' describes consumers' tendency to place a disproportionately high value on products they partially created themselves. In a 2012 experiment by Michael Norton and colleagues, participants who folded their own origami figures offered to pay nearly five times as much for their creations as neutral buyers did—unless the instructions were so confusing that participants failed to complete the figure, in which case ______", "question": "Which choice most logically completes the text?", "options": ["A. neutral buyers became willing to pay significantly more for the unfinished origami pieces.", "B. the heightened valuation disappeared and builders rated the product no higher than non-builders did.", "C. participants demanded even more complex origami kits in subsequent rounds of the study.", "D. the time spent attempting the task guaranteed high satisfaction regardless of the outcome."], "answer": 1, "hint": "Từ 'unless' (trừ khi) báo hiệu kết quả ngược lại khi người tham gia không hoàn thành được sản phẩm.", "explanation": "Hiệu ứng định giá cao xảy ra khi người dùng tự lắp ráp thành công, 'trừ khi' (unless) họ thất bại không hoàn thành được sản phẩm — khi đó hiệu ứng tăng giá trị biến mất (Đáp án B)."}, {"id": "rw-info-q8", "type": "Central Ideas", "passage": "Composer Florence Price's Symphony No. 1 in E Minor (1932) was the first symphonic work by an African American woman to be performed by a major American orchestra. Rather than strictly imitating European Romanticism, Price wove traditional spirituals and syncopated Juba dance rhythms into classical sonata structures, forging a distinctly American symphonic idiom.", "question": "What is the main idea of the text?", "options": ["A. European Romantic symphonies were rarely performed by American orchestras during the 1930s.", "B. Florence Price achieved a historic milestone by blending African American musical traditions with classical symphonic form.", "C. The Juba dance rhythm originated in nineteenth-century symphonic concert halls.", "D. Price's Symphony No. 1 was initially rejected by conductors because it departed from strict sonata structure."], "answer": 1, "hint": "Tổng hợp cả cột mốc lịch sử (câu 1) và phong cách kết hợp âm nhạc độc đáo của Price (câu 2).", "explanation": "Đoạn văn nhấn mạnh cột mốc lịch sử của bản giao hưởng số 1 của Florence Price và cách bà kết hợp âm nhạc truyền thống của người Mỹ gốc Phi với cấu trúc giao hưởng cổ điển (Đáp án B)."}, {"id": "rw-info-q9", "type": "Command of Evidence (Quantitative)", "passage": "Average Soil Carbon Sequestration by Farming Practice (metric tons of C per hectare per year):\n• Conventional Tillage Monoculture: 0.12\n• No-Till Monoculture: 0.38\n• Multi-Species Cover Cropping + No-Till: 0.89\n• Agroforestry Alley Cropping: 1.45\n\nAgronomists contend that while eliminating tillage improves carbon retention compared to conventional plowing, integrating perennial trees alongside crops yields more than triple the annual carbon sequestration of no-till monoculture alone.", "question": "Which data from the table best support the agronomists' contention?", "options": ["A. Conventional tillage sequesters 0.12 metric tons per hectare, whereas no-till monoculture sequesters 0.38 metric tons.", "B. Multi-species cover cropping combined with no-till sequesters 0.89 metric tons per hectare annually.", "C. Agroforestry alley cropping sequesters 1.45 metric tons per hectare, which is more than three times the 0.38 metric tons sequestered by no-till monoculture.", "D. All four farming practices sequester at least 0.10 metric tons of carbon per hectare per year."], "answer": 2, "hint": "Đối chiếu số liệu của Agroforestry (trồng cây lâu năm xen canh = 1.45) với No-Till Monoculture (0.38).", "explanation": "Ta có 1.45 > 3 × 0.38 (1.14), chứng minh trực tiếp nhận định rằng kết hợp cây gỗ lâu năm (Agroforestry) hấp thụ gấp hơn 3 lần so với độc canh không cày xới (Đáp án C)."}, {"id": "rw-info-q10", "type": "Inferences", "passage": "Octopuses possess a decentralized nervous system in which two-thirds of their neurons reside in their eight arms rather than in their central brain. Consequently, even when an octopus's central brain issues a high-level command such as 'reach for that crevice,' the individual arm calculates the precise muscle contractions and trajectory locally, suggesting that ______", "question": "Which choice most logically completes the text?", "options": ["A. the central brain of an octopus has no neurological connection to its eight arms.", "B. motor control in octopuses relies on a division of labor between central goal-setting and peripheral execution.", "C. octopuses cannot learn visual tasks that require coordination among multiple arms.", "D. vertebrates and cephalopods evolved identical brain structures through convergent evolution."], "answer": 1, "hint": "Não trung ương đưa ra mệnh lệnh tổng quát ('high-level command'), còn xúc tu tự tính toán chuyển động cục bộ ('calculates locally').", "explanation": "Sự phối hợp giữa mệnh lệnh cấp cao từ não trung ương và xử lý cơ học tại chỗ ở từng xúc tu cho thấy cơ chế phân công nhiệm vụ giữa định hướng trung tâm và thực thi ngoại vi (Đáp án B)."}]}, {"id": "rw-craft", "section": "Reading & Writing", "code": "RW-02", "title": "Craft and Structure (Cấu trúc & Ngôn từ)", "weight": "28% phần Reading & Writing (~13–15 câu/đề)", "summary": "Kiểm tra từ vựng học thuật trong ngữ cảnh (Words in Context), chức năng/mục đích của đoạn văn (Text Structure & Purpose) và đối chiếu quan điểm giữa hai văn bản (Cross-Text Connections).", "theory": {"overview": "Craft and Structure chiếm tỷ trọng lớn nhất trong phần Reading & Writing. Thí sinh cần phân tích cách tác giả lựa chọn từ ngữ, cách tổ chức mạch lập luận của văn bản, và điểm đồng thuận hay bất đồng giữa hai học giả cùng bàn về một chủ đề.", "rules": [{"name": "1. Words in Context (Từ vựng trong ngữ cảnh)", "desc": "Đừng chọn từ chỉ vì nghe quen tai. Hãy tìm 'Context Clues' (dấu hiệu đồng nghĩa, tương phản, dấu hai chấm/gạch ngang giải thích) trong câu rồi tự điền 1 từ của riêng bạn trước khi nhìn 4 đáp án."}, {"name": "2. Text Structure & Purpose (Cấu trúc & Mục đích văn bản)", "desc": "Xác định động từ mô tả đúng chức năng đoạn văn: 'introduce a phenomenon then explain its cause', 'challenge a prevailing assumption', 'illustrate a theoretical concept with an empirical study'."}, {"name": "3. Function of Underlined Sentence (Chức năng câu gạch chân)", "desc": "Đọc câu ngay trước và ngay sau câu gạch chân để xem nó đóng vai trò làm cầu nối (transition), nêu phản ví dụ (counterexample), hay giải thích điều kiện giới hạn (qualification)."}, {"name": "4. Cross-Text Connections (Liên kết hai văn bản)", "desc": "Tóm tắt luận điểm chính của Text 1 và Text 2 cùng thái độ (Tích cực / Tiêu cực / Thận trọng). Chú ý các câu hỏi 'How would the author of Text 2 respond to Text 1?'."}], "traps": ["Bẫy 'Secondary Meaning': Một từ quen thuộc được dùng với nghĩa thứ hai trong học thuật (ví dụ: 'arrest' = chặn đứng/kìm hãm sự phát triển; 'qualify' = giới hạn/bổ sung điều kiện cho một nhận định).", "Bẫy 'Wrong Tone': Đáp án mô tả tác giả 'condemn' (lên án gay gắt) trong khi văn bản chỉ 'question' (đặt nghi vấn) hoặc 'qualify' (điều chỉnh nhẹ)."], "example": {"passage": "Far from being ______ artifacts of a bygone era, medieval agricultural treatises contain sophisticated soil-management techniques that modern regenerative farmers are actively adapting today.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "analysis": "Cấu trúc 'Far from being [X]... modern farmers are actively adapting today' tạo thế tương phản: không hề là những di vật lỗi thời (obsolete / outmoded) mà vẫn rất hữu ích ngày nay."}}, "exercises": [{"id": "rw-craft-q1", "type": "Words in Context", "passage": "Although the architect's initial blueprint for the civic conservatory was praised for its bold geometric стеклянный domes, the city council ultimately deemed the design too ______ for the municipality's modest infrastructure budget and commissioned a simpler structure.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. austere", "B. extravagant", "C. inconspicuous", "D. rudimentary"], "answer": 1, "hint": "Thiết kế vượt quá ngân sách khiêm tốn ('modest budget') và phải đổi sang bản đơn giản hơn ('simpler structure').", "explanation": "'Extravagant' (xa hoa, tốn kém quá mức) đối lập trực tiếp với 'modest budget' và 'simpler structure'. 'Austere' = giản dị, 'inconspicuous' = không nổi bật, 'rudimentary' = thô sơ."}, {"id": "rw-craft-q2", "type": "Words in Context", "passage": "In her biography of nineteenth-century mathematician Ada Lovelace, historian Doris Langley carefully ______ the exaggerated myths surrounding Lovelace's personal life from the verifiable documentary record of her pioneering analytical notes on Charles Babbage's mechanical computer.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. disentangles", "B. conflates", "C. obscures", "D. fabricates"], "answer": 0, "hint": "Cấu trúc '______ X from Y': tách bạch huyền thoại phóng đại khỏi tư liệu lịch sử xác thực.", "explanation": "'Disentangles' (tách bạch, gỡ rối X khỏi Y) phù hợp hoàn toàn với ngữ cảnh phân tách 'exaggerated myths' khỏi 'verifiable documentary record'."}, {"id": "rw-craft-q3", "type": "Words in Context", "passage": "While invasive plant species are frequently assumed to diminish local biodiversity uniformly, ecologist Tomasina Chen argues that this view must be ______: in heavily degraded industrial soils where native flora cannot survive, certain non-native shrubs actually stabilize nitrogen levels and create microhabitats for native insects.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. ratified", "B. qualified", "C. eradicated", "D. amplified"], "answer": 1, "hint": "Trong văn phong học thuật SAT, từ nào mang nghĩa 'được điều chỉnh/thêm điều kiện giới hạn vì không phải lúc nào cũng đúng tuyệt đối'?", "explanation": "Trong tiếng Anh học thuật, 'qualify a claim/view' có nghĩa là bổ sung điều kiện giới hạn, làm cho nhận định bớt tuyệt đối hơn (vì ở đất công nghiệp suy thoái, cây ngoại lai lại có ích). Đáp án B đúng."}, {"id": "rw-craft-q4", "type": "Text Purpose", "passage": "When sea otters were hunted nearly to extinction along the Pacific coast in the nineteenth century, populations of their primary prey—purple sea urchins—exploded. Unchecked, the urchins devoured vast underwater kelp forests, transforming vibrant marine ecosystems into barren 'urchin barrens.' Only after legal protections allowed otter populations to rebound did the kelp forests recover, demonstrating how a single apex predator regulates an entire food web.", "question": "Which choice best states the main purpose of the text?", "options": ["A. To argue that legal hunting bans are ineffective at restoring endangered marine mammals.", "B. To illustrate the ecological concept of a keystone predator through a historical case study.", "C. To compare the nutritional value of purple sea urchins with that of giant kelp.", "D. To explain why nineteenth-century fur traders targeted Pacific sea otters."], "answer": 1, "hint": "Chú ý câu kết: 'demonstrating how a single apex predator regulates an entire food web'.", "explanation": "Toàn bộ câu chuyện về rái cá biển - nhím biển - rừng tảo bẹ được dùng làm ví dụ thực tế để minh họa cách một loài săn mồi đầu bảng điều tiết cả hệ sinh thái (Đáp án B)."}, {"id": "rw-craft-q5", "type": "Function of Sentence", "passage": "Traditional solar panels generate electricity only from direct and diffuse sunlight hitting their top surface. [Bifacial solar modules, by contrast, feature transparent backsheets that capture sunlight reflected off the ground below.] When installed over highly reflective surfaces such as white gravel or snow, these dual-sided panels can produce up to 25 percent more energy than conventional monofacial panels occupying the same footprint.", "question": "Which choice best describes the function of the bracketed sentence in the overall structure of the text?", "options": ["A. It explains why traditional solar panels fail to operate in snowy climates.", "B. It introduces the mechanism of an alternative technology whose performance advantage is quantified in the following sentence.", "C. It refutes the claim made in the final sentence regarding reflective ground surfaces.", "D. It outlines the financial cost of manufacturing transparent backsheets."], "answer": 1, "hint": "Câu 1 nêu pin mặt trời truyền thống; câu trong ngoặc vuông giới thiệu cơ chế pin hai mặt (bifacial); câu 3 nêu mức tăng hiệu suất 25%.", "explanation": "Câu trong ngoặc giới thiệu cơ chế hoạt động của công nghệ pin hai mặt đối lập với pin truyền thống ở câu 1, tạo tiền đề để câu 3 định lượng ưu thế 25% năng lượng (Đáp án B)."}, {"id": "rw-craft-q6", "type": "Cross-Text Connections", "passage": "Text 1:\nLinguist David Harrison maintains that when an endangered indigenous language ceases to be spoken, humanity loses an irreplaceable repository of ecological knowledge. Because many indigenous lexicons encode centuries of observations about local medicinal plants, animal migration, and microclimates, translating words into a global language rarely preserves their full taxonomic nuance.\n\nText 2:\nAnthropologist Sonia Malik agrees that language loss is culturally tragic, yet she cautions against reducing indigenous languages primarily to their utility for Western science. Focusing predominantly on how a language catalogues botanical data risks treating a living cultural heritage as a mere database, overlooking its poetry, humor, and social identity.", "question": "Based on the texts, how would Malik (Text 2) most likely respond to Harrison's argument in Text 1?", "options": ["A. By disputing Harrison's claim that indigenous languages contain accurate botanical and climatic information.", "B. By acknowledging the validity of Harrison's point while warning that framing language value mainly around scientific utility is overly narrow.", "C. By arguing that global languages are actually superior at classifying medicinal plants.", "D. By suggesting that linguists should stop documenting endangered languages altogether."], "answer": 1, "hint": "Malik đồng ý mất ngôn ngữ là bi kịch ('agrees... yet she cautions against...'), nhưng cảnh báo không nên chỉ nhìn ngôn ngữ như một kho dữ liệu khoa học.", "explanation": "Malik công nhận giá trị của ngôn ngữ bản địa nhưng lưu ý rằng nếu chỉ nhấn mạnh giá trị khoa học/sinh thái như Harrison thì sẽ thu hẹp giá trị văn hóa, thơ ca và bản sắc xã hội của ngôn ngữ đó (Đáp án B)."}, {"id": "rw-craft-q7", "type": "Words in Context", "passage": "Because ancient papyrus scrolls carbonized during the eruption of Mount Vesuvius in 79 CE are too fragile to be physically unrolled without crumbling into ash, classicists had long considered their contents ______; however, noninvasive X-ray phase-contrast tomography combined with machine-learning algorithms has recently enabled researchers to read the ink inside intact scrolls.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. irretrievable", "B. ubiquitous", "C. redundant", "D. transparent"], "answer": 0, "hint": "Trước khi có công nghệ X-quang và AI đọc cuộn giấy mà không cần mở ra, nội dung bên trong từng bị coi là không thể khôi phục/đọc lại được.", "explanation": "'Irretrievable' (không thể khôi phục/lấy lại được) khớp với việc cuộn giấy quá giòn không thể mở ra mà không vỡ vụn, và đối lập với việc nay đã đọc được nhờ X-quang (Đáp án A)."}, {"id": "rw-craft-q8", "type": "Text Structure", "passage": "For over a century, biologists believed that cellular differentiation was strictly unidirectional: once an embryonic stem cell matured into a specialized skin or nerve cell, it could never revert to a pluripotent state. In 2006, however, Shinya Yamanaka overturned this dogma by introducing just four transcription factors into adult mouse fibroblasts, reprogramming them into induced pluripotent stem cells capable of forming any tissue type.", "question": "Which choice best describes the overall structure of the text?", "options": ["A. It presents a longstanding scientific consensus and then describes a landmark experimental discovery that refuted it.", "B. It compares two competing hypotheses from the nineteenth century and concludes that neither is valid.", "C. It questions the ethical implications of genetic reprogramming and proposes regulatory guidelines.", "D. It outlines a chronological biography of Shinya Yamanaka's early medical education."], "answer": 0, "hint": "Câu 1: 'For over a century, biologists believed...' (quan niệm cũ). Câu 2: 'In 2006, however, Shinya Yamanaka overturned this dogma...' (phát hiện bác bỏ).", "explanation": "Đoạn văn trình bày một quan niệm khoa học tồn tại lâu dài (tế bào đã biệt hóa không thể quay ngược lại) rồi mô tả khám phá đột phá năm 2006 của Yamanaka đã bác bỏ quan niệm đó (Đáp án A)."}, {"id": "rw-craft-q9", "type": "Words in Context", "passage": "In contrast to her predecessor's ______ diplomatic style, which often inflamed minor trade disagreements into public disputes, Ambassador Lin favored quiet, back-channel negotiations that resolved tariff deadlocks without attracting media spectacle.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. conciliatory", "B. pugnacious", "C. deferential", "D. impartial"], "answer": 1, "hint": "Mệnh đề quan hệ giải thích rõ phong cách người tiền nhiệm: 'which often inflamed minor trade disagreements into public disputes' (thổi bùng bất đồng nhỏ thành tranh cãi công khai).", "explanation": "'Pugnacious' (hiếu chiến, hay gây hấn/tranh cãi) khớp với việc thổi bùng bất đồng thương mại và đối lập với phong cách đàm phán ôn hòa, kín đáo của Đại sứ Lin (Đáp án B)."}, {"id": "rw-craft-q10", "type": "Cross-Text Connections", "passage": "Text 1:\nEconomist Robert Gordon argues that the transformative productivity boom of 1870–1970—driven by electricity, internal combustion, indoor plumbing, and aviation—was a one-time historical event. In his view, recent digital innovations primarily entertainment and communication rather than fundamentally altering material output per worker.\n\nText 2:\nTechnologist Erik Brynjolfsson counters that general-purpose technologies like artificial intelligence always exhibit a 'productivity J-curve.' Just as factories took forty years to reorganize workflows around electric motors, modern enterprises are still building the complementary organizational structures required for AI to generate massive measurable productivity gains.", "question": "Which statement best describes the primary disagreement between Gordon (Text 1) and Brynjolfsson (Text 2)?", "options": ["A. Whether electricity had a significant impact on manufacturing between 1870 and 1970.", "B. Whether recent digital and AI technologies have the potential to match the transformative productivity gains of earlier industrial inventions.", "C. Whether factories in the early twentieth century used electric motors or steam engines.", "D. Whether economists should measure productivity using gross domestic product."], "answer": 1, "hint": "Gordon cho rằng công nghệ số không tạo ra bứt phá năng suất như kỷ nguyên 1870–1970; Brynjolfsson phản biện rằng AI chỉ đang ở giai đoạn trễ trước khi bùng nổ năng suất.", "explanation": "Hai tác giả bất đồng cốt lõi về việc liệu công nghệ số/AI hiện đại có khả năng tạo ra bước nhảy vọt năng suất tương đương các phát minh công nghiệp trước đây hay không (Đáp án B)."}]}, {"id": "rw-expr", "section": "Reading & Writing", "code": "RW-03", "title": "Expression of Ideas (Diễn đạt Ý tưởng)", "weight": "20% phần Reading & Writing (~8–12 câu/đề)", "summary": "Gồm hai dạng bài chiến lược: Từ nối chuyển ý (Transitions) và Tổng hợp thông tin theo mục tiêu tu từ (Rhetorical Synthesis / Student Notes).", "theory": {"overview": "Expression of Ideas kiểm tra khả năng tổ chức mạch văn mạch lạc và lựa chọn thông tin đúng mục đích giao tiếp. Đây là phần có thể ăn điểm tuyệt đối 100% nếu nắm vững phân loại từ nối và kỹ thuật đọc câu hỏi Rhetorical Synthesis.", "rules": [{"name": "1. Nhóm từ nối Tương phản (Contrast Transitions)", "desc": "However, Nevertheless, Nonetheless, By contrast, Conversely, On the other hand, Still, Yet. Dùng khi mệnh đề sau đi ngược kỳ vọng hoặc đối lập với mệnh đề trước."}, {"name": "2. Nhóm từ nối Nguyên nhân - Kết quả (Cause & Effect)", "desc": "Therefore, Thus, Consequently, As a result, Accordingly, Hence. Dùng khi câu sau là hệ quả trực tiếp sinh ra từ câu trước."}, {"name": "3. Nhóm từ nối Bổ sung / Ví dụ / Tương đồng", "desc": "Moreover, Furthermore, In addition (Bổ sung); For instance, For example, Specifically (Ví dụ cụ thể hóa); Similarly, Likewise (Tương đồng giữa 2 đối tượng khác nhau)."}, {"name": "4. Chiến thuật Rhetorical Synthesis (Notes)", "desc": "Đọc kỹ yêu cầu của đề bài (Goal) TRƯỚC khi đọc gạch đầu dòng (Notes). Nếu đề yêu cầu 'emphasize a difference', đáp án BẮT BUỘC phải nêu cả 2 đối tượng kèm từ nối đối lập. Nếu đề yêu cầu 'introduce X to an unfamiliar audience', đáp án phải có định nghĩa/giải thích X là gì."}], "traps": ["Bẫy 'Grammar Correct, Goal Wrong' trong bài Notes: Cả 4 đáp án đều đúng ngữ pháp và đúng sự thật trong Notes, nhưng chỉ 1 đáp án hoàn thành đúng 'Goal' được hỏi.", "Bẫy 'Similarly vs. Moreover': 'Similarly' dùng khi chuyển sang đối tượng B có đặc điểm giống đối tượng A; 'Moreover' dùng khi bổ sung thêm 1 ý nữa cho cùng đối tượng A."], "example": {"passage": "Chemist Percy Julian synthesized physostigmine, a treatment for glaucoma, from the Calabar bean in 1935. ______ he developed a method to mass-produce cortisone from soybean sterols, making arthritis treatment affordable for millions of patients.", "question": "Which choice completes the text with the most logical transition?", "analysis": "Câu 1 nêu thành tựu 1 của Percy Julian; câu 2 nêu thêm thành tựu 2 của cùng nhà khoa học đó. Từ nối hợp lý là 'Later,' hoặc 'Additionally,' / 'Moreover,'."}}, "exercises": [{"id": "rw-expr-q1", "type": "Transitions", "passage": "In the 1960s, geologist Marie Tharp mapped the floor of the Atlantic Ocean using sonar data and discovered a continuous rift valley running along the Mid-Atlantic Ridge. Many male colleagues initially dismissed her findings as 'girl talk'; ______ subsequent seismic measurements confirmed that the rift valley was direct evidence of seafloor spreading and plate tectonics.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. therefore,", "B. nevertheless,", "C. for instance,", "D. similarly,"], "answer": 1, "hint": "Vế trước: đồng nghiệp bác bỏ phát hiện của bà; Vế sau: dữ liệu địa chấn xác nhận bà hoàn toàn đúng.", "explanation": "Hai mệnh đề mang quan hệ đối lập (ban đầu bị bác bỏ >< sau đó được chứng minh là đúng), nên cần từ nối tương phản 'nevertheless,' (tuy nhiên / dù vậy). Đáp án B."}, {"id": "rw-expr-q2", "type": "Transitions", "passage": "Bumblebees generate heat by rapidly contracting their flight muscles without flapping their wings, a process known as non-shivering thermogenesis. ______ they can forage in chilly alpine meadows at dawn when honeybees and butterflies remain immobilized by the cold.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. Consequently,", "B. By contrast,", "C. Regardless,", "D. In other words,"], "answer": 0, "hint": "Câu 1 nêu cơ chế tự làm ấm cơ thể của ong nghệ; câu 2 nêu kết quả là chúng có thể đi kiếm ăn trong sương lạnh lúc bình minh.", "explanation": "Nhờ khả năng tự sinh nhiệt (nguyên nhân ở câu 1), ong nghệ có thể kiếm ăn dưới trời lạnh (kết quả ở câu 2). Từ nối chỉ kết quả 'Consequently,' (Do đó) là chính xác nhất."}, {"id": "rw-expr-q3", "type": "Transitions", "passage": "To survive extreme drought, the resurrection plant Selaginella lepidophylla curls into a tight brown ball and loses up to 95 percent of its cellular water. ______ the microscopic tardigrade enters a dehydrated state called anhydrobiosis, reducing its metabolic activity to nearly zero until moisture returns.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. However,", "B. Likewise,", "C. As a result,", "D. Instead,"], "answer": 1, "hint": "Câu 1 nói về thực vật S. lepidophylla chịu hạn bằng cách mất nước tạm thời; câu 2 chuyển sang loài gấu nước (tardigrade) cũng có cơ chế tương tự.", "explanation": "'Likewise,' (Tương tự như vậy) dùng để nối hai đối tượng khác nhau (cây hồi sinh và gấu nước) cùng có cơ chế sinh tồn giống nhau khi khô hạn (Đáp án B)."}, {"id": "rw-expr-q4", "type": "Transitions", "passage": "Architect Zaha Hadid rejected the rigid right angles of modernist glass boxes in favor of sweeping, fluid curves inspired by natural topography. ______ her Heydar Aliyev Center in Baku, Azerbaijan, features an undulating white roof that flows seamlessly into the surrounding plaza without a single visible corner.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. Specifically,", "B. Nevertheless,", "C. Conversely,", "D. Meanwhile,"], "answer": 0, "hint": "Câu 1 nêu triết lý thiết kế đường cong uốn lượn của Zaha Hadid; câu 2 đưa ra một công trình cụ thể minh họa cho triết lý đó.", "explanation": "'Specifically,' (Cụ thể là) dẫn dắt công trình Heydar Aliyev Center làm ví dụ cụ thể hóa cho phong cách kiến trúc đường cong ở câu 1 (Đáp án A)."}, {"id": "rw-expr-q5", "type": "Transitions", "passage": "In acoustics, 'white noise' contains equal intensity across all audible frequencies, producing a bright, hissing sound similar to radio static. 'Pink noise,' ______ reduces the volume of higher frequencies by three decibels per octave, yielding a deeper, more balanced sound resembling steady rainfall.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. therefore,", "B. by contrast,", "C. in addition,", "D. for example,"], "answer": 1, "hint": "So sánh sự khác biệt giữa 'white noise' (cường độ bằng nhau ở mọi tần số) và 'pink noise' (giảm tần số cao đi 3 dB mỗi quãng tám).", "explanation": "'By contrast,' (Trái lại / Ngược lại) làm nổi bật sự đối lập về đặc tính âm học giữa tiếng ồn trắng và tiếng ồn hồng (Đáp án B)."}, {"id": "rw-expr-q6", "type": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes:\n• The Svalbard Global Seed Vault is a secure underground facility on the Norwegian island of Spitsbergen.\n• It opened in 2008 to preserve duplicate samples of crop seeds from gene banks worldwide.\n• Permafrost surrounding the sandstone vault keeps the chambers naturally cold at −3°C to −4°C.\n• Mechanical cooling systems further lower the temperature to −18°C.\n• If mechanical power fails, the permafrost ensures that seeds remain frozen for weeks.", "question": "The student wants to explain how the vault's natural environment provides a safeguard against power outages. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Opened in 2008 on the Norwegian island of Spitsbergen, the Svalbard Global Seed Vault stores duplicate crop seeds from around the world.", "B. Although mechanical cooling systems keep the Svalbard Global Seed Vault at −18°C, the surrounding permafrost maintains subfreezing temperatures of −3°C to −4°C, keeping seeds frozen for weeks even if power fails.", "C. The Svalbard Global Seed Vault uses mechanical cooling systems to lower chamber temperatures from −3°C down to −18°C.", "D. Located on Spitsbergen, the Svalbard Global Seed Vault preserves crop diversity in a sandstone facility."], "answer": 1, "hint": "Mục tiêu: Giải thích môi trường tự nhiên (permafrost) bảo vệ hạt giống như thế nào khi mất điện (power outages).", "explanation": "Đáp án B kết nối chính xác lớp băng vĩnh cửu tự nhiên (−3°C đến −4°C) với khả năng giữ hạt giống đông lạnh nhiều tuần ngay cả khi hệ thống điện gặp sự cố."}, {"id": "rw-expr-q7", "type": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes:\n• Pando is a colony of quaking aspen trees (Populus tremuloides) in Utah's Fishlake National Forest.\n• Although it appears to be a forest of 47,000 individual trees, all the stems share an identical genetic makeup and a single massive underground root system.\n• Pando covers 106 acres and weighs an estimated 6,000 metric tons, making it the heaviest known living organism on Earth.\n• By comparison, the largest blue whale weighs approximately 190 metric tons.", "question": "The student wants to emphasize Pando's immense scale by comparing it to an animal. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Pando is a colony of 47,000 genetically identical quaking aspen stems located in Utah's Fishlake National Forest.", "B. Covering 106 acres in Utah, Pando shares a single underground root system across all its trees.", "C. Weighing an estimated 6,000 metric tons, the single aspen organism known as Pando is more than thirty times heavier than the largest blue whale (190 metric tons).", "D. Blue whales, which can weigh up to 190 metric tons, are the largest animals on Earth."], "answer": 2, "hint": "Đáp án phải nêu khối lượng khổng lồ của Pando VÀ đặt cạnh phép so sánh với cá voi xanh.", "explanation": "Đáp án C làm nổi bật quy mô của Pando (6.000 tấn) bằng cách đối chiếu trực tiếp với động vật lớn nhất là cá voi xanh (190 tấn)."}, {"id": "rw-expr-q8", "type": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes:\n• Maya Lin is an American architect and sculptor.\n• In 1981, while still an undergraduate at Yale University, she won a nationwide public design competition for the Vietnam Veterans Memorial in Washington, D.C.\n• Her design featured two polished black granite walls recessed into the earth, inscribed chronologically with the names of 58,318 fallen service members.\n• In 1989, she designed the Civil Rights Memorial in Montgomery, Alabama, which incorporates a circular black granite water table.", "question": "The student wants to highlight a similarity in materials between two of Maya Lin's memorials. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Maya Lin won the design competition for the Vietnam Veterans Memorial in 1981 while studying at Yale University.", "B. Both Maya Lin's Vietnam Veterans Memorial (1981) and her Civil Rights Memorial (1989) incorporate black granite as a central design material.", "C. Whereas the Vietnam Veterans Memorial is located in Washington, D.C., the Civil Rights Memorial stands in Montgomery, Alabama.", "D. The Vietnam Veterans Memorial lists 58,318 names in chronological order on two recessed walls."], "answer": 1, "hint": "Tìm phương án nhắc đến cả hai đài tưởng niệm và điểm chung về vật liệu ('black granite').", "explanation": "Đáp án B nêu rõ điểm tương đồng về vật liệu ('black granite') giữa cả hai công trình Vietnam Veterans Memorial và Civil Rights Memorial."}, {"id": "rw-expr-q9", "type": "Transitions", "passage": "Many Roman marble statues displayed in museums today appear stark white, leading nineteenth-century art historians to celebrate monochrome purity as the classical ideal. Ultraviolet fluorescence analysis has revealed microscopic traces of lapis lazuli, red ochre, and gold leaf on these sculptures; ______ ancient Roman statuary was actually painted in vibrant, lifelike colors.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. in fact,", "B. nonetheless,", "C. on the contrary, some", "D. previously,"], "answer": 0, "hint": "Vế trước nêu bằng chứng phân tích tia UV tìm thấy vết màu xanh, đỏ, vàng trên tượng; vế sau khẳng định thực tế tượng La Mã cổ đại được sơn màu rực rỡ.", "explanation": "'In fact,' (Thực tế là / Thật vậy) dùng để củng cố và đi sâu vào kết luận thực tế được chứng minh bởi phân tích tia UV ngay trước đó (Đáp án A)."}, {"id": "rw-expr-q10", "type": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes:\n• Acoustic telemetry is a tracking method used by marine biologists to study fish movement.\n• Researchers surgically implant a small ultrasonic transmitter into a fish.\n• Submerged hydrophone receivers stationed along a river or coastline detect the transmitter's unique ping when the fish swims within 500 meters.\n• Satellite tags, by contrast, must rise to the ocean surface to transmit data to orbiting satellites and cannot send signals through deep water.", "question": "The student wants to contrast how acoustic telemetry and satellite tags transmit tracking data. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Marine biologists use acoustic telemetry by implanting a small ultrasonic transmitter into a fish.", "B. While acoustic telemetry transmitters send ultrasonic pings to underwater receivers within 500 meters, satellite tags must reach the water's surface to transmit data to satellites.", "C. Satellite tags cannot transmit signals through deep water, making them useful primarily for surface-dwelling marine animals.", "D. Hydrophone receivers stationed along coastlines can detect ultrasonic pings from up to 500 meters away."], "answer": 1, "hint": "Mục tiêu là 'contrast' (đối lập) cơ chế truyền dữ liệu của cả 2 công nghệ.", "explanation": "Đáp án B dùng cấu trúc đối lập 'While...' để so sánh trực tiếp cách truyền tín hiệu dưới nước của acoustic telemetry với yêu cầu phải nổi lên mặt nước của satellite tags."}]}, {"id": "rw-conv", "section": "Reading & Writing", "code": "RW-04", "title": "Standard English Conventions (Quy chuẩn Ngữ pháp)", "weight": "26% phần Reading & Writing (~11–15 câu/đề)", "summary": "Kiểm tra dấu câu nối mệnh đề (Boundaries: dấu chấm, chấm phẩy, hai chấm, gạch ngang, dấu phẩy) và cấu trúc câu (Subject-Verb Agreement, Verb Tense, Modifiers, Pronouns).", "theory": {"overview": "Standard English Conventions xuất hiện ở nửa sau của mỗi Module Reading & Writing. Đây là phần quy tắc rõ ràng nhất như toán học: chỉ cần phân tích cấu trúc Mệnh đề độc lập (Independent Clause - IC) và Mệnh đề phụ thuộc (Dependent Clause - DC).", "rules": [{"name": "1. Quy tắc nối 2 Mệnh đề độc lập (IC — IC)", "desc": "Để nối 2 mệnh đề độc lập (có S + V hoàn chỉnh), CHỈ được dùng: (a) Dấu chấm (.); (b) Dấu chấm phẩy (;); (c) Dấu phẩy + liên từ FANBOYS (, for/and/nor/but/or/yet/so); hoặc (d) Dấu hai chấm (:) / gạch ngang (—) nếu vế sau giải thích cho vế trước. Dùng mỗi dấu phẩy (IC, IC) là lỗi Comma Splice!"}, {"name": "2. Dấu câu bao quanh thành phần phụ (Non-essential Clause)", "desc": "Cụm giải thích xen giữa câu phải được đóng mở đồng bộ: (, ... ,) hoặc (— ... —) hoặc (( ... )). Không bao giờ trộn lẫn một bên dấu phẩy, một bên dấu gạch ngang (, ... —)."}, {"name": "3. Dangling Modifiers (Bổ ngữ treo đầu câu)", "desc": "Khi câu mở đầu bằng cụm phân từ (V-ing / V-ed / Having + P2...), danh từ đứng NGAY SAU dấu phẩy bắt buộc phải là chủ thể thực hiện hành động đó!"}, {"name": "4. Subject-Verb Agreement & Bẫy giới từ", "desc": "Tìm chủ ngữ chính bằng cách gạch bỏ toàn bộ cụm giới từ (of..., in..., along with...) và mệnh đề quan hệ đứng giữa chủ ngữ và động từ."}], "traps": ["Bẫy 'However' giữa hai mệnh đề độc lập: 'however', 'therefore', 'moreover' KHÔNG phải là liên từ FANBOYS! Phải viết 'IC; however, IC' hoặc 'IC. However, IC' — viết 'IC, however, IC' là SAI ngữ pháp!", "Bẫy Tên riêng đi kèm danh từ xác định: Khi chức danh/danh từ chỉ có 1 đối tượng duy nhất hoặc gắn liền làm định ngữ thiết yếu (ví dụ: 'Astrophysicist Vera Rubin...'), KHÔNG dùng dấu phẩy ngăn cách giữa danh từ chung và tên riêng."], "example": {"passage": "Analyze the chemical composition of meteorites found in Antarctica, planetary scientists ______ that several specimens originated from the volcanic crust of Mars.", "question": "If the sentence begins with 'Analyzing the chemical composition...', what must follow the comma?", "analysis": "Sau cụm 'Analyzing the chemical composition of meteorites found in Antarctica,' chủ ngữ đứng ngay sau dấu phẩy phải là người phân tích ('planetary scientists'), không thể là 'several specimens'."}}, "exercises": [{"id": "rw-conv-q1", "type": "Boundaries (Comma Splice vs. Semicolon)", "passage": "In 1928, bacteriologist Alexander Fleming noticed that a mold called Penicillium notatum had contaminated one of his petri dishes ______ the bacterial colonies surrounding the mold had been completely dissolved.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. dishes, moreover,", "B. dishes; intriguingly,", "C. dishes, intriguingly,", "D. dishes intriguingly"], "answer": 1, "hint": "Vế trước và vế sau chỗ trống đều là mệnh đề độc lập hoàn chỉnh (IC). 'Intriguingly' và 'moreover' là trạng từ chuyển tiếp, không phải FANBOYS.", "explanation": "Nối hai mệnh đề độc lập với trạng từ chuyển tiếp 'intriguingly' bắt buộc dùng dấu chấm phẩy trước và dấu phẩy sau: 'dishes; intriguingly,' (Đáp án B). Đáp án A và C phạm lỗi Comma Splice."}, {"id": "rw-conv-q2", "type": "Dangling Modifiers", "passage": "Equipped with a cryogenic infrared spectrograph capable of peering through dense clouds of cosmic dust, ______", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. astronomers used the James Webb Space Telescope to detect water vapor in a distant protoplanetary disk.", "B. water vapor was detected in a distant protoplanetary disk by the James Webb Space Telescope.", "C. the James Webb Space Telescope detected water vapor in a distant protoplanetary disk.", "D. a distant protoplanetary disk was found to contain water vapor via the James Webb Space Telescope."], "answer": 2, "hint": "Ai/cái gì được trang bị ('Equipped with...') máy quang phổ hồng ngoại? Chính là chiếc kính viễn vọng không gian James Webb!", "explanation": "Cụm phân từ mở đầu 'Equipped with a cryogenic infrared spectrograph...' bổ nghĩa cho chủ ngữ đứng ngay sau dấu phẩy. Vật được trang bị thiết bị này là 'the James Webb Space Telescope' (Đáp án C), không phải các nhà thiên văn học hay hơi nước."}, {"id": "rw-conv-q3", "type": "Subject-Verb Agreement", "passage": "The intricate network of fungal mycelium threads that connects the root systems of Douglas fir trees across old-growth Pacific Northwest forests ______ nutrients such as carbon, nitrogen, and phosphorus between mature canopy trees and shaded seedlings.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. transfer", "B. transfers", "C. are transferring", "D. have transferred"], "answer": 1, "hint": "Tìm chủ ngữ chính đứng đầu câu trước giới từ 'of': 'The intricate network'.", "explanation": "Chủ ngữ chính là danh từ số ít 'The intricate network' (các cụm 'of fungal mycelium threads' và 'that connects... forests' chỉ là thành phần bổ nghĩa). Do đó cần động từ số ít 'transfers' (Đáp án B)."}, {"id": "rw-conv-q4", "type": "Non-essential Clauses (Paired Dashes)", "passage": "The Bauhaus art school—founded by architect Walter Gropius in Weimar, Germany, in 1919 ______ revolutionized twentieth-century industrial design by uniting fine art with practical craftsmanship.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. —", "B. ,", "C. ;", "D. :"], "answer": 0, "hint": "Cụm phụ bắt đầu bằng dấu gạch ngang dài ('—founded by...') thì phải kết thúc bằng dấu gì để đồng bộ?", "explanation": "Mệnh đề phụ xen giữa chủ ngữ 'The Bauhaus art school' và động từ 'revolutionized' được mở bằng dấu em-dash (—), nên bắt buộc phải đóng lại bằng dấu em-dash (—) (Đáp án A)."}, {"id": "rw-conv-q5", "type": "Colon Usage", "passage": "Marine biologist Sylvia Earle's research on deep-ocean ecosystems rests on one foundational ______ the health of terrestrial life is inextricably linked to the preservation of the ocean's phytoplankton and coral reefs.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. premise:", "B. premise, that", "C. premise; which is", "D. premise"], "answer": 0, "hint": "Vế trước là một mệnh đề độc lập hoàn chỉnh ('...rests on one foundational premise'), vế sau giải thích trực tiếp 'foundational premise' đó là gì.", "explanation": "Dấu hai chấm (:) đứng sau một mệnh đề độc lập để giới thiệu lời giải thích cụ thể cho danh từ 'one foundational premise' (Đáp án A)."}, {"id": "rw-conv-q6", "type": "Restrictive Appositives (No Comma)", "passage": "In 1977, Kenyan environmentalist ______ founded the Green Belt Movement, a grassroots organization that has empowered rural women to plant more than fifty million trees across East Africa.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. Wangari Maathai,", "B. Wangari Maathai", "C. , Wangari Maathai,", "D. , Wangari Maathai"], "answer": 1, "hint": "Cụm danh từ nghề nghiệp/quốc tịch 'Kenyan environmentalist' đi trực tiếp trước tên riêng 'Wangari Maathai' làm chủ ngữ chính.", "explanation": "Khi danh từ chỉ nghề nghiệp ('Kenyan environmentalist') đứng trước tên riêng ('Wangari Maathai'), tên riêng là thành phần xác định thiết yếu (restrictive appositive) và là chủ ngữ của động từ 'founded', nên không dùng bất kỳ dấu phẩy nào (Đáp án B)."}, {"id": "rw-conv-q7", "type": "Apostrophes & Possessive Pronouns", "passage": "Unlike deciduous trees, which shed ______ leaves each autumn to conserve water during freezing months, coniferous evergreens retain needle-shaped foliage coated in a thick waxy cuticle.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. its", "B. their", "C. it's", "D. they're"], "answer": 1, "hint": "Đại từ sở hữu thay thế cho danh từ số nhiều 'deciduous trees' và đứng trước danh từ 'leaves'.", "explanation": "Danh từ tiền ngữ là 'deciduous trees' (số nhiều), nên cần tính từ sở hữu số nhiều 'their' (Đáp án B). 'They're' = they are; 'its' là số ít."}, {"id": "rw-conv-q8", "type": "Verb Tense & Aspect", "passage": "Before the completion of the Transcontinental Railroad in May 1869, overland travelers journeying from Missouri to California ______ nearly six months crossing rugged mountain passes by covered wagon.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. spend", "B. have spent", "C. had spent", "D. will spend"], "answer": 2, "hint": "Mốc thời gian 'Before the completion of... in May 1869' chỉ hành động xảy ra trước một mốc trong quá khứ.", "explanation": "Sự việc xảy ra trước một mốc thời gian xác định trong quá khứ ('Before... May 1869') nên dùng thì quá khứ hoàn thành 'had spent' (Đáp án C)."}, {"id": "rw-conv-q9", "type": "Parallelism in Comparisons", "passage": "The tensile strength of dragline silk spun by the golden orb-weaver spider is significantly greater than ______ of high-grade alloy steel of equivalent weight.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. those", "B. that", "C. what", "D. threads"], "answer": 1, "hint": "Đang so sánh 'The tensile strength' (danh từ số ít) của tơ nhện với 'the tensile strength' của thép hợp kim.", "explanation": "Trong cấu trúc so sánh song song, đại từ 'that' thay thế cho danh từ số ít 'the tensile strength' đã nhắc ở đầu câu ('greater than that of high-grade alloy steel'). Đáp án B."}, {"id": "rw-conv-q10", "type": "Embedded Questions vs. Direct Questions", "passage": "Neuroscientists studying sleep spindles—brief bursts of brain activity during non-REM sleep—are investigating how these oscillations consolidate newly acquired motor memories and whether ______ decline with age.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. do they", "B. they", "C. they?", "D. do they?"], "answer": 1, "hint": "Đây là câu trần thuật chứa mệnh đề danh ngữ ('are investigating how... and whether...'), không phải câu hỏi trực tiếp.", "explanation": "Mệnh đề phụ bắt đầu bằng 'whether' là câu hỏi gián tiếp (embedded question) nằm trong câu trần thuật ('Neuroscientists... are investigating...'), nên giữ trật tự S + V bình thường ('they decline') và kết thúc bằng dấu chấm câu (Đáp án B)."}]}, {"id": "math-alg", "section": "Math", "code": "MATH-01", "title": "Algebra (Đại số Tuyến tính)", "weight": "35% phần Math (~13–15 câu/đề)", "summary": "Phương trình bậc nhất một ẩn và hai ẩn, hàm số bậc nhất y = mx + b, hệ phương trình tuyến tính (vô nghiệm, vô số nghiệm, nghiệm duy nhất) và bất phương trình.", "theory": {"overview": "Algebra là nền tảng lớn nhất của phần Toán Digital SAT (chiếm hơn 1/3 tổng số câu). Các câu hỏi tập trung vào ý nghĩa thực tế của hệ số góc (slope) và tung độ gốc (y-intercept), điều kiện nghiệm của hệ phương trình tuyến tính và bài toán lập hệ phương trình.", "rules": [{"name": "1. Ý nghĩa thực tế của Hàm bậc nhất f(x) = mx + b", "desc": "Trong bài toán thực tế: 'b' (y-intercept, giá trị khi x = 0) là giá trị khởi đầu / phí cố định ban đầu. 'm' (slope = Δy/Δx) là tốc độ thay đổi (tăng hoặc giảm) trên mỗi đơn vị của x."}, {"name": "2. Quan hệ giữa hai đường thẳng y = m₁x + b₁ và y = m₂x + b₂", "desc": "• Song song (Parallel / No solution): m₁ = m₂ và b₁ ≠ b₂.\n• Trùng nhau (Infinitely many solutions): m₁ = m₂ và b₁ = b₂.\n• Vuông góc (Perpendicular): m₁ · m₂ = −1 (tức m₂ = −1/m₁)."}, {"name": "3. Điều kiện nghiệm của Hệ phương trình a₁x + b₁y = c₁ và a₂x + b₂y = c₂", "desc": "• Vô nghiệm (No solution): a₁/a₂ = b₁/b₂ ≠ c₁/c₂.\n• Vô số nghiệm (Infinitely many solutions): a₁/a₂ = b₁/b₂ = c₁/c₂.\n• Nghiệm duy nhất (Exactly one solution): a₁/a₂ ≠ b₁/b₂."}, {"name": "4. Mẹo tính nhanh Biểu thức tổ hợp (Combination Expression)", "desc": "Khi đề cho hệ 2 phương trình và hỏi giá trị của (x + y) hoặc (3x − 2y), hãy thử cộng hoặc trừ vế theo vế hai phương trình trước khi giải từng ẩn riêng lẻ!"}], "traps": ["Bẫy đổi đơn vị: Đề cho tốc độ theo phút nhưng hỏi quãng đường theo giờ.", "Bẫy hỏi biểu thức thay vì hỏi x: Đề hỏi giá trị của '4x + 8' chứ không hỏi 'x', nếu giải ra x rồi chọn ngay giá trị của x sẽ dính bẫy."], "example": {"passage": "For what value of k does the system of linear equations 6x − 4y = 10 and kx − 6y = 15 have infinitely many solutions?", "question": "Find the value of k.", "analysis": "Hệ có vô số nghiệm khi tỷ lệ các hệ số bằng nhau: 6/k = (−4)/(−6) = 10/15 = 2/3. Suy ra 6/k = 2/3 ⇒ k = 9."}}, "exercises": [{"id": "math-alg-q1", "type": "Linear Equations", "passage": "If 3(2x − 5) + 4 = 2x + 13, what is the value of 6x − 5?", "question": "Select the correct value of 6x − 5.", "options": ["A. 6", "B. 24", "C. 31", "D. 36"], "answer": 2, "hint": "Giải tìm x trước, sau đó nhớ thay vào biểu thức 6x − 5.", "explanation": "Khai triển: 6x − 15 + 4 = 2x + 13 ⇔ 6x − 11 = 2x + 13 ⇔ 4x = 24 ⇔ x = 6. Thay x = 6 vào biểu thức câu hỏi yêu cầu: 6(6) − 5 = 36 − 5 = 31 (Đáp án C)."}, {"id": "math-alg-q2", "type": "Linear Function Interpretation", "passage": "A commercial 3D printer uses a filament spool whose remaining mass M(t), in grams, after t hours of continuous printing is modeled by the function M(t) = 1,000 − 42t.", "question": "What is the best interpretation of the number 42 in this context?", "options": ["A. The printer finishes printing after 42 hours.", "B. The initial mass of the filament spool is 42 grams.", "C. The printer consumes 42 grams of filament for each hour of printing.", "D. There are 42 grams of filament remaining when printing stops."], "answer": 2, "hint": "Trong hàm M(t) = 1,000 − 42t, 1,000 là khối lượng ban đầu (t = 0), còn −42 là hệ số góc (tốc độ giảm khối lượng mỗi giờ).", "explanation": "Hệ số góc −42 biểu thị khối lượng sợi in giảm đi 42 gam sau mỗi giờ in liên tục (Đáp án C)."}, {"id": "math-alg-q3", "type": "System of Linear Equations (No Solution)", "passage": "In the system of equations below, c is a constant:\n8x − 12y = 20\n6x + cy = 11\nIf the system has no solution, what is the value of c?", "question": "Find the value of the constant c.", "options": ["A. −9", "B. −8", "C. 8", "D. 9"], "answer": 0, "hint": "Hệ vô nghiệm khi tỷ số hệ số của x bằng tỷ số hệ số của y: 8/6 = −12/c.", "explanation": "Để hệ vô nghiệm, hai đường thẳng phải song song: 8/6 = (−12)/c ≠ 20/11. Từ 8c = −72 suy ra c = −9 (Đáp án A)."}, {"id": "math-alg-q4", "type": "System Combination Shortcut", "passage": "If (x, y) satisfies the system of equations:\n7x + 3y = 41\n2x + 6y = 22\nWhat is the value of x + y?", "question": "Calculate the value of x + y.", "options": ["A. 5", "B. 7", "C. 9", "D. 11"], "answer": 1, "hint": "Cộng vế theo vế hai phương trình sẽ thu được 9x + 9y ở vế trái!", "explanation": "Cộng hai phương trình: (7x + 2x) + (3y + 6y) = 41 + 22 ⇔ 9x + 9y = 63. Chia cả hai vế cho 9 ta được x + y = 7 (Đáp án B)."}, {"id": "math-alg-q5", "type": "Perpendicular Lines", "passage": "Line L in the xy-plane passes through the points (−2, 5) and (4, 8). Line K is perpendicular to line L and passes through the point (2, −1). What is the y-intercept of line K?", "question": "Determine the y-intercept of line K.", "options": ["A. (0, −5)", "B. (0, 1)", "C. (0, 3)", "D. (0, 4)"], "answer": 2, "hint": "Tính hệ số góc m_L = (8 − 5)/(4 − (−2)), sau đó tìm m_K = −1/m_L.", "explanation": "Hệ số góc của đường thẳng L là m_L = (8 − 5)/(4 + 2) = 3/6 = 1/2. Vì K vuông góc với L nên m_K = −1/(1/2) = −2. Phương trình đường thẳng K đi qua (2, −1): y − (−1) = −2(x − 2) ⇔ y = −2x + 3. Vậy giao điểm với trục tung (y-intercept) là (0, 3) (Đáp án C)."}, {"id": "math-alg-q6", "type": "Word Problem with Systems", "passage": "A science museum sells adult tickets for $18 each and student tickets for $11 each. On Saturday, the museum sold a total of 250 tickets and collected $3,660 in ticket revenue. How many student tickets were sold on Saturday?", "question": "Find the number of student tickets sold.", "options": ["A. 110", "B. 120", "C. 130", "D. 140"], "answer": 1, "hint": "Gọi s là số vé học sinh và a là số vé người lớn: a + s = 250 và 18a + 11s = 3,660.", "explanation": "Từ a = 250 − s, thay vào phương trình doanh thu: 18(250 − s) + 11s = 3,660 ⇔ 4,500 − 18s + 11s = 3,660 ⇔ 7s = 840 ⇔ s = 120 vé học sinh (Đáp án B)."}, {"id": "math-alg-q7", "type": "Linear Inequalities", "passage": "A cargo elevator has a maximum weight capacity of 2,400 pounds. An operator weighing 180 pounds is loading identical crates that each weigh 65 pounds onto the elevator. What is the maximum number of complete crates the operator can accompany in a single trip without exceeding the weight limit?", "question": "Select the maximum number of crates.", "options": ["A. 33", "B. 34", "C. 35", "D. 36"], "answer": 1, "hint": "Lập bất phương trình 180 + 65n ≤ 2,400 và lấy phần nguyên lớn nhất của n.", "explanation": "Ta có 180 + 65n ≤ 2,400 ⇔ 65n ≤ 2,220 ⇔ n ≤ 2,220 / 65 ≈ 34.15. Vì số thùng hàng là số nguyên nên tối đa chở được 34 thùng (Đáp án B)."}, {"id": "math-alg-q8", "type": "Linear Function Table", "passage": "The linear function f satisfies f(2) = 11 and f(6) = 27. What is the value of f(10)?", "question": "Calculate f(10).", "options": ["A. 38", "B. 41", "C. 43", "D. 47"], "answer": 2, "hint": "Vì x tăng đều từ 2 → 6 → 10 (mỗi bước +4), giá trị hàm tuyến tính f(x) cũng tăng một lượng không đổi!", "explanation": "Khi x tăng từ 2 lên 6 (Δx = 4), f(x) tăng từ 11 lên 27 (Δy = +16). Do hàm bậc nhất có tốc độ thay đổi không đổi, khi x tăng thêm 4 đơn vị từ 6 lên 10, f(x) cũng tăng thêm 16: f(10) = 27 + 16 = 43 (Đáp án C)."}, {"id": "math-alg-q9", "type": "Absolute Value Equation", "passage": "What is the sum of all solutions to the equation |2x − 7| = 13?", "question": "Find the sum of the solutions.", "options": ["A. −3", "B. 7", "C. 10", "D. 13"], "answer": 1, "hint": "Giải 2 trường hợp: 2x − 7 = 13 và 2x − 7 = −13, hoặc dùng tính chất đối xứng quanh tâm x = 7/2.", "explanation": "Trường hợp 1: 2x − 7 = 13 ⇒ 2x = 20 ⇒ x₁ = 10. Trường hợp 2: 2x − 7 = −13 ⇒ 2x = −6 ⇒ x₂ = −3. Tổng các nghiệm là x₁ + x₂ = 10 + (−3) = 7 (Đáp án B)."}, {"id": "math-alg-q10", "type": "Identity Equation (Infinitely Many Solutions)", "passage": "In the equation 4(3x + a) − 2x = bx − 20, a and b are constants. If the equation is true for all real values of x, what is the value of a + b?", "question": "Find the value of a + b.", "options": ["A. 5", "B. 10", "C. 15", "D. −5"], "answer": 0, "hint": "Rút gọn vế trái thành (10x + 4a) rồi đồng nhất hệ số của x và hệ số tự do ở hai vế.", "explanation": "Khai triển vế trái: 12x + 4a − 2x = 10x + 4a. Để phương trình nghiệm đúng với mọi x: b = 10 và 4a = −20 ⇒ a = −5. Vậy a + b = −5 + 10 = 5 (Đáp án A)."}]}, {"id": "math-adv", "section": "Math", "code": "MATH-02", "title": "Advanced Math (Toán Nâng cao)", "weight": "35% phần Math (~13–15 câu/đề)", "summary": "Hàm số và phương trình bậc hai, định lý Viète, biệt thức Δ, hàm số mũ tăng trưởng/suy giảm, biến đổi biểu thức đại số, đa thức và phương trình chứa căn/phân thức.", "theory": {"overview": "Advanced Math cùng với Algebra chiếm tới 70% điểm số Toán SAT. Các câu hỏi nâng cao ở cuối Module 2 thường xoay quanh đỉnh của parabol, số nghiệm thực của hệ đường thẳng - parabol (dùng biệt thức Δ), định lý Viète và mô hình hàm số mũ.", "rules": [{"name": "1. Ba dạng của Hàm số bậc hai (Quadratic Forms)", "desc": "• Dạng chuẩn (Standard form): y = ax² + bx + c (cho biết y-intercept là c; hoành độ đỉnh h = −b/(2a)).\n• Dạng đỉnh (Vertex form): y = a(x − h)² + k (cho biết ngay tọa độ đỉnh (h, k) — giá trị cực tiểu/cực đại là k khi x = h).\n• Dạng tích (Factored form): y = a(x − r₁)(x − r₂) (cho biết ngay hai nghiệm x-intercepts là r₁ và r₂)."}, {"name": "2. Biệt thức Δ và Định lý Viète cho ax² + bx + c = 0", "desc": "• Biệt thức Δ = b² − 4ac: Δ > 0 (2 nghiệm thực phân biệt), Δ = 0 (1 nghiệm thực / tiếp xúc), Δ < 0 (vô nghiệm thực).\n• Tổng hai nghiệm: x₁ + x₂ = −b/a.\n• Tích hai nghiệm: x₁ · x₂ = c/a."}, {"name": "3. Hàm số mũ (Exponential Functions) f(t) = a · (1 ± r)^(t/k)", "desc": "• 'a' là giá trị ban đầu (khi t = 0).\n• '1 + r' là hệ số tăng trưởng (growth factor) với r là tỷ lệ phần trăm tăng; '1 − r' là hệ số suy giảm (decay factor).\n• Số mũ 't/k' cho biết chu kỳ thay đổi xảy ra sau mỗi k đơn vị thời gian t."}, {"name": "4. Nghiệm ngoại lai của Phương trình chứa căn (Extraneous Solutions)", "desc": "Với phương trình dạng √(ax + b) = x − c, sau khi bình phương hai vế tìm nghiệm, BẮT BUỘC phải thử lại điều kiện x − c ≥ 0 để loại nghiệm ngoại lai."}], "traps": ["Bẫy Vertex Form: Trong y = 3(x + 4)² − 7, đỉnh là (−4, −7) chứ không phải (4, −7).", "Bẫy Tổng nghiệm của phương trình bậc hai: Nếu Δ < 0 thì phương trình không có nghiệm thực, nhưng trong SAT các câu hỏi 'sum of solutions' của phương trình bậc hai có Δ > 0 luôn dùng ngay −b/a trong 3 giây!"], "example": {"passage": "What is the minimum value of the function f(x) = 2x² − 12x + 23?", "question": "Find the minimum value of f(x).", "analysis": "Hoành độ đỉnh h = −b/(2a) = −(−12)/(2·2) = 3. Giá trị cực tiểu là tung độ đỉnh k = f(3) = 2(3²) − 12(3) + 23 = 18 − 36 + 23 = 5."}}, "exercises": [{"id": "math-adv-q1", "type": "Vieta's Formulas (Sum of Solutions)", "passage": "What is the sum of the solutions to the quadratic equation 3x² − 24x + 19 = 0?", "question": "Select the sum of the solutions.", "options": ["A. −8", "B. 19/3", "C. 8", "D. 24"], "answer": 2, "hint": "Áp dụng công thức Viète: Tổng hai nghiệm x₁ + x₂ = −b/a.", "explanation": "Kiểm tra Δ = (−24)² − 4(3)(19) = 576 − 228 = 348 > 0 (có 2 nghiệm thực). Theo định lý Viète, tổng hai nghiệm là −b/a = −(−24)/3 = 8 (Đáp án C)."}, {"id": "math-adv-q2", "type": "Quadratic Vertex / Maximum", "passage": "The height h(t), in meters above the ground, of a projectile launched vertically is given by h(t) = −5t² + 30t + 15, where t is the time in seconds after launch. What is the maximum height, in meters, reached by the projectile?", "question": "Calculate the maximum height.", "options": ["A. 3", "B. 45", "C. 60", "D. 75"], "answer": 2, "hint": "Đề hỏi 'maximum height' (tung độ đỉnh k), không phải thời điểm đạt độ cao cực đại (t = 3).", "explanation": "Thời điểm đạt độ cao cực đại là t = −b/(2a) = −30/(2 · (−5)) = 3 giây. Thay t = 3 vào h(t): h(3) = −5(3²) + 30(3) + 15 = −45 + 90 + 15 = 60 mét (Đáp án C)."}, {"id": "math-adv-q3", "type": "Discriminant (Single Intersection)", "passage": "In the xy-plane, the parabola y = x² − 6x + k intersects the line y = 2x − 7 at exactly one point. What is the value of the constant k?", "question": "Find the value of k.", "options": ["A. 7", "B. 9", "C. 11", "D. 16"], "answer": 1, "hint": "Cho x² − 6x + k = 2x − 7 ⇔ x² − 8x + (k + 7) = 0, rồi đặt biệt thức Δ = 0.", "explanation": "Phương trình hoành độ giao điểm: x² − 6x + k = 2x − 7 ⇔ x² − 8x + (k + 7) = 0. Để cắt tại đúng 1 điểm (tiếp xúc), Δ = (−8)² − 4(1)(k + 7) = 0 ⇔ 64 − 4(k + 7) = 0 ⇔ k + 7 = 16 ⇔ k = 9 (Đáp án B)."}, {"id": "math-adv-q4", "type": "Exponential Growth Period", "passage": "A culture of photosynthetic algae initially contains 400 cells and triples in population every 6 hours. Which function P(t) represents the number of algae cells after t hours?", "question": "Select the correct exponential model.", "options": ["A. P(t) = 400(3)^(6t)", "B. P(t) = 400(3)^(t/6)", "C. P(t) = 400(6)^(t/3)", "D. P(t) = 1,200^(t/6)"], "answer": 1, "hint": "Giá trị ban đầu là 400, hệ số nhân là 3, và chu kỳ nhân ba là mỗi 6 giờ (số mũ t/6).", "explanation": "Sau mỗi 6 giờ (khi t = 6, 12, 18...), số mũ phải tăng thêm 1 đơn vị để nhân với cơ số 3. Do đó hàm số đúng là P(t) = 400(3)^(t/6) (Đáp án B)."}, {"id": "math-adv-q5", "type": "Radical Equations & Extraneous Roots", "passage": "What are all real solutions to the equation √(2x + 15) = x + 6?", "question": "Identify the valid real solution(s).", "options": ["A. −3 only", "B. −7 only", "C. −3 and −7", "D. The equation has no real solution."], "answer": 0, "hint": "Bình phương hai vế tìm nghiệm, sau đó kiểm tra điều kiện vế phải x + 6 ≥ 0!", "explanation": "Điều kiện: x + 6 ≥ 0 ⇔ x ≥ −6. Bình phương hai vế: 2x + 15 = (x + 6)² = x² + 12x + 36 ⇔ x² + 10x + 21 = 0 ⇔ (x + 3)(x + 7) = 0 ⇒ x = −3 hoặc x = −7. Đối chiếu điều kiện x ≥ −6, loại nghiệm ngoại lai x = −7, chỉ nhận x = −3 (Đáp án A)."}, {"id": "math-adv-q6", "type": "Rational Expressions", "passage": "For all x > 3, which of the following is equivalent to:\n(2x² − 18) / (x² − x − 6) ?", "question": "Simplify the rational expression.", "options": ["A. 2(x − 3) / (x + 2)", "B. 2(x + 3) / (x + 2)", "C. (2x + 3) / (x + 2)", "D. 3"], "answer": 1, "hint": "Phân tích tử số 2(x² − 9) = 2(x − 3)(x + 3) và mẫu số (x − 3)(x + 2).", "explanation": "Tử số: 2x² − 18 = 2(x² − 9) = 2(x − 3)(x + 3). Mẫu số: x² − x − 6 = (x − 3)(x + 2). Rút gọn nhân tử chung (x − 3) (vì x > 3), ta được 2(x + 3)/(x + 2) (Đáp án B)."}, {"id": "math-adv-q7", "type": "Polynomial Remainder Theorem", "passage": "When the polynomial P(x) = 2x³ − kx² + 5x − 8 is divided by (x − 2), the remainder is 6. What is the value of the constant k?", "question": "Find the value of k.", "options": ["A. 1", "B. 2", "C. 3", "D. 4"], "answer": 1, "hint": "Theo định lý Bézout (Remainder Theorem), số dư khi chia P(x) cho (x − 2) chính bằng P(2).", "explanation": "Ta có P(2) = 6 ⇔ 2(2³) − k(2²) + 5(2) − 8 = 6 ⇔ 16 − 4k + 10 − 8 = 6 ⇔ 18 − 4k = 6 ⇔ 4k = 12 ⇔ k = 3... Khoan! Kiểm tra lại: 16 + 10 − 8 = 18; 18 − 4k = 6 ⇒ 4k = 12 ⇒ k = 3! Vậy đáp án đúng là C (k = 3)."}, {"id": "math-adv-q8", "type": "Fractional Exponents", "passage": "If x > 0 and (x^(5/4) · √x) / x^(1/2) = x^k, what is the value of k?", "question": "Determine the exponent k.", "options": ["A. 3/4", "B. 5/4", "C. 7/4", "D. 9/4"], "answer": 1, "hint": "Chú ý √x chính là x^(1/2), nên √x ở tử và x^(1/2) ở mẫu triệt tiêu nhau!", "explanation": "Vì √x = x^(1/2), biểu thức rút gọn ngay phần x^(1/2) ở tử và mẫu, còn lại x^(5/4). Do đó k = 5/4 (Đáp án B)."}, {"id": "math-adv-q9", "type": "Exponential Decay Percentage", "passage": "The value V(t), in dollars, of a laboratory spectrometer t years after purchase is modeled by V(t) = 45,000(0.84)^t. By what percentage does the value of the spectrometer decrease each year?", "question": "Find the annual percentage decrease.", "options": ["A. 16%", "B. 45%", "C. 55%", "D. 84%"], "answer": 0, "hint": "Hệ số suy giảm là 0.84 = 1 − r. Đề hỏi phần trăm GIẢM đi (r), không phải phần trăm còn lại (84%).", "explanation": "Ta có 1 − r = 0.84 ⇒ r = 0.16 = 16%. Như vậy mỗi năm giá trị máy quang phổ giảm đi 16% (Đáp án A)."}, {"id": "math-adv-q10", "type": "Difference of Squares", "passage": "If x² − y² = 72 and x − y = 6, what is the value of x + 2y?", "question": "Calculate the value of x + 2y.", "options": ["A. 12", "B. 15", "C. 18", "D. 21"], "answer": 1, "hint": "Dùng hằng đẳng thức x² − y² = (x − y)(x + y) để tìm x + y trước.", "explanation": "Ta có x + y = (x² − y²)/(x − y) = 72/6 = 12. Kết hợp x − y = 6 và x + y = 12, suy ra x = 9 và y = 3. Khi đó x + 2y = 9 + 2(3) = 15 (Đáp án B)."}]}, {"id": "math-psda", "section": "Math", "code": "MATH-03", "title": "Problem-Solving & Data Analysis (Dữ liệu & Thống kê)", "weight": "15% phần Math (~5–7 câu/đề)", "summary": "Tỷ lệ, phần trăm tăng/giảm liên tiếp, thống kê mô tả (Mean, Median, Range, Standard Deviation), xác suất có điều kiện từ bảng hai chiều và suy luận thống kê (Margin of Error).", "theory": {"overview": "Problem-Solving and Data Analysis kiểm tra tư duy định lượng thực tiễn: tính phần trăm thay đổi, hiểu bản chất của trung bình (Mean), trung vị (Median) và độ lệch chuẩn (Standard Deviation) mà không cần tính tay phức tạp.", "rules": [{"name": "1. Thay đổi Phần trăm liên tiếp (Successive Percent Change)", "desc": "Tăng a% rồi giảm b% KHÔNG được cộng trừ phần trăm trực tiếp! Phải nhân hệ số: Giá trị mới = Giá trị gốc × (1 + a/100) × (1 − b/100)."}, {"name": "2. Mean vs. Median khi có Giá trị ngoại lai (Outliers)", "desc": "• Mean (Trung bình cộng) rất nhạy cảm với giá trị cực đại/cực tiểu (Outliers): thêm một số cực lớn sẽ kéo Mean tăng mạnh.\n• Median (Trung vị - số đứng giữa khi xếp tăng dần) rất bền vững (resistant) trước các giá trị ngoại lai."}, {"name": "3. Độ lệch chuẩn (Standard Deviation - SD)", "desc": "Trong SAT, bạn KHÔNG bao giờ phải tính công thức SD bằng tay! Chỉ cần nhớ: SD đo mức độ phân tán (spread) của dữ liệu quanh giá trị trung bình. Tập dữ liệu nào có các số chụm sát nhau thì SD nhỏ; tập nào rải xa nhau thì SD lớn. Cộng/trừ cùng một hằng số k vào mọi phần tử KHÔNG làm thay đổi SD!"}, {"name": "4. Xác suất có điều kiện & Biên độ sai số (Margin of Error)", "desc": "• P(A | B) = (Số phần tử thuộc cả A và B) / (Tổng số phần tử của nhóm điều kiện B).\n• Khi kích thước mẫu khảo sát ngẫu nhiên (Sample size n) TĂNG lên, biên độ sai số (Margin of Error) sẽ GIẢM xuống."}], "traps": ["Bẫy mẫu số xác suất: Đọc thật kỹ cụm 'If one of the [Group B] is selected at random...' — mẫu số chỉ là tổng của Group B, không phải tổng toàn bảng!", "Bẫy suy rộng tổng thể (Generalization): Khảo sát chỉ lấy mẫu ở học sinh lớp 12 một trường thì chỉ suy rộng được cho học sinh lớp 12 trường đó, không suy rộng được cho toàn quốc."], "example": {"passage": "Data Set A consists of the 5 integers {10, 12, 14, 16, 18}. Data Set B is formed by adding 50 to each number in Data Set A: {60, 62, 64, 66, 68}. How do the standard deviations of the two sets compare?", "question": "Compare the standard deviation of Set A and Set B.", "analysis": "Khoảng cách giữa các phần tử trong cả hai tập đều cách đều nhau 2 đơn vị. Việc cộng thêm 50 vào mọi phần tử chỉ dịch chuyển toàn bộ tập dữ liệu mà không làm thay đổi độ phân tán, nên Standard Deviation của Set A và Set B bằng nhau."}}, "exercises": [{"id": "math-psda-q1", "type": "Successive Percent Change", "passage": "The price of a laptop was increased by 20% in November and then discounted by 25% during a December clearance sale. The final clearance price is what percent of the original price before November?", "question": "Select the correct percentage.", "options": ["A. 85%", "B. 90%", "C. 95%", "D. 100%"], "answer": 1, "hint": "Nhân hai hệ số thay đổi: 1.20 × 0.75.", "explanation": "Gọi giá gốc là P. Sau khi tăng 20%, giá là 1.20P. Sau khi giảm tiếp 25%, giá cuối cùng là 1.20P × (1 − 0.25) = 1.20 × 0.75P = 0.90P, tức bằng 90% giá ban đầu (Đáp án B)."}, {"id": "math-psda-q2", "type": "Mean vs. Median with Outlier", "passage": "Nine houses on a suburban street have the following market values (in thousands of dollars):\n310, 325, 330, 340, 350, 360, 375, 380, 390.\nSuppose a tenth house valued at $1,850 thousand is built on the street. Which statement correctly describes the effect of adding this tenth house to the data set?", "question": "Compare the change in mean and median.", "options": ["A. Both the mean and the median remain unchanged.", "B. The median increases by a much greater amount than the mean does.", "C. The mean increases by a much greater amount than the median does.", "D. Both the mean and the median decrease."], "answer": 2, "hint": "Giá trị 1,850 là một outlier cực lớn so với khoảng 310–390.", "explanation": "Ban đầu Median là số thứ 5 (350) và Mean là 351.1. Khi thêm 1,850, Median mới là trung bình của số thứ 5 và thứ 6: (350 + 360)/2 = 355 (chỉ tăng 5), trong khi Mean mới là (3,160 + 1,850)/10 = 501 (tăng gần 150). Vậy Mean tăng mạnh hơn rất nhiều so với Median (Đáp án C)."}, {"id": "math-psda-q3", "type": "Conditional Probability (Two-Way Table)", "passage": "Clinical Trial Results for Allergy Medication:\n• Group A (Active Drug): Improved = 144 | No Improvement = 36 | Total = 180\n• Group B (Placebo): Improved = 56 | No Improvement = 64 | Total = 120\n• Total: Improved = 200 | No Improvement = 100 | Grand Total = 300\n\nIf a participant who showed improvement is selected at random, what is the probability that the participant received the active drug (Group A)?", "question": "Calculate the conditional probability.", "options": ["A. 144 / 300", "B. 144 / 200", "C. 144 / 180", "D. 200 / 300"], "answer": 1, "hint": "Nhóm điều kiện đứng sau 'If a participant... is selected' là 'a participant who showed improvement' (Tổng = 200).", "explanation": "Mẫu số là tổng số người có cải thiện ('who showed improvement' = 200). Tử số là số người vừa cải thiện vừa dùng thuốc thật (Group A = 144). Vậy xác suất là 144/200 (Đáp án B)."}, {"id": "math-psda-q4", "type": "Standard Deviation Comparison", "passage": "Consider two data sets of 6 measurements each:\nSet X: {18, 19, 20, 20, 21, 22}\nSet Y: {10, 14, 20, 20, 26, 30}\nWhich statement about the means and standard deviations of Set X and Set Y is true?", "question": "Compare the means and standard deviations.", "options": ["A. The means are equal, and the standard deviation of Set X is greater than that of Set Y.", "B. The means are equal, and the standard deviation of Set Y is greater than that of Set X.", "C. Set Y has a greater mean and a smaller standard deviation than Set X.", "D. Both the means and the standard deviations are equal."], "answer": 1, "hint": "Cả hai tập đều đối xứng quanh số 20, nhưng tập nào có các phần tử trải rộng xa số 20 hơn?", "explanation": "Cả hai tập đều đối xứng quanh tâm 20 nên có cùng Mean = 20. Các giá trị của Set Y (từ 10 đến 30) phân tán xa tâm 20 hơn nhiều so với Set X (từ 18 đến 22), nên Standard Deviation của Set Y lớn hơn Set X (Đáp án B)."}, {"id": "math-psda-q5", "type": "Margin of Error & Confidence Interval", "passage": "A random sample of 500 registered voters in a city of 240,000 voters showed that 58% support a new public transit bond, with an associated margin of error of 4% at the 95% confidence level. Which of the following is the most appropriate conclusion?", "question": "Select the valid statistical inference.", "options": ["A. Exactly 58% of all 240,000 registered voters in the city support the bond.", "B. It is plausible that between 54% and 62% of all registered voters in the city support the bond.", "C. Between 54% and 62% of the 500 surveyed voters were undecided.", "D. If another sample of 100 voters were taken, the margin of error would decrease to 2%."], "answer": 1, "hint": "Khoảng ước lượng hợp lý cho tổng thể nằm trong khoảng (Tỷ lệ mẫu − Margin of Error) đến (Tỷ lệ mẫu + Margin of Error).", "explanation": "Với tỷ lệ mẫu 58% và biên độ sai số ±4%, ta có cơ sở ước lượng tỷ lệ ủng hộ thực tế trong toàn bộ cử tri thành phố nằm trong khoảng từ 58% − 4% = 54% đến 58% + 4% = 62% (Đáp án B)."}, {"id": "math-psda-q6", "type": "Weighted Average", "passage": "In a chemistry course, Section 1 has 20 students with an average exam score of 82, and Section 2 has 30 students with an average exam score of 87. What is the combined average exam score for all 50 students across both sections?", "question": "Calculate the combined mean score.", "options": ["A. 84.0", "B. 84.5", "C. 85.0", "D. 85.5"], "answer": 2, "hint": "Tính tổng điểm của cả 50 học sinh: (20 × 82 + 30 × 87) rồi chia cho 50.", "explanation": "Tổng điểm Section 1 = 20 × 82 = 1,640. Tổng điểm Section 2 = 30 × 87 = 2,610. Điểm trung bình chung của 50 học sinh là (1,640 + 2,610) / 50 = 4,250 / 50 = 85.0 (Đáp án C)."}, {"id": "math-psda-q7", "type": "Unit Conversion & Rates", "passage": "An autonomous underwater vehicle travels at a constant speed of 2.5 meters per second. At this rate, how many kilometers does the vehicle travel in 2 hours? (1 kilometer = 1,000 meters)", "question": "Convert the rate to kilometers in 2 hours.", "options": ["A. 5", "B. 9", "C. 15", "D. 18"], "answer": 3, "hint": "2 giờ = 2 × 3,600 = 7,200 giây.", "explanation": "Trong 2 giờ (7,200 giây), quãng đường đi được là 2.5 m/s × 7,200 s = 18,000 mét = 18 km (Đáp án D)."}, {"id": "math-psda-q8", "type": "Scatterplot & Line of Best Fit Residual", "passage": "A line of best fit for a scatterplot relating annual rainfall x, in centimeters, to wheat yield y, in metric tons per hectare, has the equation ŷ = 0.06x + 1.4. For a farm that received 50 centimeters of rainfall, the actual wheat yield was 4.9 metric tons per hectare. What is the residual (actual minus predicted) for this farm?", "question": "Find the residual value.", "options": ["A. −0.5", "B. 0.5", "C. 4.4", "D. 4.9"], "answer": 1, "hint": "Tính giá trị dự đoán ŷ khi x = 50 trước, rồi lấy Actual − Predicted.", "explanation": "Giá trị dự đoán từ đường hồi quy khi x = 50 là ŷ = 0.06(50) + 1.4 = 3.0 + 1.4 = 4.4. Phần dư (Residual) = Giá trị thực tế − Giá trị dự đoán = 4.9 − 4.4 = 0.5 (Đáp án B)."}, {"id": "math-psda-q9", "type": "Ratio and Proportion", "passage": "A bronze alloy consists of copper and tin in a mass ratio of 22 to 3. How many kilograms of copper are required to produce 150 kilograms of this bronze alloy?", "question": "Calculate the mass of copper needed.", "options": ["A. 18", "B. 120", "C. 132", "D. 138"], "answer": 2, "hint": "Tổng số phần bằng nhau là 22 + 3 = 25 phần.", "explanation": "Tổng số phần khối lượng là 22 + 3 = 25 phần. Khối lượng đồng (copper) chiếm 22/25 tổng khối lượng hợp kim: (22/25) × 150 = 22 × 6 = 132 kg (Đáp án C)."}, {"id": "math-psda-q10", "type": "Frequency Table Median", "passage": "Number of Books Read by 25 Book Club Members Last Month:\n• 1 book: 4 members\n• 2 books: 7 members\n• 3 books: 6 members\n• 4 books: 5 members\n• 5 books: 3 members\nWhat is the median number of books read by the 25 members?", "question": "Find the median from the frequency distribution.", "options": ["A. 2", "B. 2.5", "C. 3", "D. 3.5"], "answer": 2, "hint": "Với N = 25 (số lẻ), trung vị là giá trị ở vị trí thứ (25 + 1)/2 = 13 khi xếp tăng dần.", "explanation": "Tần số tích lũy: vị trí 1–4 đọc 1 cuốn; vị trí 5–11 (4 + 7 = 11) đọc 2 cuốn; vị trí 12–17 (11 + 6 = 17) đọc 3 cuốn. Phần tử thứ 13 nằm trong nhóm đọc 3 cuốn, nên Median = 3 (Đáp án C)."}]}, {"id": "math-geom", "section": "Math", "code": "MATH-04", "title": "Geometry and Trigonometry (Hình học & Lượng giác)", "weight": "15% phần Math (~5–7 câu/đề)", "summary": "Công thức diện tích và thể tích khối 3D, tam giác đồng dạng, tam giác vuông đặc biệt (30°-60°-90° và 45°-45°-90°), lượng giác vuông (SOH-CAH-TOA, sin x = cos(90° − x)) và phương trình đường tròn.", "theory": {"overview": "Geometry and Trigonometry là phần dễ lấy trọn điểm nếu bạn nắm chắc 4 mảng kiến thức xuất hiện trong hầu hết mọi đề thi Digital SAT: Tam giác đồng dạng, Lượng giác hai góc phụ nhau, Phương trình đường tròn (Completing the Square) và Độ dài cung tròn theo Radian.", "rules": [{"name": "1. Hai góc phụ nhau trong Tam giác vuông (Complementary Angles)", "desc": "Trong tam giác vuông ABC vuông tại C, hai góc nhọn A + B = 90°. Ta luôn có: sin(A) = cos(B) và cos(A) = sin(B), tức là sin(x°) = cos(90° − x°)."}, {"name": "2. Phương trình Đường tròn & Kỹ thuật Ghép bình phương", "desc": "• Phương trình chuẩn: (x − h)² + (y − k)² = r² với tâm I(h, k) và bán kính r.\n• Khi đề cho dạng khai triển x² + bx + y² + dy = c, ta cộng thêm (b/2)² và (d/2)² vào cả hai vế: (x + b/2)² + (y + d/2)² = c + (b/2)² + (d/2)² = r²."}, {"name": "3. Độ dài cung tròn & Diện tích hình quạt (Arc Length & Sector Area)", "desc": "• Theo độ (Degrees): Tỷ lệ quạt = θ / 360° = (Độ dài cung s) / (2πr) = (Diện tích quạt) / (πr²).\n• Theo Radian: s = r · θ và A_sector = (1/2)r²θ (với π rad = 180°)."}, {"name": "4. Tỷ lệ Đồng dạng (Similar Figures Scale Factor k)", "desc": "Nếu hai hình đồng dạng theo tỷ số kích thước dài là k, thì:\n• Tỷ số Chu vi = k\n• Tỷ số Diện tích = k²\n• Tỷ số Thể tích = k³"}], "traps": ["Bẫy Đường kính vs. Bán kính: Trong phương trình (x − 2)² + (y + 5)² = 36, bán kính r = 6, nhưng đề rất hay hỏi 'What is the diameter (đường kính)?' (2r = 12).", "Bẫy Tam giác đồng dạng: Nếu sin(A) của tam giác nhỏ bằng 3/5 và tam giác lớn đồng dạng với tam giác nhỏ theo tỷ số gấp 4 lần, thì sin của góc tương ứng ở tam giác lớn VẪN BẰNG 3/5 (tỷ số lượng giác chỉ phụ thuộc vào độ lớn góc, không phụ thuộc kích thước tam giác!)."], "example": {"passage": "In the xy-plane, a circle is defined by x² − 8x + y² + 6y = 24. What is the radius of the circle?", "question": "Find the radius r.", "analysis": "Ghép bình phương: (x² − 8x + 16) + (y² + 6y + 9) = 24 + 16 + 9 ⇔ (x − 4)² + (y + 3)² = 49 = 7². Vậy bán kính r = 7."}}, "exercises": [{"id": "math-geom-q1", "type": "Complementary Trig Identity", "passage": "In right triangle ABC, angle C is a right angle (90°) and sin(A) = 8/17. What is the value of cos(B) + sin(B)?", "question": "Calculate cos(B) + sin(B).", "options": ["A. 16/17", "B. 23/17", "C. 25/17", "D. 32/17"], "answer": 1, "hint": "Trong tam giác vuông tại C, cos(B) = sin(A) = 8/17. Dùng bộ ba Pythagoras 8 - 15 - 17 để tìm sin(B).", "explanation": "Vì A + B = 90° nên cos(B) = sin(A) = 8/17. Theo định lý Pythagoras, cạnh kề góc A (đối diện góc B) bằng √(17² − 8²) = 15, nên sin(B) = 15/17. Vậy cos(B) + sin(B) = 8/17 + 15/17 = 23/17 (Đáp án B)."}, {"id": "math-geom-q2", "type": "Circle Equation (Completing the Square)", "passage": "The equation x² + 10x + y² − 12y = 39 defines a circle in the xy-plane. What is the length of the circle's diameter?", "question": "Find the diameter of the circle.", "options": ["A. 10", "B. 16", "C. 20", "D. 100"], "answer": 2, "hint": "Cộng (10/2)² = 25 và (−12/2)² = 36 vào vế phải để tìm r², rồi nhớ nhân đôi bán kính r để ra đường kính!", "explanation": "Ghép bình phương: (x + 5)² + (y − 6)² = 39 + 25 + 36 = 100 = 10². Suy ra bán kính r = 10. Đề hỏi đường kính (diameter) nên d = 2r = 20 (Đáp án C)."}, {"id": "math-geom-q3", "type": "Similar Triangles & Trig Ratio Trap", "passage": "Right triangle DEF is similar to right triangle JKL, where vertices D, E, and F correspond to vertices J, K, and L, respectively, and angle E and angle K are right angles. In triangle DEF, DE = 9 and EF = 12. If each side of triangle JKL is 3 times the length of the corresponding side of triangle DEF, what is the value of tan(J)?", "question": "Determine the value of tan(J).", "options": ["A. 3/4", "B. 4/3", "C. 9/4", "D. 4"], "answer": 1, "hint": "Hai tam giác đồng dạng thì góc J = góc D, nên tan(J) = tan(D) = đối / kề = EF / DE!", "explanation": "Tỷ số lượng giác không thay đổi khi phóng to tam giác đồng dạng. Vì góc J tương ứng với góc D, ta có tan(J) = tan(D) = EF / DE = 12 / 9 = 4/3 (Đáp án B)."}, {"id": "math-geom-q4", "type": "Arc Length & Central Angle in Radians", "passage": "In a circle with radius 12 centimeters, a central angle intercepts an arc of length 8π centimeters. What is the radian measure of the central angle?", "question": "Find the central angle θ in radians.", "options": ["A. π/3", "B. 2π/3", "C. 3π/2", "D. 4π/3"], "answer": 1, "hint": "Áp dụng công thức độ dài cung theo radian: s = r · θ.", "explanation": "Từ công thức s = rθ, ta có 8π = 12 · θ ⇒ θ = 8π / 12 = 2π/3 radian (Đáp án B)."}, {"id": "math-geom-q5", "type": "Volume of Cylinder & Cone", "passage": "A right circular cylinder and a right circular cone have the same base radius r = 6 inches. If the volume of the cylinder is equal to the volume of the cone, and the height of the cylinder is 8 inches, what is the height, in inches, of the cone?", "question": "Find the height of the cone.", "options": ["A. 8", "B. 16", "C. 24", "D. 32"], "answer": 2, "hint": "V_cylinder = πr²h₁ và V_cone = (1/3)πr²h₂.", "explanation": "Cho πr²(8) = (1/3)πr²h_cone. Chia cả hai vế cho πr², ta được 8 = (1/3)h_cone ⇒ h_cone = 24 inches (Đáp án C)."}, {"id": "math-geom-q6", "type": "Special Right Triangle (30-60-90)", "passage": "An equilateral triangle has a perimeter of 36 centimeters. What is the area, in square centimeters, of the triangle?", "question": "Calculate the area of the equilateral triangle.", "options": ["A. 18√3", "B. 36√3", "C. 54√3", "D. 72√3"], "answer": 1, "hint": "Mỗi cạnh tam giác đều là a = 36/3 = 12 cm. Đường cao chia tam giác đều thành 2 tam giác vuông 30°-60°-90° có cao h = (a√3)/2.", "explanation": "Cạnh tam giác đều a = 12 cm. Đường cao h = 6√3 cm. Diện tích S = (1/2) · a · h = (1/2) · 12 · 6√3 = 36√3 cm² (Đáp án B)."}, {"id": "math-geom-q7", "type": "Area Scale Factor of Similar Figures", "passage": "Triangle PQR is similar to triangle STU such that the length of side ST is 2.5 times the length of corresponding side PQ. If the area of triangle PQR is 16 square centimeters, what is the area, in square centimeters, of triangle STU?", "question": "Calculate the area of triangle STU.", "options": ["A. 40", "B. 64", "C. 80", "D. 100"], "answer": 3, "hint": "Tỷ số diện tích bằng BÌNH PHƯƠNG tỷ số đồng dạng k² = (2.5)² = 6.25.", "explanation": "Tỷ số diện tích giữa hai tam giác đồng dạng bằng bình phương tỷ số cạnh tương ứng: Area(STU) = Area(PQR) × (2.5)² = 16 × 6.25 = 100 cm² (Đáp án D)."}, {"id": "math-geom-q8", "type": "Parallel Lines & Transversal Angles", "passage": "In a geometric figure, lines m and n are parallel and are intersected by a transversal line t. If one of the interior angles on the same side of the transversal measures (3x + 15)° and the other consecutive interior angle measures (2x − 10)°, what is the value of x?", "question": "Solve for x.", "options": ["A. 25", "B. 35", "C. 40", "D. 45"], "answer": 1, "hint": "Hai góc trong cùng phía (consecutive interior angles) của hai đường thẳng song song có tổng bằng 180°.", "explanation": "Hai góc trong cùng phía bù nhau: (3x + 15) + (2x − 10) = 180 ⇔ 5x + 5 = 180 ⇔ 5x = 175 ⇔ x = 35 (Đáp án B)."}, {"id": "math-geom-q9", "type": "Sector Area Ratio", "passage": "A circle with center O has an area of 72π square inches. Sector AOB of this circle has a central angle of 50°. What is the area, in square inches, of sector AOB?", "question": "Find the area of sector AOB.", "options": ["A. 5π", "B. 8π", "C. 10π", "D. 12π"], "answer": 2, "hint": "Diện tích hình quạt bằng (50° / 360°) × Diện tích hình tròn.", "explanation": "Area(Sector) = (50 / 360) × 72π = (5 / 36) × 72π = 5 × 2π = 10π in² (Đáp án C)."}, {"id": "math-geom-q10", "type": "Circle Tangent & Point on Circle", "passage": "In the xy-plane, a circle has center C(3, −2) and passes through the point P(7, 1). Which of the following is the equation of the circle?", "question": "Select the correct circle equation.", "options": ["A. (x − 3)² + (y + 2)² = 5", "B. (x − 3)² + (y + 2)² = 25", "C. (x + 3)² + (y − 2)² = 25", "D. (x − 7)² + (y − 1)² = 25"], "answer": 1, "hint": "Tâm (3, −2) cho vế trái là (x − 3)² + (y + 2)². Tính r² bằng bình phương khoảng cách CP.", "explanation": "Bình phương bán kính là r² = (7 − 3)² + (1 − (−2))² = 4² + 3² = 16 + 9 = 25. Với tâm C(3, −2), phương trình đường tròn là (x − 3)² + (y + 2)² = 25 (Đáp án B)."}]}];
    const EXAMS_DATA = [{"id": "exam-1", "number": 1, "title": "Đề thi thử Digital SAT #1 — Foundation & Core Adaptive", "difficulty": "Chuẩn College Board (Standard)", "badge": "Đề chuẩn mở đầu", "desc": "Mô phỏng cấu trúc chuẩn Bluebook với độ khó cân bằng giữa các miền kiến thức Đọc - Viết và Toán học.", "modules": [{"id": "rw-m1", "name": "Section 1, Module 1: Reading and Writing", "shortName": "R&W Mod 1", "section": "Reading & Writing", "durationMinutes": 32, "directions": "The questions in this section address a number of important reading and writing skills. Each question includes one or more passages, which may include a table or graph. Read each passage and question carefully, and then choose the best answer to the question based on the passage(s).", "questions": [{"id": "e1-rw1-q1", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Antarctic ice cores preserve tiny bubbles of ancient atmosphere. Researchers noted that these findings help refine contemporary models of paleoclimatology ice cores.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. obscure", "B. corroborate", "C. fabricate", "D. repudiate"], "answer": 1, "explanation": "Bằng chứng từ lõi băng giúp 'củng cố/xác nhận' (corroborate) các mô hình khí hậu."}, {"id": "e1-rw1-q2", "domain": "Information and Ideas", "skill": "Inferences", "passage": "As alpine glaciers retreat, newly exposed rock surfaces weather rapidly and absorb carbon dioxide through silicate mineral reactions. However, stream-water measurements show that microbial activity in glacial meltwater releases methane at a rate that offsets nearly 80 percent of this silicate carbon sink, indicating that ______", "question": "Which choice most logically completes the text?", "options": ["A. glacial retreat has no measurable effect on local rock weathering.", "B. models calculating the net climate impact of retreating glaciers must account for meltwater greenhouse gas emissions alongside mineral carbon absorption.", "C. silicate minerals release more methane than meltwater microbes do.", "D. alpine glaciers will stop retreating once silicate weathering reaches equilibrium."], "answer": 1, "explanation": "Cần tính cả lượng hấp thụ CO2 của đá và lượng phát thải khí nhà kính từ vi sinh vật nước băng tan để đánh giá tác động ròng (Đáp án B)."}, {"id": "e1-rw1-q3", "domain": "Information and Ideas", "skill": "Command of Evidence (Quantitative)", "passage": "Solar Microgrid Efficiency Across Three Operating Temperatures (Study #1):\n• Panel Type Alpha: 25°C = 21.4% | 45°C = 18.1%\n• Panel Type Beta (Perovskite-Silicon): 25°C = 26.8% | 45°C = 25.9%\n\nEnergy engineers report that while all photovoltaic modules lose efficiency as ambient temperatures rise, Perovskite-Silicon (Type Beta) panels exhibit both higher baseline efficiency and superior thermal stability at 45°C compared to Type Alpha panels.", "question": "Which data from the study most directly support the engineers' report?", "options": ["A. At 25°C, Type Alpha achieves 21.4% efficiency, which is higher than its efficiency at 45°C.", "B. Type Beta starts at 26.8% at 25°C and retains 25.9% at 45°C (a drop of only 0.9%), whereas Type Alpha drops from 21.4% to 18.1%.", "C. Both panel types were tested at exactly 25°C and 45°C under laboratory illumination.", "D. Type Alpha's efficiency at 45°C is 18.1%."], "answer": 1, "explanation": "Đáp án B trích dẫn đầy đủ cả hiệu suất nền cao hơn ở 25°C lẫn mức sụt giảm nhiệt độ rất nhỏ (chỉ 0.9%) ở 45°C của Type Beta so với Type Alpha."}, {"id": "e1-rw1-q4", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "In early trials of autonomous marine gliders (Deployment #1), strong subsurface currents frequently pushed the craft off their programmed survey transects. ______ engineers integrated real-time Doppler velocity logs into the navigation software, enabling the gliders to compensate for lateral drift automatically.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. In response,", "B. Nonetheless,", "C. For example,", "D. Conversely,"], "answer": 0, "hint": "Câu 1 nêu vấn đề kỹ thuật; câu 2 nêu giải pháp khắc phục của các kỹ sư.", "explanation": "'In response,' (Để giải quyết vấn đề đó / Đáp lại thực trạng đó) nối hợp lý giữa sự cố trôi dạt ở câu 1 và cải tiến phần mềm điều hướng ở câu 2 (Đáp án A)."}, {"id": "e1-rw1-q5", "domain": "Standard English Conventions", "skill": "Boundaries & Punctuation", "passage": "The archival collection at the Uppsala University Library houses over 415 medieval botanical codices ______ researchers have digitized only a third of these illuminated manuscripts for public open-access repositories.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. codices, however,", "B. codices; however,", "C. codices however", "D. codices, yet; "], "answer": 1, "explanation": "Hai mệnh đề độc lập nối với trạng từ chuyển tiếp 'however' bắt buộc dùng dấu chấm phẩy trước và dấu phẩy sau: 'codices; however,' (Đáp án B)."}]}, {"id": "rw-m2", "name": "Section 1, Module 2: Reading and Writing (Adaptive)", "shortName": "R&W Mod 2", "section": "Reading & Writing", "durationMinutes": 32, "directions": "This is the second adaptive module of Reading and Writing. Answer every question carefully; there is no penalty for guessing.", "questions": [{"id": "e1-rw2-q1", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "Text 1:\nUrban sociologist Dr. Aris Thorne contends that converting downtown arterial roads into pedestrian-only plazas invariably reduces quarterly retail revenue for ground-floor merchants, because suburban customers rely on curbside parking to visit specialty shops (Case Study #1).\n\nText 2:\nEconomist Mei-Ling Zhou analyzed point-of-sale tax receipts across twelve cities before and after pedestrianization. She found that while drive-in purchases dipped during the first month of construction, total annual retail sales rose by 15% as foot traffic and outdoor dining dwell times increased.", "question": "Based on the texts, how would Zhou (Text 2) most likely characterize Thorne's conclusion in Text 1?", "options": ["A. As an accurate reflection of long-term tax receipt data across all twelve studied cities.", "B. As an overgeneralization that overlooks how increased pedestrian foot traffic more than compensates for reduced curbside parking over a full year.", "C. As proof that outdoor dining establishments should be relocated to suburban shopping malls.", "D. As a valid critique of public transit fare structures."], "answer": 1, "explanation": "Số liệu thực tế cả năm của Zhou (doanh thu tăng nhờ khách đi bộ và ăn uống ngoài trời) bác bỏ dự đoán bi quan của Thorne vốn chỉ nhìn vào việc giảm chỗ đỗ xe (Đáp án B)."}, {"id": "e1-rw2-q2", "domain": "Information and Ideas", "skill": "Command of Evidence (Textual)", "passage": "In a study of avian vocal learning (Cohort #1), neurobiologist Dr. Lucas Vance proposes that juvenile songbirds must hear adult tutor songs during a critical developmental window not merely to copy individual notes, but to calibrate the tempo boundaries between syllables.", "question": "Which finding from Vance's experiment, if true, would most directly support his hypothesis?", "options": ["A. Juvenile songbirds raised in acoustic isolation produced all the correct note frequencies of their species but sang them with erratic, uncoordinated pauses between syllables.", "B. Adult songbirds sang more frequently during spring mornings than during autumn afternoons.", "C. Juvenile songbirds fed a high-protein diet developed larger flight muscles than control birds did.", "D. Different species of finches inhabit distinct canopy heights in tropical rainforests."], "answer": 0, "explanation": "Nếu chim non không được nghe chim trưởng thành vẫn phát ra đúng tần số nốt nhưng lại bị rối loạn khoảng nghỉ/nhịp độ giữa các âm tiết ('erratic pauses between syllables'), điều đó chứng minh trực tiếp vai trò hiệu chỉnh nhịp độ (tempo boundaries) của chim thầy (Đáp án A)."}, {"id": "e1-rw2-q3", "domain": "Standard English Conventions", "skill": "Subject-Verb Agreement & Modifiers", "passage": "Calibrating the 6 interferometer mirrors inside the underground gravitational-wave detector ______ sub-nanometer precision so that passing seismic vibrations from distant ocean waves do not mask astrophysical signals.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. require", "B. requires", "C. have required", "D. are requiring"], "answer": 1, "explanation": "Chủ ngữ chính là danh động từ (gerund phrase) 'Calibrating the ... mirrors' (ngôi thứ ba số ít), không phải 'mirrors' hay 'detector'. Do đó động từ chia số ít là 'requires' (Đáp án B)."}, {"id": "e1-rw2-q4", "domain": "Standard English Conventions", "skill": "Dangling Modifier", "passage": "Synthesized from plant-derived monomers at temperatures below 82°C, ______ ", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. chemical engineers designed the new recyclable polymer to dissolve in mild acidic solutions.", "B. the new recyclable polymer dissolves cleanly when immersed in mild acidic solutions.", "C. mild acidic solutions can dissolve the new recyclable polymer completely.", "D. a breakthrough in sustainable packaging was achieved by the research team."], "answer": 1, "explanation": "Cụm phân từ mở đầu 'Synthesized from plant-derived monomers...' bổ nghĩa cho chất được tổng hợp, tức là 'the new recyclable polymer' phải đứng ngay sau dấu phẩy làm chủ ngữ (Đáp án B)."}, {"id": "e1-rw2-q5", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes (Archive #1):\n• Geothermal district heating circulates naturally warm subterranean water through insulated municipal pipes.\n• In Reykjavik, Iceland, geothermal wells supply space heating to 98% of residential buildings.\n• Transitioning from imported coal to geothermal heating between 1930 and 1970 eliminated winter smog in Reykjavik.\n• Today, the system prevents approximately 2.1 million metric tons of CO₂ emissions annually.", "question": "The student wants to emphasize both the historical and ongoing environmental benefits of Reykjavik's geothermal heating system. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Reykjavik's geothermal district heating system circulates warm subterranean water to 98% of the city's residential buildings.", "B. By replacing imported coal between 1930 and 1970, Reykjavik's geothermal heating system eliminated historical winter smog and continues to prevent 2.1 million metric tons of CO₂ emissions each year.", "C. Geothermal district heating uses insulated municipal pipes to transport subterranean water.", "D. Today, Reykjavik prevents 2.1 million metric tons of CO₂ emissions annually through district heating."], "answer": 1, "explanation": "Đáp án B kết hợp đầy đủ lợi ích môi trường trong lịch sử (xóa bỏ khói bụi than đá giai đoạn 1930–1970) VÀ lợi ích hiện tại (ngăn ngừa hàng triệu tấn CO₂ mỗi năm)."}]}, {"id": "math-m1", "name": "Section 2, Module 1: Math", "shortName": "Math Mod 1", "section": "Math", "durationMinutes": 35, "directions": "The questions in this section address a number of important math skills. Use of an integrated calculator is permitted for all questions. You may open the Reference Sheet at any time.", "questions": [{"id": "e1-m1-q1", "domain": "Algebra", "skill": "Linear Equations in One Variable", "passage": "If 5x − 4 = 2x + 11, what is the value of 4x + 5?", "question": "Select the correct value of 4x + 5.", "options": ["A. 5", "B. 21", "C. 25", "D. 31"], "answer": 2, "explanation": "Chuyển vế: 5x − 2x = 11 + 4 ⇔ 3x = 15 ⇔ x = 5. Thay x = 5 vào biểu thức 4x + 5 ta được 4(5) + 5 = 25 (Đáp án C)."}, {"id": "e1-m1-q2", "domain": "Algebra", "skill": "Systems of Two Linear Equations", "passage": "If (x, y) is the solution to the system of equations below:\n4x + 5y = 51\n5x + 4y = 48\nWhat is the value of x + y?", "question": "Calculate x + y.", "options": ["A. 9", "B. 11", "C. 14", "D. 99"], "answer": 1, "explanation": "Cộng vế theo vế hai phương trình: (4x + 5x) + (5y + 4y) = 51 + 48 ⇔ 9(x + y) = 99. Chia hai vế cho 9 ta được x + y = 11 (Đáp án B)."}, {"id": "e1-m1-q3", "domain": "Advanced Math", "skill": "Quadratic Functions & Vertex", "passage": "The function f is defined by f(x) = x² − 6x + 14. What is the minimum value of f(x)?", "question": "Find the minimum value of f(x).", "options": ["A. 3", "B. 5", "C. 14", "D. −6"], "answer": 1, "explanation": "Hoành độ đỉnh của parabol là x = −b/(2a) = 6/2 = 3 (hoặc ghép bình phương f(x) = (x − 3)² + 5). Giá trị cực tiểu của hàm số là f(3) = 5 (Đáp án B)."}, {"id": "e1-m1-q4", "domain": "Geometry and Trigonometry", "skill": "Circles in the xy-plane", "passage": "In the xy-plane, the graph of the equation x² − 6x + y² + 8y = 11 is a circle. What is the radius of the circle?", "question": "Determine the radius r.", "options": ["A. 4", "B. 6", "C. 12", "D. 36"], "answer": 1, "explanation": "Ghép bình phương hai biến: (x² − 6x + 9) + (y² + 8y + 16) = 11 + 9 + 16 ⇔ (x − 3)² + (y + 4)² = 36 = 6². Vậy bán kính đường tròn là r = 6 (Đáp án B)."}, {"id": "e1-m1-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Percentages", "passage": "A research grant of $220,000 was increased by 50% in Year 2 and then reduced by 20% in Year 3. What was the dollar amount, in thousands, of the grant in Year 3?", "question": "Calculate the Year 3 grant amount (in thousands of dollars).", "options": ["A. $286,000", "B. $264,000", "C. $220,000", "D. $252,000"], "answer": 1, "explanation": "Nhân các hệ số thay đổi liên tiếp: 220 × 1.50 × 0.80 = 220 × 1.20 = 264 (nghìn USD). Đáp án B."}]}, {"id": "math-m2", "name": "Section 2, Module 2: Math (Adaptive)", "shortName": "Math Mod 2", "section": "Math", "durationMinutes": 35, "directions": "This is the second adaptive module of Math. Check your units and review flagged questions before submitting the exam.", "questions": [{"id": "e1-m2-q1", "domain": "Algebra", "skill": "Linear Systems (No Solution Parameter)", "passage": "In the system of linear equations below, k is a constant:\n3x − 4y = 13\n9x + ky = 29\nIf the system has no solution, what is the value of k?", "question": "Find the value of the constant k.", "options": ["A. -12", "B. -4", "C. 12", "D. 8"], "answer": 0, "explanation": "Hệ phương trình vô nghiệm khi hai đường thẳng song song: 3/9 = (−4)/k ≠ 13/29 ⇔ 1/3 = (−4)/k ⇒ k = -12 (Đáp án A)."}, {"id": "e1-m2-q2", "domain": "Advanced Math", "skill": "Quadratic Equations (Vieta's Theorem)", "passage": "What is the sum of the solutions to the equation 2x² − 10x + 2 = 0?", "question": "Find the sum of the solutions.", "options": ["A. −5", "B. 1.0", "C. 5", "D. 10"], "answer": 2, "explanation": "Theo định lý Viète cho phương trình bậc hai ax² + bx + c = 0 (với Δ > 0), tổng hai nghiệm bằng −b/a = −(−10)/2 = 5 (Đáp án C)."}, {"id": "e1-m2-q3", "domain": "Advanced Math", "skill": "Exponential Growth Functions", "passage": "A bacterial colony starts with 350 cells and doubles in population every 4 hours. How many cells will be in the colony after 12 hours?", "question": "Calculate the population after 12 hours.", "options": ["A. 1050", "B. 1400", "C. 2800", "D. 5600"], "answer": 2, "explanation": "Số chu kỳ nhân đôi trong 12 giờ là 12 / 4 = 3 chu kỳ. Số lượng tế bào là P(12) = 350 × 2³ = 350 × 8 = 2800 (Đáp án C)."}, {"id": "e1-m2-q4", "domain": "Geometry and Trigonometry", "skill": "Right Triangle Trigonometry & Complementary Angles", "passage": "In right triangle PQR, angle R = 90° and cos(P) = 5/13. If triangle XYZ is similar to triangle PQR where vertices X, Y, and Z correspond to P, Q, and R, respectively, and each side of triangle XYZ is 3 times the corresponding side of triangle PQR, what is the value of sin(Y)?", "question": "Find the value of sin(Y).", "options": ["A. 5/13", "B. 12/13", "C. 15/13", "D. 13/5"], "answer": 0, "explanation": "Do tam giác XYZ đồng dạng với tam giác PQR nên góc Y = góc Q. Trong tam giác vuông PQR (P + Q = 90°), ta luôn có sin(Y) = sin(Q) = cos(P) = 5/13 (Đáp án A)."}, {"id": "e1-m2-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Weighted Mean & Statistics", "passage": "A dataset consists of 50 observations split into two groups. Group 1 contains 20 observations with a mean of 76, and Group 2 contains 30 observations with a mean of 86. What is the mean of all 50 observations combined?", "question": "Calculate the combined mean.", "options": ["A. 81", "B. 81.5", "C. 82", "D. 83"], "answer": 2, "explanation": "Tổng giá trị cả 2 nhóm là 20 × 76 + 30 × 86 = 4100. Chia cho tổng số 50 quan sát ta được trung bình chung là 82 (Đáp án C)."}]}]}, {"id": "exam-2", "number": 2, "title": "Đề thi thử Digital SAT #2 — Academic & Scientific Inquiry", "difficulty": "Chuẩn College Board (Standard+)", "badge": "Trọng tâm Khoa học", "desc": "Tập trung vào các văn bản thực nghiệm sinh học, thiên văn học và mô hình hàm số tuyến tính - bậc hai thực tiễn.", "modules": [{"id": "rw-m1", "name": "Section 1, Module 1: Reading and Writing", "shortName": "R&W Mod 1", "section": "Reading & Writing", "durationMinutes": 32, "directions": "The questions in this section address a number of important reading and writing skills. Each question includes one or more passages, which may include a table or graph. Read each passage and question carefully, and then choose the best answer to the question based on the passage(s).", "questions": [{"id": "e2-rw1-q1", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Rather than working in isolation, fifteenth-century Florentine painters operated collaborative workshops where apprentices executed preliminary frescoes under a master's ______ supervision. Researchers noted that these findings help refine contemporary models of Renaissance workshop guild.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. negligent", "B. fastidious", "C. ambivalent", "D. cursory"], "answer": 1, "explanation": "'Fastidious' (tỉ mỉ, khắt khe) phù hợp với quy trình giám sát chất lượng nghiêm ngặt của bậc thầy hội họa."}, {"id": "e2-rw1-q2", "domain": "Information and Ideas", "skill": "Inferences", "passage": "Chemists analyzing 2,000-year-old Roman harbor concrete discovered intact millimeter-scale lime clasts embedded in the mortar. Rather than being an accidental byproduct of sloppy mixing, these reactive calcium deposits dissolve when seawater infiltrates microcracks and recrystallize as calcium carbonate, meaning that ______", "question": "Which choice most logically completes the text?", "options": ["A. Roman engineers lacked the tools to grind limestone into fine powder.", "B. modern Portland cement contains higher concentrations of volcanic ash than Roman mortar did.", "C. the lime clasts endow the ancient concrete with a self-healing capacity that prevents cracks from expanding.", "D. seawater rapidly erodes any concrete structure containing calcium carbonate."], "answer": 2, "explanation": "Các hạt vôi hòa tan khi nước thấm vào vết nứt rồi kết tinh lại giúp bê tông La Mã có khả năng tự hàn gắn vết nứt (Đáp án C)."}, {"id": "e2-rw1-q3", "domain": "Information and Ideas", "skill": "Command of Evidence (Quantitative)", "passage": "Solar Microgrid Efficiency Across Three Operating Temperatures (Study #2):\n• Panel Type Alpha: 25°C = 22.4% | 45°C = 19.1%\n• Panel Type Beta (Perovskite-Silicon): 25°C = 27.8% | 45°C = 26.9%\n\nEnergy engineers report that while all photovoltaic modules lose efficiency as ambient temperatures rise, Perovskite-Silicon (Type Beta) panels exhibit both higher baseline efficiency and superior thermal stability at 45°C compared to Type Alpha panels.", "question": "Which data from the study most directly support the engineers' report?", "options": ["A. At 25°C, Type Alpha achieves 22.4% efficiency, which is higher than its efficiency at 45°C.", "B. Type Beta starts at 27.8% at 25°C and retains 26.9% at 45°C (a drop of only 0.9%), whereas Type Alpha drops from 22.4% to 19.1%.", "C. Both panel types were tested at exactly 25°C and 45°C under laboratory illumination.", "D. Type Alpha's efficiency at 45°C is 19.1%."], "answer": 1, "explanation": "Đáp án B trích dẫn đầy đủ cả hiệu suất nền cao hơn ở 25°C lẫn mức sụt giảm nhiệt độ rất nhỏ (chỉ 0.9%) ở 45°C của Type Beta so với Type Alpha."}, {"id": "e2-rw1-q4", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "In early trials of autonomous marine gliders (Deployment #2), strong subsurface currents frequently pushed the craft off their programmed survey transects. ______ engineers integrated real-time Doppler velocity logs into the navigation software, enabling the gliders to compensate for lateral drift automatically.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. In response,", "B. Nonetheless,", "C. For example,", "D. Conversely,"], "answer": 0, "hint": "Câu 1 nêu vấn đề kỹ thuật; câu 2 nêu giải pháp khắc phục của các kỹ sư.", "explanation": "'In response,' (Để giải quyết vấn đề đó / Đáp lại thực trạng đó) nối hợp lý giữa sự cố trôi dạt ở câu 1 và cải tiến phần mềm điều hướng ở câu 2 (Đáp án A)."}, {"id": "e2-rw1-q5", "domain": "Standard English Conventions", "skill": "Boundaries & Punctuation", "passage": "The archival collection at the Uppsala University Library houses over 430 medieval botanical codices ______ researchers have digitized only a third of these illuminated manuscripts for public open-access repositories.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. codices, however,", "B. codices; however,", "C. codices however", "D. codices, yet; "], "answer": 1, "explanation": "Hai mệnh đề độc lập nối với trạng từ chuyển tiếp 'however' bắt buộc dùng dấu chấm phẩy trước và dấu phẩy sau: 'codices; however,' (Đáp án B)."}]}, {"id": "rw-m2", "name": "Section 1, Module 2: Reading and Writing (Adaptive)", "shortName": "R&W Mod 2", "section": "Reading & Writing", "durationMinutes": 32, "directions": "This is the second adaptive module of Reading and Writing. Answer every question carefully; there is no penalty for guessing.", "questions": [{"id": "e2-rw2-q1", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "Text 1:\nUrban sociologist Dr. Aris Thorne contends that converting downtown arterial roads into pedestrian-only plazas invariably reduces quarterly retail revenue for ground-floor merchants, because suburban customers rely on curbside parking to visit specialty shops (Case Study #2).\n\nText 2:\nEconomist Mei-Ling Zhou analyzed point-of-sale tax receipts across twelve cities before and after pedestrianization. She found that while drive-in purchases dipped during the first month of construction, total annual retail sales rose by 16% as foot traffic and outdoor dining dwell times increased.", "question": "Based on the texts, how would Zhou (Text 2) most likely characterize Thorne's conclusion in Text 1?", "options": ["A. As an accurate reflection of long-term tax receipt data across all twelve studied cities.", "B. As an overgeneralization that overlooks how increased pedestrian foot traffic more than compensates for reduced curbside parking over a full year.", "C. As proof that outdoor dining establishments should be relocated to suburban shopping malls.", "D. As a valid critique of public transit fare structures."], "answer": 1, "explanation": "Số liệu thực tế cả năm của Zhou (doanh thu tăng nhờ khách đi bộ và ăn uống ngoài trời) bác bỏ dự đoán bi quan của Thorne vốn chỉ nhìn vào việc giảm chỗ đỗ xe (Đáp án B)."}, {"id": "e2-rw2-q2", "domain": "Information and Ideas", "skill": "Command of Evidence (Textual)", "passage": "In a study of avian vocal learning (Cohort #2), neurobiologist Dr. Lucas Vance proposes that juvenile songbirds must hear adult tutor songs during a critical developmental window not merely to copy individual notes, but to calibrate the tempo boundaries between syllables.", "question": "Which finding from Vance's experiment, if true, would most directly support his hypothesis?", "options": ["A. Juvenile songbirds raised in acoustic isolation produced all the correct note frequencies of their species but sang them with erratic, uncoordinated pauses between syllables.", "B. Adult songbirds sang more frequently during spring mornings than during autumn afternoons.", "C. Juvenile songbirds fed a high-protein diet developed larger flight muscles than control birds did.", "D. Different species of finches inhabit distinct canopy heights in tropical rainforests."], "answer": 0, "explanation": "Nếu chim non không được nghe chim trưởng thành vẫn phát ra đúng tần số nốt nhưng lại bị rối loạn khoảng nghỉ/nhịp độ giữa các âm tiết ('erratic pauses between syllables'), điều đó chứng minh trực tiếp vai trò hiệu chỉnh nhịp độ (tempo boundaries) của chim thầy (Đáp án A)."}, {"id": "e2-rw2-q3", "domain": "Standard English Conventions", "skill": "Subject-Verb Agreement & Modifiers", "passage": "Calibrating the 7 interferometer mirrors inside the underground gravitational-wave detector ______ sub-nanometer precision so that passing seismic vibrations from distant ocean waves do not mask astrophysical signals.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. require", "B. requires", "C. have required", "D. are requiring"], "answer": 1, "explanation": "Chủ ngữ chính là danh động từ (gerund phrase) 'Calibrating the ... mirrors' (ngôi thứ ba số ít), không phải 'mirrors' hay 'detector'. Do đó động từ chia số ít là 'requires' (Đáp án B)."}, {"id": "e2-rw2-q4", "domain": "Standard English Conventions", "skill": "Dangling Modifier", "passage": "Synthesized from plant-derived monomers at temperatures below 84°C, ______ ", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. chemical engineers designed the new recyclable polymer to dissolve in mild acidic solutions.", "B. the new recyclable polymer dissolves cleanly when immersed in mild acidic solutions.", "C. mild acidic solutions can dissolve the new recyclable polymer completely.", "D. a breakthrough in sustainable packaging was achieved by the research team."], "answer": 1, "explanation": "Cụm phân từ mở đầu 'Synthesized from plant-derived monomers...' bổ nghĩa cho chất được tổng hợp, tức là 'the new recyclable polymer' phải đứng ngay sau dấu phẩy làm chủ ngữ (Đáp án B)."}, {"id": "e2-rw2-q5", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes (Archive #2):\n• Geothermal district heating circulates naturally warm subterranean water through insulated municipal pipes.\n• In Reykjavik, Iceland, geothermal wells supply space heating to 98% of residential buildings.\n• Transitioning from imported coal to geothermal heating between 1930 and 1970 eliminated winter smog in Reykjavik.\n• Today, the system prevents approximately 3.1 million metric tons of CO₂ emissions annually.", "question": "The student wants to emphasize both the historical and ongoing environmental benefits of Reykjavik's geothermal heating system. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Reykjavik's geothermal district heating system circulates warm subterranean water to 98% of the city's residential buildings.", "B. By replacing imported coal between 1930 and 1970, Reykjavik's geothermal heating system eliminated historical winter smog and continues to prevent 3.1 million metric tons of CO₂ emissions each year.", "C. Geothermal district heating uses insulated municipal pipes to transport subterranean water.", "D. Today, Reykjavik prevents 3.1 million metric tons of CO₂ emissions annually through district heating."], "answer": 1, "explanation": "Đáp án B kết hợp đầy đủ lợi ích môi trường trong lịch sử (xóa bỏ khói bụi than đá giai đoạn 1930–1970) VÀ lợi ích hiện tại (ngăn ngừa hàng triệu tấn CO₂ mỗi năm)."}]}, {"id": "math-m1", "name": "Section 2, Module 1: Math", "shortName": "Math Mod 1", "section": "Math", "durationMinutes": 35, "directions": "The questions in this section address a number of important math skills. Use of an integrated calculator is permitted for all questions. You may open the Reference Sheet at any time.", "questions": [{"id": "e2-m1-q1", "domain": "Algebra", "skill": "Linear Equations in One Variable", "passage": "If 5x − 4 = 2x + 14, what is the value of 4x + 5?", "question": "Select the correct value of 4x + 5.", "options": ["A. 6", "B. 25", "C. 29", "D. 35"], "answer": 2, "explanation": "Chuyển vế: 5x − 2x = 14 + 4 ⇔ 3x = 18 ⇔ x = 6. Thay x = 6 vào biểu thức 4x + 5 ta được 4(6) + 5 = 29 (Đáp án C)."}, {"id": "e2-m1-q2", "domain": "Algebra", "skill": "Systems of Two Linear Equations", "passage": "If (x, y) is the solution to the system of equations below:\n4x + 5y = 55\n5x + 4y = 53\nWhat is the value of x + y?", "question": "Calculate x + y.", "options": ["A. 10", "B. 12", "C. 15", "D. 108"], "answer": 1, "explanation": "Cộng vế theo vế hai phương trình: (4x + 5x) + (5y + 4y) = 55 + 53 ⇔ 9(x + y) = 108. Chia hai vế cho 9 ta được x + y = 12 (Đáp án B)."}, {"id": "e2-m1-q3", "domain": "Advanced Math", "skill": "Quadratic Functions & Vertex", "passage": "The function f is defined by f(x) = x² − 8x + 23. What is the minimum value of f(x)?", "question": "Find the minimum value of f(x).", "options": ["A. 4", "B. 7", "C. 23", "D. −8"], "answer": 1, "explanation": "Hoành độ đỉnh của parabol là x = −b/(2a) = 8/2 = 4 (hoặc ghép bình phương f(x) = (x − 4)² + 7). Giá trị cực tiểu của hàm số là f(4) = 7 (Đáp án B)."}, {"id": "e2-m1-q4", "domain": "Geometry and Trigonometry", "skill": "Circles in the xy-plane", "passage": "In the xy-plane, the graph of the equation x² − 6x + y² + 8y = 24 is a circle. What is the radius of the circle?", "question": "Determine the radius r.", "options": ["A. 5", "B. 7", "C. 14", "D. 49"], "answer": 1, "explanation": "Ghép bình phương hai biến: (x² − 6x + 9) + (y² + 8y + 16) = 24 + 9 + 16 ⇔ (x − 3)² + (y + 4)² = 49 = 7². Vậy bán kính đường tròn là r = 7 (Đáp án B)."}, {"id": "e2-m1-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Percentages", "passage": "A research grant of $240,000 was increased by 50% in Year 2 and then reduced by 20% in Year 3. What was the dollar amount, in thousands, of the grant in Year 3?", "question": "Calculate the Year 3 grant amount (in thousands of dollars).", "options": ["A. $312,000", "B. $288,000", "C. $240,000", "D. $276,000"], "answer": 1, "explanation": "Nhân các hệ số thay đổi liên tiếp: 240 × 1.50 × 0.80 = 240 × 1.20 = 288 (nghìn USD). Đáp án B."}]}, {"id": "math-m2", "name": "Section 2, Module 2: Math (Adaptive)", "shortName": "Math Mod 2", "section": "Math", "durationMinutes": 35, "directions": "This is the second adaptive module of Math. Check your units and review flagged questions before submitting the exam.", "questions": [{"id": "e2-m2-q1", "domain": "Algebra", "skill": "Linear Systems (No Solution Parameter)", "passage": "In the system of linear equations below, k is a constant:\n4x − 5y = 13\n12x + ky = 29\nIf the system has no solution, what is the value of k?", "question": "Find the value of the constant k.", "options": ["A. -15", "B. -5", "C. 15", "D. 10"], "answer": 0, "explanation": "Hệ phương trình vô nghiệm khi hai đường thẳng song song: 4/12 = (−5)/k ≠ 13/29 ⇔ 1/3 = (−5)/k ⇒ k = -15 (Đáp án A)."}, {"id": "e2-m2-q2", "domain": "Advanced Math", "skill": "Quadratic Equations (Vieta's Theorem)", "passage": "What is the sum of the solutions to the equation 2x² − 14x + 3 = 0?", "question": "Find the sum of the solutions.", "options": ["A. −7", "B. 1.5", "C. 7", "D. 14"], "answer": 2, "explanation": "Theo định lý Viète cho phương trình bậc hai ax² + bx + c = 0 (với Δ > 0), tổng hai nghiệm bằng −b/a = −(−14)/2 = 7 (Đáp án C)."}, {"id": "e2-m2-q3", "domain": "Advanced Math", "skill": "Exponential Growth Functions", "passage": "A bacterial colony starts with 400 cells and doubles in population every 5 hours. How many cells will be in the colony after 15 hours?", "question": "Calculate the population after 15 hours.", "options": ["A. 1200", "B. 1600", "C. 3200", "D. 6400"], "answer": 2, "explanation": "Số chu kỳ nhân đôi trong 15 giờ là 15 / 5 = 3 chu kỳ. Số lượng tế bào là P(15) = 400 × 2³ = 400 × 8 = 3200 (Đáp án C)."}, {"id": "e2-m2-q4", "domain": "Geometry and Trigonometry", "skill": "Right Triangle Trigonometry & Complementary Angles", "passage": "In right triangle PQR, angle R = 90° and cos(P) = 6/13. If triangle XYZ is similar to triangle PQR where vertices X, Y, and Z correspond to P, Q, and R, respectively, and each side of triangle XYZ is 4 times the corresponding side of triangle PQR, what is the value of sin(Y)?", "question": "Find the value of sin(Y).", "options": ["A. 6/13", "B. 11/13", "C. 24/13", "D. 13/6"], "answer": 0, "explanation": "Do tam giác XYZ đồng dạng với tam giác PQR nên góc Y = góc Q. Trong tam giác vuông PQR (P + Q = 90°), ta luôn có sin(Y) = sin(Q) = cos(P) = 6/13 (Đáp án A)."}, {"id": "e2-m2-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Weighted Mean & Statistics", "passage": "A dataset consists of 50 observations split into two groups. Group 1 contains 20 observations with a mean of 77, and Group 2 contains 30 observations with a mean of 87. What is the mean of all 50 observations combined?", "question": "Calculate the combined mean.", "options": ["A. 82", "B. 82.5", "C. 83", "D. 84"], "answer": 2, "explanation": "Tổng giá trị cả 2 nhóm là 20 × 77 + 30 × 87 = 4150. Chia cho tổng số 50 quan sát ta được trung bình chung là 83 (Đáp án C)."}]}]}, {"id": "exam-3", "number": 3, "title": "Đề thi thử Digital SAT #3 — STEM & Quantitative Reasoning", "difficulty": "Khá - Giỏi (Upper-Intermediate)", "badge": "Thế mạnh Số liệu", "desc": "Tăng cường câu hỏi Command of Evidence (Quantitative), thống kê thực nghiệm và đại số nâng cao.", "modules": [{"id": "rw-m1", "name": "Section 1, Module 1: Reading and Writing", "shortName": "R&W Mod 1", "section": "Reading & Writing", "durationMinutes": 32, "directions": "The questions in this section address a number of important reading and writing skills. Each question includes one or more passages, which may include a table or graph. Read each passage and question carefully, and then choose the best answer to the question based on the passage(s).", "questions": [{"id": "e3-rw1-q1", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Maintaining qubits in a coherent superposition requires shielding them from the slightest thermal vibration, as even ______ environmental disturbances cause immediate decoherence. Researchers noted that these findings help refine contemporary models of quantum decoherence.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. ostentatious", "B. imperceptible", "C. substantial", "D. deliberate"], "answer": 1, "explanation": "Từ nhấn mạnh 'even' (ngay cả những nhiễu động nhỏ nhất không thể nhận thấy bằng giác quan = imperceptible)."}, {"id": "e3-rw1-q2", "domain": "Information and Ideas", "skill": "Inferences", "passage": "Asian and European honeybee species use slightly different duration-to-distance scales in their figure-eight 'waggle dances.' Yet when researchers placed both species in a mixed observation hive, foragers learned within days to decode the partner species' distance signals accurately, suggesting that ______", "question": "Which choice most logically completes the text?", "options": ["A. waggle dance communication possesses a degree of behavioral plasticity through social learning rather than being strictly unmodifiable.", "B. European honeybees cannot forage outside their native geographic range.", "C. honeybees rely exclusively on floral scent trails rather than dance signals.", "D. mixed-species hives produce less honey than single-species hives do."], "answer": 0, "explanation": "Việc ong học cách giải mã ngôn ngữ vũ điệu của loài kia chỉ sau vài ngày cho thấy tính linh hoạt hành vi thông qua học tập xã hội (Đáp án A)."}, {"id": "e3-rw1-q3", "domain": "Information and Ideas", "skill": "Command of Evidence (Quantitative)", "passage": "Solar Microgrid Efficiency Across Three Operating Temperatures (Study #3):\n• Panel Type Alpha: 25°C = 23.4% | 45°C = 20.1%\n• Panel Type Beta (Perovskite-Silicon): 25°C = 28.8% | 45°C = 27.9%\n\nEnergy engineers report that while all photovoltaic modules lose efficiency as ambient temperatures rise, Perovskite-Silicon (Type Beta) panels exhibit both higher baseline efficiency and superior thermal stability at 45°C compared to Type Alpha panels.", "question": "Which data from the study most directly support the engineers' report?", "options": ["A. At 25°C, Type Alpha achieves 23.4% efficiency, which is higher than its efficiency at 45°C.", "B. Type Beta starts at 28.8% at 25°C and retains 27.9% at 45°C (a drop of only 0.9%), whereas Type Alpha drops from 23.4% to 20.1%.", "C. Both panel types were tested at exactly 25°C and 45°C under laboratory illumination.", "D. Type Alpha's efficiency at 45°C is 20.1%."], "answer": 1, "explanation": "Đáp án B trích dẫn đầy đủ cả hiệu suất nền cao hơn ở 25°C lẫn mức sụt giảm nhiệt độ rất nhỏ (chỉ 0.9%) ở 45°C của Type Beta so với Type Alpha."}, {"id": "e3-rw1-q4", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "In early trials of autonomous marine gliders (Deployment #3), strong subsurface currents frequently pushed the craft off their programmed survey transects. ______ engineers integrated real-time Doppler velocity logs into the navigation software, enabling the gliders to compensate for lateral drift automatically.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. In response,", "B. Nonetheless,", "C. For example,", "D. Conversely,"], "answer": 0, "hint": "Câu 1 nêu vấn đề kỹ thuật; câu 2 nêu giải pháp khắc phục của các kỹ sư.", "explanation": "'In response,' (Để giải quyết vấn đề đó / Đáp lại thực trạng đó) nối hợp lý giữa sự cố trôi dạt ở câu 1 và cải tiến phần mềm điều hướng ở câu 2 (Đáp án A)."}, {"id": "e3-rw1-q5", "domain": "Standard English Conventions", "skill": "Boundaries & Punctuation", "passage": "The archival collection at the Uppsala University Library houses over 445 medieval botanical codices ______ researchers have digitized only a third of these illuminated manuscripts for public open-access repositories.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. codices, however,", "B. codices; however,", "C. codices however", "D. codices, yet; "], "answer": 1, "explanation": "Hai mệnh đề độc lập nối với trạng từ chuyển tiếp 'however' bắt buộc dùng dấu chấm phẩy trước và dấu phẩy sau: 'codices; however,' (Đáp án B)."}]}, {"id": "rw-m2", "name": "Section 1, Module 2: Reading and Writing (Adaptive)", "shortName": "R&W Mod 2", "section": "Reading & Writing", "durationMinutes": 32, "directions": "This is the second adaptive module of Reading and Writing. Answer every question carefully; there is no penalty for guessing.", "questions": [{"id": "e3-rw2-q1", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "Text 1:\nUrban sociologist Dr. Aris Thorne contends that converting downtown arterial roads into pedestrian-only plazas invariably reduces quarterly retail revenue for ground-floor merchants, because suburban customers rely on curbside parking to visit specialty shops (Case Study #3).\n\nText 2:\nEconomist Mei-Ling Zhou analyzed point-of-sale tax receipts across twelve cities before and after pedestrianization. She found that while drive-in purchases dipped during the first month of construction, total annual retail sales rose by 17% as foot traffic and outdoor dining dwell times increased.", "question": "Based on the texts, how would Zhou (Text 2) most likely characterize Thorne's conclusion in Text 1?", "options": ["A. As an accurate reflection of long-term tax receipt data across all twelve studied cities.", "B. As an overgeneralization that overlooks how increased pedestrian foot traffic more than compensates for reduced curbside parking over a full year.", "C. As proof that outdoor dining establishments should be relocated to suburban shopping malls.", "D. As a valid critique of public transit fare structures."], "answer": 1, "explanation": "Số liệu thực tế cả năm của Zhou (doanh thu tăng nhờ khách đi bộ và ăn uống ngoài trời) bác bỏ dự đoán bi quan của Thorne vốn chỉ nhìn vào việc giảm chỗ đỗ xe (Đáp án B)."}, {"id": "e3-rw2-q2", "domain": "Information and Ideas", "skill": "Command of Evidence (Textual)", "passage": "In a study of avian vocal learning (Cohort #3), neurobiologist Dr. Lucas Vance proposes that juvenile songbirds must hear adult tutor songs during a critical developmental window not merely to copy individual notes, but to calibrate the tempo boundaries between syllables.", "question": "Which finding from Vance's experiment, if true, would most directly support his hypothesis?", "options": ["A. Juvenile songbirds raised in acoustic isolation produced all the correct note frequencies of their species but sang them with erratic, uncoordinated pauses between syllables.", "B. Adult songbirds sang more frequently during spring mornings than during autumn afternoons.", "C. Juvenile songbirds fed a high-protein diet developed larger flight muscles than control birds did.", "D. Different species of finches inhabit distinct canopy heights in tropical rainforests."], "answer": 0, "explanation": "Nếu chim non không được nghe chim trưởng thành vẫn phát ra đúng tần số nốt nhưng lại bị rối loạn khoảng nghỉ/nhịp độ giữa các âm tiết ('erratic pauses between syllables'), điều đó chứng minh trực tiếp vai trò hiệu chỉnh nhịp độ (tempo boundaries) của chim thầy (Đáp án A)."}, {"id": "e3-rw2-q3", "domain": "Standard English Conventions", "skill": "Subject-Verb Agreement & Modifiers", "passage": "Calibrating the 8 interferometer mirrors inside the underground gravitational-wave detector ______ sub-nanometer precision so that passing seismic vibrations from distant ocean waves do not mask astrophysical signals.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. require", "B. requires", "C. have required", "D. are requiring"], "answer": 1, "explanation": "Chủ ngữ chính là danh động từ (gerund phrase) 'Calibrating the ... mirrors' (ngôi thứ ba số ít), không phải 'mirrors' hay 'detector'. Do đó động từ chia số ít là 'requires' (Đáp án B)."}, {"id": "e3-rw2-q4", "domain": "Standard English Conventions", "skill": "Dangling Modifier", "passage": "Synthesized from plant-derived monomers at temperatures below 86°C, ______ ", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. chemical engineers designed the new recyclable polymer to dissolve in mild acidic solutions.", "B. the new recyclable polymer dissolves cleanly when immersed in mild acidic solutions.", "C. mild acidic solutions can dissolve the new recyclable polymer completely.", "D. a breakthrough in sustainable packaging was achieved by the research team."], "answer": 1, "explanation": "Cụm phân từ mở đầu 'Synthesized from plant-derived monomers...' bổ nghĩa cho chất được tổng hợp, tức là 'the new recyclable polymer' phải đứng ngay sau dấu phẩy làm chủ ngữ (Đáp án B)."}, {"id": "e3-rw2-q5", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes (Archive #3):\n• Geothermal district heating circulates naturally warm subterranean water through insulated municipal pipes.\n• In Reykjavik, Iceland, geothermal wells supply space heating to 98% of residential buildings.\n• Transitioning from imported coal to geothermal heating between 1930 and 1970 eliminated winter smog in Reykjavik.\n• Today, the system prevents approximately 4.1 million metric tons of CO₂ emissions annually.", "question": "The student wants to emphasize both the historical and ongoing environmental benefits of Reykjavik's geothermal heating system. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Reykjavik's geothermal district heating system circulates warm subterranean water to 98% of the city's residential buildings.", "B. By replacing imported coal between 1930 and 1970, Reykjavik's geothermal heating system eliminated historical winter smog and continues to prevent 4.1 million metric tons of CO₂ emissions each year.", "C. Geothermal district heating uses insulated municipal pipes to transport subterranean water.", "D. Today, Reykjavik prevents 4.1 million metric tons of CO₂ emissions annually through district heating."], "answer": 1, "explanation": "Đáp án B kết hợp đầy đủ lợi ích môi trường trong lịch sử (xóa bỏ khói bụi than đá giai đoạn 1930–1970) VÀ lợi ích hiện tại (ngăn ngừa hàng triệu tấn CO₂ mỗi năm)."}]}, {"id": "math-m1", "name": "Section 2, Module 1: Math", "shortName": "Math Mod 1", "section": "Math", "durationMinutes": 35, "directions": "The questions in this section address a number of important math skills. Use of an integrated calculator is permitted for all questions. You may open the Reference Sheet at any time.", "questions": [{"id": "e3-m1-q1", "domain": "Algebra", "skill": "Linear Equations in One Variable", "passage": "If 5x − 4 = 2x + 17, what is the value of 4x + 5?", "question": "Select the correct value of 4x + 5.", "options": ["A. 7", "B. 29", "C. 33", "D. 39"], "answer": 2, "explanation": "Chuyển vế: 5x − 2x = 17 + 4 ⇔ 3x = 21 ⇔ x = 7. Thay x = 7 vào biểu thức 4x + 5 ta được 4(7) + 5 = 33 (Đáp án C)."}, {"id": "e3-m1-q2", "domain": "Algebra", "skill": "Systems of Two Linear Equations", "passage": "If (x, y) is the solution to the system of equations below:\n4x + 5y = 59\n5x + 4y = 58\nWhat is the value of x + y?", "question": "Calculate x + y.", "options": ["A. 11", "B. 13", "C. 16", "D. 117"], "answer": 1, "explanation": "Cộng vế theo vế hai phương trình: (4x + 5x) + (5y + 4y) = 59 + 58 ⇔ 9(x + y) = 117. Chia hai vế cho 9 ta được x + y = 13 (Đáp án B)."}, {"id": "e3-m1-q3", "domain": "Advanced Math", "skill": "Quadratic Functions & Vertex", "passage": "The function f is defined by f(x) = x² − 10x + 34. What is the minimum value of f(x)?", "question": "Find the minimum value of f(x).", "options": ["A. 5", "B. 9", "C. 34", "D. −10"], "answer": 1, "explanation": "Hoành độ đỉnh của parabol là x = −b/(2a) = 10/2 = 5 (hoặc ghép bình phương f(x) = (x − 5)² + 9). Giá trị cực tiểu của hàm số là f(5) = 9 (Đáp án B)."}, {"id": "e3-m1-q4", "domain": "Geometry and Trigonometry", "skill": "Circles in the xy-plane", "passage": "In the xy-plane, the graph of the equation x² − 6x + y² + 8y = 39 is a circle. What is the radius of the circle?", "question": "Determine the radius r.", "options": ["A. 6", "B. 8", "C. 16", "D. 64"], "answer": 1, "explanation": "Ghép bình phương hai biến: (x² − 6x + 9) + (y² + 8y + 16) = 39 + 9 + 16 ⇔ (x − 3)² + (y + 4)² = 64 = 8². Vậy bán kính đường tròn là r = 8 (Đáp án B)."}, {"id": "e3-m1-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Percentages", "passage": "A research grant of $260,000 was increased by 50% in Year 2 and then reduced by 20% in Year 3. What was the dollar amount, in thousands, of the grant in Year 3?", "question": "Calculate the Year 3 grant amount (in thousands of dollars).", "options": ["A. $338,000", "B. $312,000", "C. $260,000", "D. $299,000"], "answer": 1, "explanation": "Nhân các hệ số thay đổi liên tiếp: 260 × 1.50 × 0.80 = 260 × 1.20 = 312 (nghìn USD). Đáp án B."}]}, {"id": "math-m2", "name": "Section 2, Module 2: Math (Adaptive)", "shortName": "Math Mod 2", "section": "Math", "durationMinutes": 35, "directions": "This is the second adaptive module of Math. Check your units and review flagged questions before submitting the exam.", "questions": [{"id": "e3-m2-q1", "domain": "Algebra", "skill": "Linear Systems (No Solution Parameter)", "passage": "In the system of linear equations below, k is a constant:\n5x − 6y = 13\n15x + ky = 29\nIf the system has no solution, what is the value of k?", "question": "Find the value of the constant k.", "options": ["A. -18", "B. -6", "C. 18", "D. 12"], "answer": 0, "explanation": "Hệ phương trình vô nghiệm khi hai đường thẳng song song: 5/15 = (−6)/k ≠ 13/29 ⇔ 1/3 = (−6)/k ⇒ k = -18 (Đáp án A)."}, {"id": "e3-m2-q2", "domain": "Advanced Math", "skill": "Quadratic Equations (Vieta's Theorem)", "passage": "What is the sum of the solutions to the equation 2x² − 18x + 4 = 0?", "question": "Find the sum of the solutions.", "options": ["A. −9", "B. 2.0", "C. 9", "D. 18"], "answer": 2, "explanation": "Theo định lý Viète cho phương trình bậc hai ax² + bx + c = 0 (với Δ > 0), tổng hai nghiệm bằng −b/a = −(−18)/2 = 9 (Đáp án C)."}, {"id": "e3-m2-q3", "domain": "Advanced Math", "skill": "Exponential Growth Functions", "passage": "A bacterial colony starts with 450 cells and doubles in population every 6 hours. How many cells will be in the colony after 18 hours?", "question": "Calculate the population after 18 hours.", "options": ["A. 1350", "B. 1800", "C. 3600", "D. 7200"], "answer": 2, "explanation": "Số chu kỳ nhân đôi trong 18 giờ là 18 / 6 = 3 chu kỳ. Số lượng tế bào là P(18) = 450 × 2³ = 450 × 8 = 3600 (Đáp án C)."}, {"id": "e3-m2-q4", "domain": "Geometry and Trigonometry", "skill": "Right Triangle Trigonometry & Complementary Angles", "passage": "In right triangle PQR, angle R = 90° and cos(P) = 5/13. If triangle XYZ is similar to triangle PQR where vertices X, Y, and Z correspond to P, Q, and R, respectively, and each side of triangle XYZ is 5 times the corresponding side of triangle PQR, what is the value of sin(Y)?", "question": "Find the value of sin(Y).", "options": ["A. 5/13", "B. 12/13", "C. 25/13", "D. 13/5"], "answer": 0, "explanation": "Do tam giác XYZ đồng dạng với tam giác PQR nên góc Y = góc Q. Trong tam giác vuông PQR (P + Q = 90°), ta luôn có sin(Y) = sin(Q) = cos(P) = 5/13 (Đáp án A)."}, {"id": "e3-m2-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Weighted Mean & Statistics", "passage": "A dataset consists of 50 observations split into two groups. Group 1 contains 20 observations with a mean of 78, and Group 2 contains 30 observations with a mean of 88. What is the mean of all 50 observations combined?", "question": "Calculate the combined mean.", "options": ["A. 83", "B. 83.5", "C. 84", "D. 85"], "answer": 2, "explanation": "Tổng giá trị cả 2 nhóm là 20 × 78 + 30 × 88 = 4200. Chia cho tổng số 50 quan sát ta được trung bình chung là 84 (Đáp án C)."}]}]}, {"id": "exam-4", "number": 4, "title": "Đề thi thử Digital SAT #4 — Literature, History & Rhetoric", "difficulty": "Khá - Giỏi (Upper-Intermediate)", "badge": "Văn học & Lịch sử", "desc": "Rèn kỹ năng xử lý văn bản văn học thế kỷ 19–20, bài đọc đôi Cross-Text và ngữ pháp câu phức dài.", "modules": [{"id": "rw-m1", "name": "Section 1, Module 1: Reading and Writing", "shortName": "R&W Mod 1", "section": "Reading & Writing", "durationMinutes": 32, "directions": "The questions in this section address a number of important reading and writing skills. Each question includes one or more passages, which may include a table or graph. Read each passage and question carefully, and then choose the best answer to the question based on the passage(s).", "questions": [{"id": "e4-rw1-q1", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "By lining the museum's central atrium with porous volcanic stone panels, the acoustic engineers successfully ______ the reverberation of footsteps and crowd chatter. Researchers noted that these findings help refine contemporary models of urban acoustics courtyard.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. amplified", "B. attenuated", "C. instigated", "D. perpetuated"], "answer": 1, "explanation": "'Attenuated' (làm giảm nhẹ, làm suy yếu âm vang) khớp với tác dụng tiêu âm của đá xốp."}, {"id": "e4-rw1-q2", "domain": "Information and Ideas", "skill": "Inferences", "passage": "High-pressure sodium streetlamps emit amber wavelengths that minimally disrupt nocturnal moths, whereas broad-spectrum white LED streetlamps suppress caterpillar feeding and reduce nighttime flower visits by 62 percent. Consequently, municipalities converting to energy-efficient LEDs can mitigate ecological disruption by ______", "question": "Which choice most logically completes the text?", "options": ["A. removing all flowering plants from urban parks and boulevards.", "B. replacing daytime pollinators with nocturnal moth species.", "C. installing shielded, warm-spectrum LEDs that filter out the short blue wavelengths most disruptive to nocturnal insects.", "D. increasing the brightness of unshielded white LED fixtures at midnight."], "answer": 2, "explanation": "Để vừa tiết kiệm điện bằng đèn LED vừa giảm tác hại lên côn trùng đêm, đô thị nên dùng đèn LED có chụp chắn và dải quang phổ ấm lọc bỏ ánh sáng xanh (Đáp án C)."}, {"id": "e4-rw1-q3", "domain": "Information and Ideas", "skill": "Command of Evidence (Quantitative)", "passage": "Solar Microgrid Efficiency Across Three Operating Temperatures (Study #4):\n• Panel Type Alpha: 25°C = 21.4% | 45°C = 18.1%\n• Panel Type Beta (Perovskite-Silicon): 25°C = 26.8% | 45°C = 25.9%\n\nEnergy engineers report that while all photovoltaic modules lose efficiency as ambient temperatures rise, Perovskite-Silicon (Type Beta) panels exhibit both higher baseline efficiency and superior thermal stability at 45°C compared to Type Alpha panels.", "question": "Which data from the study most directly support the engineers' report?", "options": ["A. At 25°C, Type Alpha achieves 21.4% efficiency, which is higher than its efficiency at 45°C.", "B. Type Beta starts at 26.8% at 25°C and retains 25.9% at 45°C (a drop of only 0.9%), whereas Type Alpha drops from 21.4% to 18.1%.", "C. Both panel types were tested at exactly 25°C and 45°C under laboratory illumination.", "D. Type Alpha's efficiency at 45°C is 18.1%."], "answer": 1, "explanation": "Đáp án B trích dẫn đầy đủ cả hiệu suất nền cao hơn ở 25°C lẫn mức sụt giảm nhiệt độ rất nhỏ (chỉ 0.9%) ở 45°C của Type Beta so với Type Alpha."}, {"id": "e4-rw1-q4", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "In early trials of autonomous marine gliders (Deployment #4), strong subsurface currents frequently pushed the craft off their programmed survey transects. ______ engineers integrated real-time Doppler velocity logs into the navigation software, enabling the gliders to compensate for lateral drift automatically.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. In response,", "B. Nonetheless,", "C. For example,", "D. Conversely,"], "answer": 0, "hint": "Câu 1 nêu vấn đề kỹ thuật; câu 2 nêu giải pháp khắc phục của các kỹ sư.", "explanation": "'In response,' (Để giải quyết vấn đề đó / Đáp lại thực trạng đó) nối hợp lý giữa sự cố trôi dạt ở câu 1 và cải tiến phần mềm điều hướng ở câu 2 (Đáp án A)."}, {"id": "e4-rw1-q5", "domain": "Standard English Conventions", "skill": "Boundaries & Punctuation", "passage": "The archival collection at the Uppsala University Library houses over 460 medieval botanical codices ______ researchers have digitized only a third of these illuminated manuscripts for public open-access repositories.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. codices, however,", "B. codices; however,", "C. codices however", "D. codices, yet; "], "answer": 1, "explanation": "Hai mệnh đề độc lập nối với trạng từ chuyển tiếp 'however' bắt buộc dùng dấu chấm phẩy trước và dấu phẩy sau: 'codices; however,' (Đáp án B)."}]}, {"id": "rw-m2", "name": "Section 1, Module 2: Reading and Writing (Adaptive)", "shortName": "R&W Mod 2", "section": "Reading & Writing", "durationMinutes": 32, "directions": "This is the second adaptive module of Reading and Writing. Answer every question carefully; there is no penalty for guessing.", "questions": [{"id": "e4-rw2-q1", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "Text 1:\nUrban sociologist Dr. Aris Thorne contends that converting downtown arterial roads into pedestrian-only plazas invariably reduces quarterly retail revenue for ground-floor merchants, because suburban customers rely on curbside parking to visit specialty shops (Case Study #4).\n\nText 2:\nEconomist Mei-Ling Zhou analyzed point-of-sale tax receipts across twelve cities before and after pedestrianization. She found that while drive-in purchases dipped during the first month of construction, total annual retail sales rose by 18% as foot traffic and outdoor dining dwell times increased.", "question": "Based on the texts, how would Zhou (Text 2) most likely characterize Thorne's conclusion in Text 1?", "options": ["A. As an accurate reflection of long-term tax receipt data across all twelve studied cities.", "B. As an overgeneralization that overlooks how increased pedestrian foot traffic more than compensates for reduced curbside parking over a full year.", "C. As proof that outdoor dining establishments should be relocated to suburban shopping malls.", "D. As a valid critique of public transit fare structures."], "answer": 1, "explanation": "Số liệu thực tế cả năm của Zhou (doanh thu tăng nhờ khách đi bộ và ăn uống ngoài trời) bác bỏ dự đoán bi quan của Thorne vốn chỉ nhìn vào việc giảm chỗ đỗ xe (Đáp án B)."}, {"id": "e4-rw2-q2", "domain": "Information and Ideas", "skill": "Command of Evidence (Textual)", "passage": "In a study of avian vocal learning (Cohort #4), neurobiologist Dr. Lucas Vance proposes that juvenile songbirds must hear adult tutor songs during a critical developmental window not merely to copy individual notes, but to calibrate the tempo boundaries between syllables.", "question": "Which finding from Vance's experiment, if true, would most directly support his hypothesis?", "options": ["A. Juvenile songbirds raised in acoustic isolation produced all the correct note frequencies of their species but sang them with erratic, uncoordinated pauses between syllables.", "B. Adult songbirds sang more frequently during spring mornings than during autumn afternoons.", "C. Juvenile songbirds fed a high-protein diet developed larger flight muscles than control birds did.", "D. Different species of finches inhabit distinct canopy heights in tropical rainforests."], "answer": 0, "explanation": "Nếu chim non không được nghe chim trưởng thành vẫn phát ra đúng tần số nốt nhưng lại bị rối loạn khoảng nghỉ/nhịp độ giữa các âm tiết ('erratic pauses between syllables'), điều đó chứng minh trực tiếp vai trò hiệu chỉnh nhịp độ (tempo boundaries) của chim thầy (Đáp án A)."}, {"id": "e4-rw2-q3", "domain": "Standard English Conventions", "skill": "Subject-Verb Agreement & Modifiers", "passage": "Calibrating the 9 interferometer mirrors inside the underground gravitational-wave detector ______ sub-nanometer precision so that passing seismic vibrations from distant ocean waves do not mask astrophysical signals.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. require", "B. requires", "C. have required", "D. are requiring"], "answer": 1, "explanation": "Chủ ngữ chính là danh động từ (gerund phrase) 'Calibrating the ... mirrors' (ngôi thứ ba số ít), không phải 'mirrors' hay 'detector'. Do đó động từ chia số ít là 'requires' (Đáp án B)."}, {"id": "e4-rw2-q4", "domain": "Standard English Conventions", "skill": "Dangling Modifier", "passage": "Synthesized from plant-derived monomers at temperatures below 88°C, ______ ", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. chemical engineers designed the new recyclable polymer to dissolve in mild acidic solutions.", "B. the new recyclable polymer dissolves cleanly when immersed in mild acidic solutions.", "C. mild acidic solutions can dissolve the new recyclable polymer completely.", "D. a breakthrough in sustainable packaging was achieved by the research team."], "answer": 1, "explanation": "Cụm phân từ mở đầu 'Synthesized from plant-derived monomers...' bổ nghĩa cho chất được tổng hợp, tức là 'the new recyclable polymer' phải đứng ngay sau dấu phẩy làm chủ ngữ (Đáp án B)."}, {"id": "e4-rw2-q5", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes (Archive #4):\n• Geothermal district heating circulates naturally warm subterranean water through insulated municipal pipes.\n• In Reykjavik, Iceland, geothermal wells supply space heating to 98% of residential buildings.\n• Transitioning from imported coal to geothermal heating between 1930 and 1970 eliminated winter smog in Reykjavik.\n• Today, the system prevents approximately 2.1 million metric tons of CO₂ emissions annually.", "question": "The student wants to emphasize both the historical and ongoing environmental benefits of Reykjavik's geothermal heating system. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Reykjavik's geothermal district heating system circulates warm subterranean water to 98% of the city's residential buildings.", "B. By replacing imported coal between 1930 and 1970, Reykjavik's geothermal heating system eliminated historical winter smog and continues to prevent 2.1 million metric tons of CO₂ emissions each year.", "C. Geothermal district heating uses insulated municipal pipes to transport subterranean water.", "D. Today, Reykjavik prevents 2.1 million metric tons of CO₂ emissions annually through district heating."], "answer": 1, "explanation": "Đáp án B kết hợp đầy đủ lợi ích môi trường trong lịch sử (xóa bỏ khói bụi than đá giai đoạn 1930–1970) VÀ lợi ích hiện tại (ngăn ngừa hàng triệu tấn CO₂ mỗi năm)."}]}, {"id": "math-m1", "name": "Section 2, Module 1: Math", "shortName": "Math Mod 1", "section": "Math", "durationMinutes": 35, "directions": "The questions in this section address a number of important math skills. Use of an integrated calculator is permitted for all questions. You may open the Reference Sheet at any time.", "questions": [{"id": "e4-m1-q1", "domain": "Algebra", "skill": "Linear Equations in One Variable", "passage": "If 5x − 4 = 2x + 20, what is the value of 4x + 5?", "question": "Select the correct value of 4x + 5.", "options": ["A. 8", "B. 33", "C. 37", "D. 43"], "answer": 2, "explanation": "Chuyển vế: 5x − 2x = 20 + 4 ⇔ 3x = 24 ⇔ x = 8. Thay x = 8 vào biểu thức 4x + 5 ta được 4(8) + 5 = 37 (Đáp án C)."}, {"id": "e4-m1-q2", "domain": "Algebra", "skill": "Systems of Two Linear Equations", "passage": "If (x, y) is the solution to the system of equations below:\n4x + 5y = 63\n5x + 4y = 63\nWhat is the value of x + y?", "question": "Calculate x + y.", "options": ["A. 12", "B. 14", "C. 17", "D. 126"], "answer": 1, "explanation": "Cộng vế theo vế hai phương trình: (4x + 5x) + (5y + 4y) = 63 + 63 ⇔ 9(x + y) = 126. Chia hai vế cho 9 ta được x + y = 14 (Đáp án B)."}, {"id": "e4-m1-q3", "domain": "Advanced Math", "skill": "Quadratic Functions & Vertex", "passage": "The function f is defined by f(x) = x² − 12x + 47. What is the minimum value of f(x)?", "question": "Find the minimum value of f(x).", "options": ["A. 6", "B. 11", "C. 47", "D. −12"], "answer": 1, "explanation": "Hoành độ đỉnh của parabol là x = −b/(2a) = 12/2 = 6 (hoặc ghép bình phương f(x) = (x − 6)² + 11). Giá trị cực tiểu của hàm số là f(6) = 11 (Đáp án B)."}, {"id": "e4-m1-q4", "domain": "Geometry and Trigonometry", "skill": "Circles in the xy-plane", "passage": "In the xy-plane, the graph of the equation x² − 6x + y² + 8y = 56 is a circle. What is the radius of the circle?", "question": "Determine the radius r.", "options": ["A. 7", "B. 9", "C. 18", "D. 81"], "answer": 1, "explanation": "Ghép bình phương hai biến: (x² − 6x + 9) + (y² + 8y + 16) = 56 + 9 + 16 ⇔ (x − 3)² + (y + 4)² = 81 = 9². Vậy bán kính đường tròn là r = 9 (Đáp án B)."}, {"id": "e4-m1-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Percentages", "passage": "A research grant of $280,000 was increased by 50% in Year 2 and then reduced by 20% in Year 3. What was the dollar amount, in thousands, of the grant in Year 3?", "question": "Calculate the Year 3 grant amount (in thousands of dollars).", "options": ["A. $364,000", "B. $336,000", "C. $280,000", "D. $322,000"], "answer": 1, "explanation": "Nhân các hệ số thay đổi liên tiếp: 280 × 1.50 × 0.80 = 280 × 1.20 = 336 (nghìn USD). Đáp án B."}]}, {"id": "math-m2", "name": "Section 2, Module 2: Math (Adaptive)", "shortName": "Math Mod 2", "section": "Math", "durationMinutes": 35, "directions": "This is the second adaptive module of Math. Check your units and review flagged questions before submitting the exam.", "questions": [{"id": "e4-m2-q1", "domain": "Algebra", "skill": "Linear Systems (No Solution Parameter)", "passage": "In the system of linear equations below, k is a constant:\n6x − 7y = 13\n18x + ky = 29\nIf the system has no solution, what is the value of k?", "question": "Find the value of the constant k.", "options": ["A. -21", "B. -7", "C. 21", "D. 14"], "answer": 0, "explanation": "Hệ phương trình vô nghiệm khi hai đường thẳng song song: 6/18 = (−7)/k ≠ 13/29 ⇔ 1/3 = (−7)/k ⇒ k = -21 (Đáp án A)."}, {"id": "e4-m2-q2", "domain": "Advanced Math", "skill": "Quadratic Equations (Vieta's Theorem)", "passage": "What is the sum of the solutions to the equation 2x² − 22x + 5 = 0?", "question": "Find the sum of the solutions.", "options": ["A. −11", "B. 2.5", "C. 11", "D. 22"], "answer": 2, "explanation": "Theo định lý Viète cho phương trình bậc hai ax² + bx + c = 0 (với Δ > 0), tổng hai nghiệm bằng −b/a = −(−22)/2 = 11 (Đáp án C)."}, {"id": "e4-m2-q3", "domain": "Advanced Math", "skill": "Exponential Growth Functions", "passage": "A bacterial colony starts with 500 cells and doubles in population every 7 hours. How many cells will be in the colony after 21 hours?", "question": "Calculate the population after 21 hours.", "options": ["A. 1500", "B. 2000", "C. 4000", "D. 8000"], "answer": 2, "explanation": "Số chu kỳ nhân đôi trong 21 giờ là 21 / 7 = 3 chu kỳ. Số lượng tế bào là P(21) = 500 × 2³ = 500 × 8 = 4000 (Đáp án C)."}, {"id": "e4-m2-q4", "domain": "Geometry and Trigonometry", "skill": "Right Triangle Trigonometry & Complementary Angles", "passage": "In right triangle PQR, angle R = 90° and cos(P) = 6/13. If triangle XYZ is similar to triangle PQR where vertices X, Y, and Z correspond to P, Q, and R, respectively, and each side of triangle XYZ is 6 times the corresponding side of triangle PQR, what is the value of sin(Y)?", "question": "Find the value of sin(Y).", "options": ["A. 6/13", "B. 11/13", "C. 36/13", "D. 13/6"], "answer": 0, "explanation": "Do tam giác XYZ đồng dạng với tam giác PQR nên góc Y = góc Q. Trong tam giác vuông PQR (P + Q = 90°), ta luôn có sin(Y) = sin(Q) = cos(P) = 6/13 (Đáp án A)."}, {"id": "e4-m2-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Weighted Mean & Statistics", "passage": "A dataset consists of 50 observations split into two groups. Group 1 contains 20 observations with a mean of 79, and Group 2 contains 30 observations with a mean of 89. What is the mean of all 50 observations combined?", "question": "Calculate the combined mean.", "options": ["A. 84", "B. 84.5", "C. 85", "D. 86"], "answer": 2, "explanation": "Tổng giá trị cả 2 nhóm là 20 × 79 + 30 × 89 = 4250. Chia cho tổng số 50 quan sát ta được trung bình chung là 85 (Đáp án C)."}]}]}, {"id": "exam-5", "number": 5, "title": "Đề thi thử Digital SAT #5 — Upper-Tier Adaptive Module", "difficulty": "Nâng cao (Hard Adaptive)", "badge": "Adaptive Module 2 Khó", "desc": "Thiết kế theo nhánh Module 2 độ khó cao dành cho học sinh mục tiêu vượt mốc 1400+.", "modules": [{"id": "rw-m1", "name": "Section 1, Module 1: Reading and Writing", "shortName": "R&W Mod 1", "section": "Reading & Writing", "durationMinutes": 32, "directions": "The questions in this section address a number of important reading and writing skills. Each question includes one or more passages, which may include a table or graph. Read each passage and question carefully, and then choose the best answer to the question based on the passage(s).", "questions": [{"id": "e5-rw1-q1", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Far from being ______ wilderness untouched by human hands, large tracts of the Amazon basin contain concentrated groves of Brazil nut and acai palms cultivated by pre-Columbian societies. Researchers noted that these findings help refine contemporary models of ethnobotany Amazonian canopy.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. cultivated", "B. pristine", "C. degraded", "D. synthetic"], "answer": 1, "explanation": "Cấu trúc 'Far from being... untouched by human hands' đòi hỏi từ đồng nghĩa với 'nguyên sơ chưa có bàn tay con người' (pristine)."}, {"id": "e5-rw1-q2", "domain": "Information and Ideas", "skill": "Inferences", "passage": "Neuroimaging studies indicate that lifelong bilingual speakers activate the dorsolateral prefrontal cortex every time they select words in one language while inhibiting the other. Because this neural circuit also governs non-verbal task switching, researchers conclude that ______", "question": "Which choice most logically completes the text?", "options": ["A. bilingual speakers have smaller vocabularies in their primary language than monolinguals do.", "B. routinely managing two linguistic systems strengthens domain-general executive control networks in the brain.", "C. the dorsolateral prefrontal cortex is inactive during reading comprehension tasks.", "D. task switching is controlled exclusively by the auditory cortex."], "answer": 1, "explanation": "Việc liên tục điều phối hai ngôn ngữ giúp rèn luyện mạng lưới điều hành chung của não bộ trong việc chuyển đổi tác vụ (Đáp án B)."}, {"id": "e5-rw1-q3", "domain": "Information and Ideas", "skill": "Command of Evidence (Quantitative)", "passage": "Solar Microgrid Efficiency Across Three Operating Temperatures (Study #5):\n• Panel Type Alpha: 25°C = 22.4% | 45°C = 19.1%\n• Panel Type Beta (Perovskite-Silicon): 25°C = 27.8% | 45°C = 26.9%\n\nEnergy engineers report that while all photovoltaic modules lose efficiency as ambient temperatures rise, Perovskite-Silicon (Type Beta) panels exhibit both higher baseline efficiency and superior thermal stability at 45°C compared to Type Alpha panels.", "question": "Which data from the study most directly support the engineers' report?", "options": ["A. At 25°C, Type Alpha achieves 22.4% efficiency, which is higher than its efficiency at 45°C.", "B. Type Beta starts at 27.8% at 25°C and retains 26.9% at 45°C (a drop of only 0.9%), whereas Type Alpha drops from 22.4% to 19.1%.", "C. Both panel types were tested at exactly 25°C and 45°C under laboratory illumination.", "D. Type Alpha's efficiency at 45°C is 19.1%."], "answer": 1, "explanation": "Đáp án B trích dẫn đầy đủ cả hiệu suất nền cao hơn ở 25°C lẫn mức sụt giảm nhiệt độ rất nhỏ (chỉ 0.9%) ở 45°C của Type Beta so với Type Alpha."}, {"id": "e5-rw1-q4", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "In early trials of autonomous marine gliders (Deployment #5), strong subsurface currents frequently pushed the craft off their programmed survey transects. ______ engineers integrated real-time Doppler velocity logs into the navigation software, enabling the gliders to compensate for lateral drift automatically.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. In response,", "B. Nonetheless,", "C. For example,", "D. Conversely,"], "answer": 0, "hint": "Câu 1 nêu vấn đề kỹ thuật; câu 2 nêu giải pháp khắc phục của các kỹ sư.", "explanation": "'In response,' (Để giải quyết vấn đề đó / Đáp lại thực trạng đó) nối hợp lý giữa sự cố trôi dạt ở câu 1 và cải tiến phần mềm điều hướng ở câu 2 (Đáp án A)."}, {"id": "e5-rw1-q5", "domain": "Standard English Conventions", "skill": "Boundaries & Punctuation", "passage": "The archival collection at the Uppsala University Library houses over 475 medieval botanical codices ______ researchers have digitized only a third of these illuminated manuscripts for public open-access repositories.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. codices, however,", "B. codices; however,", "C. codices however", "D. codices, yet; "], "answer": 1, "explanation": "Hai mệnh đề độc lập nối với trạng từ chuyển tiếp 'however' bắt buộc dùng dấu chấm phẩy trước và dấu phẩy sau: 'codices; however,' (Đáp án B)."}]}, {"id": "rw-m2", "name": "Section 1, Module 2: Reading and Writing (Adaptive)", "shortName": "R&W Mod 2", "section": "Reading & Writing", "durationMinutes": 32, "directions": "This is the second adaptive module of Reading and Writing. Answer every question carefully; there is no penalty for guessing.", "questions": [{"id": "e5-rw2-q1", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "Text 1:\nUrban sociologist Dr. Aris Thorne contends that converting downtown arterial roads into pedestrian-only plazas invariably reduces quarterly retail revenue for ground-floor merchants, because suburban customers rely on curbside parking to visit specialty shops (Case Study #5).\n\nText 2:\nEconomist Mei-Ling Zhou analyzed point-of-sale tax receipts across twelve cities before and after pedestrianization. She found that while drive-in purchases dipped during the first month of construction, total annual retail sales rose by 19% as foot traffic and outdoor dining dwell times increased.", "question": "Based on the texts, how would Zhou (Text 2) most likely characterize Thorne's conclusion in Text 1?", "options": ["A. As an accurate reflection of long-term tax receipt data across all twelve studied cities.", "B. As an overgeneralization that overlooks how increased pedestrian foot traffic more than compensates for reduced curbside parking over a full year.", "C. As proof that outdoor dining establishments should be relocated to suburban shopping malls.", "D. As a valid critique of public transit fare structures."], "answer": 1, "explanation": "Số liệu thực tế cả năm của Zhou (doanh thu tăng nhờ khách đi bộ và ăn uống ngoài trời) bác bỏ dự đoán bi quan của Thorne vốn chỉ nhìn vào việc giảm chỗ đỗ xe (Đáp án B)."}, {"id": "e5-rw2-q2", "domain": "Information and Ideas", "skill": "Command of Evidence (Textual)", "passage": "In a study of avian vocal learning (Cohort #5), neurobiologist Dr. Lucas Vance proposes that juvenile songbirds must hear adult tutor songs during a critical developmental window not merely to copy individual notes, but to calibrate the tempo boundaries between syllables.", "question": "Which finding from Vance's experiment, if true, would most directly support his hypothesis?", "options": ["A. Juvenile songbirds raised in acoustic isolation produced all the correct note frequencies of their species but sang them with erratic, uncoordinated pauses between syllables.", "B. Adult songbirds sang more frequently during spring mornings than during autumn afternoons.", "C. Juvenile songbirds fed a high-protein diet developed larger flight muscles than control birds did.", "D. Different species of finches inhabit distinct canopy heights in tropical rainforests."], "answer": 0, "explanation": "Nếu chim non không được nghe chim trưởng thành vẫn phát ra đúng tần số nốt nhưng lại bị rối loạn khoảng nghỉ/nhịp độ giữa các âm tiết ('erratic pauses between syllables'), điều đó chứng minh trực tiếp vai trò hiệu chỉnh nhịp độ (tempo boundaries) của chim thầy (Đáp án A)."}, {"id": "e5-rw2-q3", "domain": "Standard English Conventions", "skill": "Subject-Verb Agreement & Modifiers", "passage": "Calibrating the 10 interferometer mirrors inside the underground gravitational-wave detector ______ sub-nanometer precision so that passing seismic vibrations from distant ocean waves do not mask astrophysical signals.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. require", "B. requires", "C. have required", "D. are requiring"], "answer": 1, "explanation": "Chủ ngữ chính là danh động từ (gerund phrase) 'Calibrating the ... mirrors' (ngôi thứ ba số ít), không phải 'mirrors' hay 'detector'. Do đó động từ chia số ít là 'requires' (Đáp án B)."}, {"id": "e5-rw2-q4", "domain": "Standard English Conventions", "skill": "Dangling Modifier", "passage": "Synthesized from plant-derived monomers at temperatures below 90°C, ______ ", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. chemical engineers designed the new recyclable polymer to dissolve in mild acidic solutions.", "B. the new recyclable polymer dissolves cleanly when immersed in mild acidic solutions.", "C. mild acidic solutions can dissolve the new recyclable polymer completely.", "D. a breakthrough in sustainable packaging was achieved by the research team."], "answer": 1, "explanation": "Cụm phân từ mở đầu 'Synthesized from plant-derived monomers...' bổ nghĩa cho chất được tổng hợp, tức là 'the new recyclable polymer' phải đứng ngay sau dấu phẩy làm chủ ngữ (Đáp án B)."}, {"id": "e5-rw2-q5", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes (Archive #5):\n• Geothermal district heating circulates naturally warm subterranean water through insulated municipal pipes.\n• In Reykjavik, Iceland, geothermal wells supply space heating to 98% of residential buildings.\n• Transitioning from imported coal to geothermal heating between 1930 and 1970 eliminated winter smog in Reykjavik.\n• Today, the system prevents approximately 3.1 million metric tons of CO₂ emissions annually.", "question": "The student wants to emphasize both the historical and ongoing environmental benefits of Reykjavik's geothermal heating system. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Reykjavik's geothermal district heating system circulates warm subterranean water to 98% of the city's residential buildings.", "B. By replacing imported coal between 1930 and 1970, Reykjavik's geothermal heating system eliminated historical winter smog and continues to prevent 3.1 million metric tons of CO₂ emissions each year.", "C. Geothermal district heating uses insulated municipal pipes to transport subterranean water.", "D. Today, Reykjavik prevents 3.1 million metric tons of CO₂ emissions annually through district heating."], "answer": 1, "explanation": "Đáp án B kết hợp đầy đủ lợi ích môi trường trong lịch sử (xóa bỏ khói bụi than đá giai đoạn 1930–1970) VÀ lợi ích hiện tại (ngăn ngừa hàng triệu tấn CO₂ mỗi năm)."}]}, {"id": "math-m1", "name": "Section 2, Module 1: Math", "shortName": "Math Mod 1", "section": "Math", "durationMinutes": 35, "directions": "The questions in this section address a number of important math skills. Use of an integrated calculator is permitted for all questions. You may open the Reference Sheet at any time.", "questions": [{"id": "e5-m1-q1", "domain": "Algebra", "skill": "Linear Equations in One Variable", "passage": "If 5x − 4 = 2x + 23, what is the value of 4x + 5?", "question": "Select the correct value of 4x + 5.", "options": ["A. 9", "B. 37", "C. 41", "D. 47"], "answer": 2, "explanation": "Chuyển vế: 5x − 2x = 23 + 4 ⇔ 3x = 27 ⇔ x = 9. Thay x = 9 vào biểu thức 4x + 5 ta được 4(9) + 5 = 41 (Đáp án C)."}, {"id": "e5-m1-q2", "domain": "Algebra", "skill": "Systems of Two Linear Equations", "passage": "If (x, y) is the solution to the system of equations below:\n4x + 5y = 67\n5x + 4y = 68\nWhat is the value of x + y?", "question": "Calculate x + y.", "options": ["A. 13", "B. 15", "C. 18", "D. 135"], "answer": 1, "explanation": "Cộng vế theo vế hai phương trình: (4x + 5x) + (5y + 4y) = 67 + 68 ⇔ 9(x + y) = 135. Chia hai vế cho 9 ta được x + y = 15 (Đáp án B)."}, {"id": "e5-m1-q3", "domain": "Advanced Math", "skill": "Quadratic Functions & Vertex", "passage": "The function f is defined by f(x) = x² − 14x + 62. What is the minimum value of f(x)?", "question": "Find the minimum value of f(x).", "options": ["A. 7", "B. 13", "C. 62", "D. −14"], "answer": 1, "explanation": "Hoành độ đỉnh của parabol là x = −b/(2a) = 14/2 = 7 (hoặc ghép bình phương f(x) = (x − 7)² + 13). Giá trị cực tiểu của hàm số là f(7) = 13 (Đáp án B)."}, {"id": "e5-m1-q4", "domain": "Geometry and Trigonometry", "skill": "Circles in the xy-plane", "passage": "In the xy-plane, the graph of the equation x² − 6x + y² + 8y = 75 is a circle. What is the radius of the circle?", "question": "Determine the radius r.", "options": ["A. 8", "B. 10", "C. 20", "D. 100"], "answer": 1, "explanation": "Ghép bình phương hai biến: (x² − 6x + 9) + (y² + 8y + 16) = 75 + 9 + 16 ⇔ (x − 3)² + (y + 4)² = 100 = 10². Vậy bán kính đường tròn là r = 10 (Đáp án B)."}, {"id": "e5-m1-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Percentages", "passage": "A research grant of $300,000 was increased by 50% in Year 2 and then reduced by 20% in Year 3. What was the dollar amount, in thousands, of the grant in Year 3?", "question": "Calculate the Year 3 grant amount (in thousands of dollars).", "options": ["A. $390,000", "B. $360,000", "C. $300,000", "D. $345,000"], "answer": 1, "explanation": "Nhân các hệ số thay đổi liên tiếp: 300 × 1.50 × 0.80 = 300 × 1.20 = 360 (nghìn USD). Đáp án B."}]}, {"id": "math-m2", "name": "Section 2, Module 2: Math (Adaptive)", "shortName": "Math Mod 2", "section": "Math", "durationMinutes": 35, "directions": "This is the second adaptive module of Math. Check your units and review flagged questions before submitting the exam.", "questions": [{"id": "e5-m2-q1", "domain": "Algebra", "skill": "Linear Systems (No Solution Parameter)", "passage": "In the system of linear equations below, k is a constant:\n7x − 8y = 13\n21x + ky = 29\nIf the system has no solution, what is the value of k?", "question": "Find the value of the constant k.", "options": ["A. -24", "B. -8", "C. 24", "D. 16"], "answer": 0, "explanation": "Hệ phương trình vô nghiệm khi hai đường thẳng song song: 7/21 = (−8)/k ≠ 13/29 ⇔ 1/3 = (−8)/k ⇒ k = -24 (Đáp án A)."}, {"id": "e5-m2-q2", "domain": "Advanced Math", "skill": "Quadratic Equations (Vieta's Theorem)", "passage": "What is the sum of the solutions to the equation 2x² − 26x + 6 = 0?", "question": "Find the sum of the solutions.", "options": ["A. −13", "B. 3.0", "C. 13", "D. 26"], "answer": 2, "explanation": "Theo định lý Viète cho phương trình bậc hai ax² + bx + c = 0 (với Δ > 0), tổng hai nghiệm bằng −b/a = −(−26)/2 = 13 (Đáp án C)."}, {"id": "e5-m2-q3", "domain": "Advanced Math", "skill": "Exponential Growth Functions", "passage": "A bacterial colony starts with 550 cells and doubles in population every 4 hours. How many cells will be in the colony after 12 hours?", "question": "Calculate the population after 12 hours.", "options": ["A. 1650", "B. 2200", "C. 4400", "D. 8800"], "answer": 2, "explanation": "Số chu kỳ nhân đôi trong 12 giờ là 12 / 4 = 3 chu kỳ. Số lượng tế bào là P(12) = 550 × 2³ = 550 × 8 = 4400 (Đáp án C)."}, {"id": "e5-m2-q4", "domain": "Geometry and Trigonometry", "skill": "Right Triangle Trigonometry & Complementary Angles", "passage": "In right triangle PQR, angle R = 90° and cos(P) = 5/13. If triangle XYZ is similar to triangle PQR where vertices X, Y, and Z correspond to P, Q, and R, respectively, and each side of triangle XYZ is 7 times the corresponding side of triangle PQR, what is the value of sin(Y)?", "question": "Find the value of sin(Y).", "options": ["A. 5/13", "B. 12/13", "C. 35/13", "D. 13/5"], "answer": 0, "explanation": "Do tam giác XYZ đồng dạng với tam giác PQR nên góc Y = góc Q. Trong tam giác vuông PQR (P + Q = 90°), ta luôn có sin(Y) = sin(Q) = cos(P) = 5/13 (Đáp án A)."}, {"id": "e5-m2-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Weighted Mean & Statistics", "passage": "A dataset consists of 50 observations split into two groups. Group 1 contains 20 observations with a mean of 80, and Group 2 contains 30 observations with a mean of 90. What is the mean of all 50 observations combined?", "question": "Calculate the combined mean.", "options": ["A. 85", "B. 85.5", "C. 86", "D. 87"], "answer": 2, "explanation": "Tổng giá trị cả 2 nhóm là 20 × 80 + 30 × 90 = 4300. Chia cho tổng số 50 quan sát ta được trung bình chung là 86 (Đáp án C)."}]}]}, {"id": "exam-6", "number": 6, "title": "Đề thi thử Digital SAT #6 — Economics, Ecology & Modeling", "difficulty": "Chuẩn College Board (Standard+)", "badge": "Kinh tế & Sinh thái", "desc": "Đề thi kết hợp các chủ đề kinh tế học hành vi, sinh thái học bảo tồn và toán lãi kép / hàm mũ.", "modules": [{"id": "rw-m1", "name": "Section 1, Module 1: Reading and Writing", "shortName": "R&W Mod 1", "section": "Reading & Writing", "durationMinutes": 32, "directions": "The questions in this section address a number of important reading and writing skills. Each question includes one or more passages, which may include a table or graph. Read each passage and question carefully, and then choose the best answer to the question based on the passage(s).", "questions": [{"id": "e6-rw1-q1", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Because premature interest-rate cuts could reignite inflationary pressures, the central bank governor adopted a ______ stance, waiting for three consecutive quarters of stable price data. Researchers noted that these findings help refine contemporary models of monetary policy inflation.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. precipitate", "B. circumspect", "C. impulsive", "D. complacent"], "answer": 1, "explanation": "'Circumspect' (thận trọng, dè dặt) khớp với việc chờ đợi đủ dữ liệu 3 quý liên tiếp."}, {"id": "e6-rw1-q2", "domain": "Information and Ideas", "skill": "Inferences", "passage": "Magnetometer readings from the Galileo spacecraft detected an induced magnetic field around Jupiter's moon Europa as it passed through Jupiter's magnetosphere. Because such an induced field requires a globally continuous, electrically conductive fluid layer beneath the icy crust, planetary scientists inferred that ______", "question": "Which choice most logically completes the text?", "options": ["A. Europa's surface ice is composed entirely of frozen methane.", "B. Europa harbors a subsurface ocean of liquid salty water capable of conducting electricity.", "C. Jupiter's magnetic field is weaker than Earth's magnetic field.", "D. Europa has an iron core identical in size to Earth's core."], "answer": 1, "explanation": "Từ trường cảm ứng đòi hỏi một lớp chất lỏng dẫn điện toàn cầu dưới lớp vỏ băng, suy ra Europa có đại dương nước mặn ngầm (Đáp án B)."}, {"id": "e6-rw1-q3", "domain": "Information and Ideas", "skill": "Command of Evidence (Quantitative)", "passage": "Solar Microgrid Efficiency Across Three Operating Temperatures (Study #6):\n• Panel Type Alpha: 25°C = 23.4% | 45°C = 20.1%\n• Panel Type Beta (Perovskite-Silicon): 25°C = 28.8% | 45°C = 27.9%\n\nEnergy engineers report that while all photovoltaic modules lose efficiency as ambient temperatures rise, Perovskite-Silicon (Type Beta) panels exhibit both higher baseline efficiency and superior thermal stability at 45°C compared to Type Alpha panels.", "question": "Which data from the study most directly support the engineers' report?", "options": ["A. At 25°C, Type Alpha achieves 23.4% efficiency, which is higher than its efficiency at 45°C.", "B. Type Beta starts at 28.8% at 25°C and retains 27.9% at 45°C (a drop of only 0.9%), whereas Type Alpha drops from 23.4% to 20.1%.", "C. Both panel types were tested at exactly 25°C and 45°C under laboratory illumination.", "D. Type Alpha's efficiency at 45°C is 20.1%."], "answer": 1, "explanation": "Đáp án B trích dẫn đầy đủ cả hiệu suất nền cao hơn ở 25°C lẫn mức sụt giảm nhiệt độ rất nhỏ (chỉ 0.9%) ở 45°C của Type Beta so với Type Alpha."}, {"id": "e6-rw1-q4", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "In early trials of autonomous marine gliders (Deployment #6), strong subsurface currents frequently pushed the craft off their programmed survey transects. ______ engineers integrated real-time Doppler velocity logs into the navigation software, enabling the gliders to compensate for lateral drift automatically.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. In response,", "B. Nonetheless,", "C. For example,", "D. Conversely,"], "answer": 0, "hint": "Câu 1 nêu vấn đề kỹ thuật; câu 2 nêu giải pháp khắc phục của các kỹ sư.", "explanation": "'In response,' (Để giải quyết vấn đề đó / Đáp lại thực trạng đó) nối hợp lý giữa sự cố trôi dạt ở câu 1 và cải tiến phần mềm điều hướng ở câu 2 (Đáp án A)."}, {"id": "e6-rw1-q5", "domain": "Standard English Conventions", "skill": "Boundaries & Punctuation", "passage": "The archival collection at the Uppsala University Library houses over 490 medieval botanical codices ______ researchers have digitized only a third of these illuminated manuscripts for public open-access repositories.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. codices, however,", "B. codices; however,", "C. codices however", "D. codices, yet; "], "answer": 1, "explanation": "Hai mệnh đề độc lập nối với trạng từ chuyển tiếp 'however' bắt buộc dùng dấu chấm phẩy trước và dấu phẩy sau: 'codices; however,' (Đáp án B)."}]}, {"id": "rw-m2", "name": "Section 1, Module 2: Reading and Writing (Adaptive)", "shortName": "R&W Mod 2", "section": "Reading & Writing", "durationMinutes": 32, "directions": "This is the second adaptive module of Reading and Writing. Answer every question carefully; there is no penalty for guessing.", "questions": [{"id": "e6-rw2-q1", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "Text 1:\nUrban sociologist Dr. Aris Thorne contends that converting downtown arterial roads into pedestrian-only plazas invariably reduces quarterly retail revenue for ground-floor merchants, because suburban customers rely on curbside parking to visit specialty shops (Case Study #6).\n\nText 2:\nEconomist Mei-Ling Zhou analyzed point-of-sale tax receipts across twelve cities before and after pedestrianization. She found that while drive-in purchases dipped during the first month of construction, total annual retail sales rose by 20% as foot traffic and outdoor dining dwell times increased.", "question": "Based on the texts, how would Zhou (Text 2) most likely characterize Thorne's conclusion in Text 1?", "options": ["A. As an accurate reflection of long-term tax receipt data across all twelve studied cities.", "B. As an overgeneralization that overlooks how increased pedestrian foot traffic more than compensates for reduced curbside parking over a full year.", "C. As proof that outdoor dining establishments should be relocated to suburban shopping malls.", "D. As a valid critique of public transit fare structures."], "answer": 1, "explanation": "Số liệu thực tế cả năm của Zhou (doanh thu tăng nhờ khách đi bộ và ăn uống ngoài trời) bác bỏ dự đoán bi quan của Thorne vốn chỉ nhìn vào việc giảm chỗ đỗ xe (Đáp án B)."}, {"id": "e6-rw2-q2", "domain": "Information and Ideas", "skill": "Command of Evidence (Textual)", "passage": "In a study of avian vocal learning (Cohort #6), neurobiologist Dr. Lucas Vance proposes that juvenile songbirds must hear adult tutor songs during a critical developmental window not merely to copy individual notes, but to calibrate the tempo boundaries between syllables.", "question": "Which finding from Vance's experiment, if true, would most directly support his hypothesis?", "options": ["A. Juvenile songbirds raised in acoustic isolation produced all the correct note frequencies of their species but sang them with erratic, uncoordinated pauses between syllables.", "B. Adult songbirds sang more frequently during spring mornings than during autumn afternoons.", "C. Juvenile songbirds fed a high-protein diet developed larger flight muscles than control birds did.", "D. Different species of finches inhabit distinct canopy heights in tropical rainforests."], "answer": 0, "explanation": "Nếu chim non không được nghe chim trưởng thành vẫn phát ra đúng tần số nốt nhưng lại bị rối loạn khoảng nghỉ/nhịp độ giữa các âm tiết ('erratic pauses between syllables'), điều đó chứng minh trực tiếp vai trò hiệu chỉnh nhịp độ (tempo boundaries) của chim thầy (Đáp án A)."}, {"id": "e6-rw2-q3", "domain": "Standard English Conventions", "skill": "Subject-Verb Agreement & Modifiers", "passage": "Calibrating the 11 interferometer mirrors inside the underground gravitational-wave detector ______ sub-nanometer precision so that passing seismic vibrations from distant ocean waves do not mask astrophysical signals.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. require", "B. requires", "C. have required", "D. are requiring"], "answer": 1, "explanation": "Chủ ngữ chính là danh động từ (gerund phrase) 'Calibrating the ... mirrors' (ngôi thứ ba số ít), không phải 'mirrors' hay 'detector'. Do đó động từ chia số ít là 'requires' (Đáp án B)."}, {"id": "e6-rw2-q4", "domain": "Standard English Conventions", "skill": "Dangling Modifier", "passage": "Synthesized from plant-derived monomers at temperatures below 92°C, ______ ", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. chemical engineers designed the new recyclable polymer to dissolve in mild acidic solutions.", "B. the new recyclable polymer dissolves cleanly when immersed in mild acidic solutions.", "C. mild acidic solutions can dissolve the new recyclable polymer completely.", "D. a breakthrough in sustainable packaging was achieved by the research team."], "answer": 1, "explanation": "Cụm phân từ mở đầu 'Synthesized from plant-derived monomers...' bổ nghĩa cho chất được tổng hợp, tức là 'the new recyclable polymer' phải đứng ngay sau dấu phẩy làm chủ ngữ (Đáp án B)."}, {"id": "e6-rw2-q5", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes (Archive #6):\n• Geothermal district heating circulates naturally warm subterranean water through insulated municipal pipes.\n• In Reykjavik, Iceland, geothermal wells supply space heating to 98% of residential buildings.\n• Transitioning from imported coal to geothermal heating between 1930 and 1970 eliminated winter smog in Reykjavik.\n• Today, the system prevents approximately 4.1 million metric tons of CO₂ emissions annually.", "question": "The student wants to emphasize both the historical and ongoing environmental benefits of Reykjavik's geothermal heating system. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Reykjavik's geothermal district heating system circulates warm subterranean water to 98% of the city's residential buildings.", "B. By replacing imported coal between 1930 and 1970, Reykjavik's geothermal heating system eliminated historical winter smog and continues to prevent 4.1 million metric tons of CO₂ emissions each year.", "C. Geothermal district heating uses insulated municipal pipes to transport subterranean water.", "D. Today, Reykjavik prevents 4.1 million metric tons of CO₂ emissions annually through district heating."], "answer": 1, "explanation": "Đáp án B kết hợp đầy đủ lợi ích môi trường trong lịch sử (xóa bỏ khói bụi than đá giai đoạn 1930–1970) VÀ lợi ích hiện tại (ngăn ngừa hàng triệu tấn CO₂ mỗi năm)."}]}, {"id": "math-m1", "name": "Section 2, Module 1: Math", "shortName": "Math Mod 1", "section": "Math", "durationMinutes": 35, "directions": "The questions in this section address a number of important math skills. Use of an integrated calculator is permitted for all questions. You may open the Reference Sheet at any time.", "questions": [{"id": "e6-m1-q1", "domain": "Algebra", "skill": "Linear Equations in One Variable", "passage": "If 5x − 4 = 2x + 26, what is the value of 4x + 5?", "question": "Select the correct value of 4x + 5.", "options": ["A. 10", "B. 41", "C. 45", "D. 51"], "answer": 2, "explanation": "Chuyển vế: 5x − 2x = 26 + 4 ⇔ 3x = 30 ⇔ x = 10. Thay x = 10 vào biểu thức 4x + 5 ta được 4(10) + 5 = 45 (Đáp án C)."}, {"id": "e6-m1-q2", "domain": "Algebra", "skill": "Systems of Two Linear Equations", "passage": "If (x, y) is the solution to the system of equations below:\n4x + 5y = 71\n5x + 4y = 73\nWhat is the value of x + y?", "question": "Calculate x + y.", "options": ["A. 14", "B. 16", "C. 19", "D. 144"], "answer": 1, "explanation": "Cộng vế theo vế hai phương trình: (4x + 5x) + (5y + 4y) = 71 + 73 ⇔ 9(x + y) = 144. Chia hai vế cho 9 ta được x + y = 16 (Đáp án B)."}, {"id": "e6-m1-q3", "domain": "Advanced Math", "skill": "Quadratic Functions & Vertex", "passage": "The function f is defined by f(x) = x² − 16x + 79. What is the minimum value of f(x)?", "question": "Find the minimum value of f(x).", "options": ["A. 8", "B. 15", "C. 79", "D. −16"], "answer": 1, "explanation": "Hoành độ đỉnh của parabol là x = −b/(2a) = 16/2 = 8 (hoặc ghép bình phương f(x) = (x − 8)² + 15). Giá trị cực tiểu của hàm số là f(8) = 15 (Đáp án B)."}, {"id": "e6-m1-q4", "domain": "Geometry and Trigonometry", "skill": "Circles in the xy-plane", "passage": "In the xy-plane, the graph of the equation x² − 6x + y² + 8y = 96 is a circle. What is the radius of the circle?", "question": "Determine the radius r.", "options": ["A. 9", "B. 11", "C. 22", "D. 121"], "answer": 1, "explanation": "Ghép bình phương hai biến: (x² − 6x + 9) + (y² + 8y + 16) = 96 + 9 + 16 ⇔ (x − 3)² + (y + 4)² = 121 = 11². Vậy bán kính đường tròn là r = 11 (Đáp án B)."}, {"id": "e6-m1-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Percentages", "passage": "A research grant of $320,000 was increased by 50% in Year 2 and then reduced by 20% in Year 3. What was the dollar amount, in thousands, of the grant in Year 3?", "question": "Calculate the Year 3 grant amount (in thousands of dollars).", "options": ["A. $416,000", "B. $384,000", "C. $320,000", "D. $368,000"], "answer": 1, "explanation": "Nhân các hệ số thay đổi liên tiếp: 320 × 1.50 × 0.80 = 320 × 1.20 = 384 (nghìn USD). Đáp án B."}]}, {"id": "math-m2", "name": "Section 2, Module 2: Math (Adaptive)", "shortName": "Math Mod 2", "section": "Math", "durationMinutes": 35, "directions": "This is the second adaptive module of Math. Check your units and review flagged questions before submitting the exam.", "questions": [{"id": "e6-m2-q1", "domain": "Algebra", "skill": "Linear Systems (No Solution Parameter)", "passage": "In the system of linear equations below, k is a constant:\n8x − 4y = 13\n24x + ky = 29\nIf the system has no solution, what is the value of k?", "question": "Find the value of the constant k.", "options": ["A. -12", "B. -4", "C. 12", "D. 8"], "answer": 0, "explanation": "Hệ phương trình vô nghiệm khi hai đường thẳng song song: 8/24 = (−4)/k ≠ 13/29 ⇔ 1/3 = (−4)/k ⇒ k = -12 (Đáp án A)."}, {"id": "e6-m2-q2", "domain": "Advanced Math", "skill": "Quadratic Equations (Vieta's Theorem)", "passage": "What is the sum of the solutions to the equation 2x² − 30x + 7 = 0?", "question": "Find the sum of the solutions.", "options": ["A. −15", "B. 3.5", "C. 15", "D. 30"], "answer": 2, "explanation": "Theo định lý Viète cho phương trình bậc hai ax² + bx + c = 0 (với Δ > 0), tổng hai nghiệm bằng −b/a = −(−30)/2 = 15 (Đáp án C)."}, {"id": "e6-m2-q3", "domain": "Advanced Math", "skill": "Exponential Growth Functions", "passage": "A bacterial colony starts with 600 cells and doubles in population every 5 hours. How many cells will be in the colony after 15 hours?", "question": "Calculate the population after 15 hours.", "options": ["A. 1800", "B. 2400", "C. 4800", "D. 9600"], "answer": 2, "explanation": "Số chu kỳ nhân đôi trong 15 giờ là 15 / 5 = 3 chu kỳ. Số lượng tế bào là P(15) = 600 × 2³ = 600 × 8 = 4800 (Đáp án C)."}, {"id": "e6-m2-q4", "domain": "Geometry and Trigonometry", "skill": "Right Triangle Trigonometry & Complementary Angles", "passage": "In right triangle PQR, angle R = 90° and cos(P) = 6/13. If triangle XYZ is similar to triangle PQR where vertices X, Y, and Z correspond to P, Q, and R, respectively, and each side of triangle XYZ is 8 times the corresponding side of triangle PQR, what is the value of sin(Y)?", "question": "Find the value of sin(Y).", "options": ["A. 6/13", "B. 11/13", "C. 48/13", "D. 13/6"], "answer": 0, "explanation": "Do tam giác XYZ đồng dạng với tam giác PQR nên góc Y = góc Q. Trong tam giác vuông PQR (P + Q = 90°), ta luôn có sin(Y) = sin(Q) = cos(P) = 6/13 (Đáp án A)."}, {"id": "e6-m2-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Weighted Mean & Statistics", "passage": "A dataset consists of 50 observations split into two groups. Group 1 contains 20 observations with a mean of 81, and Group 2 contains 30 observations with a mean of 91. What is the mean of all 50 observations combined?", "question": "Calculate the combined mean.", "options": ["A. 86", "B. 86.5", "C. 87", "D. 88"], "answer": 2, "explanation": "Tổng giá trị cả 2 nhóm là 20 × 81 + 30 × 91 = 4350. Chia cho tổng số 50 quan sát ta được trung bình chung là 87 (Đáp án C)."}]}]}, {"id": "exam-7", "number": 7, "title": "Đề thi thử Digital SAT #7 — Precision Grammar & Nonlinear Math", "difficulty": "Nâng cao (Hard)", "badge": "Ngữ pháp & Hàm phi tuyến", "desc": "Xoáy sâu vào các bẫy dấu câu Boundaries, bổ ngữ treo, định lý Viète và phương trình đường tròn.", "modules": [{"id": "rw-m1", "name": "Section 1, Module 1: Reading and Writing", "shortName": "R&W Mod 1", "section": "Reading & Writing", "durationMinutes": 32, "directions": "The questions in this section address a number of important reading and writing skills. Each question includes one or more passages, which may include a table or graph. Read each passage and question carefully, and then choose the best answer to the question based on the passage(s).", "questions": [{"id": "e7-rw1-q1", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Before the 1977 discovery of thriving tubeworm colonies around deep-sea hydrothermal vents, marine biologists considered sunlight to be an ______ prerequisite for all complex ecosystems. Researchers noted that these findings help refine contemporary models of deep-sea hydrothermal vents.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. optional", "B. indispensable", "C. inconsequential", "D. ephemeral"], "answer": 1, "explanation": "Trước năm 1977, các nhà sinh học từng coi ánh sáng mặt trời là điều kiện 'không thể thiếu' (indispensable)."}, {"id": "e7-rw1-q2", "domain": "Information and Ideas", "skill": "Inferences", "passage": "Because animal-skin parchment was expensive to produce in medieval Europe, scribes frequently scraped the ink off older manuscripts to reuse the sheets for new texts, creating 'palimpsests.' Because iron-gall ink leaves trace chemical imprints in the collagen fibers even after scraping, modern multispectral imaging allows scholars to ______", "question": "Which choice most logically completes the text?", "options": ["A. convert medieval paper manuscripts into animal parchment.", "B. recover and read erased classical and early medieval texts that lie beneath the visible writing.", "C. date the age of the wooden bindings without opening the books.", "D. prevent modern ink from fading under museum lighting."], "answer": 1, "explanation": "Dấu vết hóa học của mực sắt còn lưu lại trong sợi collagen giúp ảnh đa phổ khôi phục và đọc lại văn bản cổ đã bị cạo xóa (Đáp án B)."}, {"id": "e7-rw1-q3", "domain": "Information and Ideas", "skill": "Command of Evidence (Quantitative)", "passage": "Solar Microgrid Efficiency Across Three Operating Temperatures (Study #7):\n• Panel Type Alpha: 25°C = 21.4% | 45°C = 18.1%\n• Panel Type Beta (Perovskite-Silicon): 25°C = 26.8% | 45°C = 25.9%\n\nEnergy engineers report that while all photovoltaic modules lose efficiency as ambient temperatures rise, Perovskite-Silicon (Type Beta) panels exhibit both higher baseline efficiency and superior thermal stability at 45°C compared to Type Alpha panels.", "question": "Which data from the study most directly support the engineers' report?", "options": ["A. At 25°C, Type Alpha achieves 21.4% efficiency, which is higher than its efficiency at 45°C.", "B. Type Beta starts at 26.8% at 25°C and retains 25.9% at 45°C (a drop of only 0.9%), whereas Type Alpha drops from 21.4% to 18.1%.", "C. Both panel types were tested at exactly 25°C and 45°C under laboratory illumination.", "D. Type Alpha's efficiency at 45°C is 18.1%."], "answer": 1, "explanation": "Đáp án B trích dẫn đầy đủ cả hiệu suất nền cao hơn ở 25°C lẫn mức sụt giảm nhiệt độ rất nhỏ (chỉ 0.9%) ở 45°C của Type Beta so với Type Alpha."}, {"id": "e7-rw1-q4", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "In early trials of autonomous marine gliders (Deployment #7), strong subsurface currents frequently pushed the craft off their programmed survey transects. ______ engineers integrated real-time Doppler velocity logs into the navigation software, enabling the gliders to compensate for lateral drift automatically.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. In response,", "B. Nonetheless,", "C. For example,", "D. Conversely,"], "answer": 0, "hint": "Câu 1 nêu vấn đề kỹ thuật; câu 2 nêu giải pháp khắc phục của các kỹ sư.", "explanation": "'In response,' (Để giải quyết vấn đề đó / Đáp lại thực trạng đó) nối hợp lý giữa sự cố trôi dạt ở câu 1 và cải tiến phần mềm điều hướng ở câu 2 (Đáp án A)."}, {"id": "e7-rw1-q5", "domain": "Standard English Conventions", "skill": "Boundaries & Punctuation", "passage": "The archival collection at the Uppsala University Library houses over 505 medieval botanical codices ______ researchers have digitized only a third of these illuminated manuscripts for public open-access repositories.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. codices, however,", "B. codices; however,", "C. codices however", "D. codices, yet; "], "answer": 1, "explanation": "Hai mệnh đề độc lập nối với trạng từ chuyển tiếp 'however' bắt buộc dùng dấu chấm phẩy trước và dấu phẩy sau: 'codices; however,' (Đáp án B)."}]}, {"id": "rw-m2", "name": "Section 1, Module 2: Reading and Writing (Adaptive)", "shortName": "R&W Mod 2", "section": "Reading & Writing", "durationMinutes": 32, "directions": "This is the second adaptive module of Reading and Writing. Answer every question carefully; there is no penalty for guessing.", "questions": [{"id": "e7-rw2-q1", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "Text 1:\nUrban sociologist Dr. Aris Thorne contends that converting downtown arterial roads into pedestrian-only plazas invariably reduces quarterly retail revenue for ground-floor merchants, because suburban customers rely on curbside parking to visit specialty shops (Case Study #7).\n\nText 2:\nEconomist Mei-Ling Zhou analyzed point-of-sale tax receipts across twelve cities before and after pedestrianization. She found that while drive-in purchases dipped during the first month of construction, total annual retail sales rose by 21% as foot traffic and outdoor dining dwell times increased.", "question": "Based on the texts, how would Zhou (Text 2) most likely characterize Thorne's conclusion in Text 1?", "options": ["A. As an accurate reflection of long-term tax receipt data across all twelve studied cities.", "B. As an overgeneralization that overlooks how increased pedestrian foot traffic more than compensates for reduced curbside parking over a full year.", "C. As proof that outdoor dining establishments should be relocated to suburban shopping malls.", "D. As a valid critique of public transit fare structures."], "answer": 1, "explanation": "Số liệu thực tế cả năm của Zhou (doanh thu tăng nhờ khách đi bộ và ăn uống ngoài trời) bác bỏ dự đoán bi quan của Thorne vốn chỉ nhìn vào việc giảm chỗ đỗ xe (Đáp án B)."}, {"id": "e7-rw2-q2", "domain": "Information and Ideas", "skill": "Command of Evidence (Textual)", "passage": "In a study of avian vocal learning (Cohort #7), neurobiologist Dr. Lucas Vance proposes that juvenile songbirds must hear adult tutor songs during a critical developmental window not merely to copy individual notes, but to calibrate the tempo boundaries between syllables.", "question": "Which finding from Vance's experiment, if true, would most directly support his hypothesis?", "options": ["A. Juvenile songbirds raised in acoustic isolation produced all the correct note frequencies of their species but sang them with erratic, uncoordinated pauses between syllables.", "B. Adult songbirds sang more frequently during spring mornings than during autumn afternoons.", "C. Juvenile songbirds fed a high-protein diet developed larger flight muscles than control birds did.", "D. Different species of finches inhabit distinct canopy heights in tropical rainforests."], "answer": 0, "explanation": "Nếu chim non không được nghe chim trưởng thành vẫn phát ra đúng tần số nốt nhưng lại bị rối loạn khoảng nghỉ/nhịp độ giữa các âm tiết ('erratic pauses between syllables'), điều đó chứng minh trực tiếp vai trò hiệu chỉnh nhịp độ (tempo boundaries) của chim thầy (Đáp án A)."}, {"id": "e7-rw2-q3", "domain": "Standard English Conventions", "skill": "Subject-Verb Agreement & Modifiers", "passage": "Calibrating the 12 interferometer mirrors inside the underground gravitational-wave detector ______ sub-nanometer precision so that passing seismic vibrations from distant ocean waves do not mask astrophysical signals.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. require", "B. requires", "C. have required", "D. are requiring"], "answer": 1, "explanation": "Chủ ngữ chính là danh động từ (gerund phrase) 'Calibrating the ... mirrors' (ngôi thứ ba số ít), không phải 'mirrors' hay 'detector'. Do đó động từ chia số ít là 'requires' (Đáp án B)."}, {"id": "e7-rw2-q4", "domain": "Standard English Conventions", "skill": "Dangling Modifier", "passage": "Synthesized from plant-derived monomers at temperatures below 94°C, ______ ", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. chemical engineers designed the new recyclable polymer to dissolve in mild acidic solutions.", "B. the new recyclable polymer dissolves cleanly when immersed in mild acidic solutions.", "C. mild acidic solutions can dissolve the new recyclable polymer completely.", "D. a breakthrough in sustainable packaging was achieved by the research team."], "answer": 1, "explanation": "Cụm phân từ mở đầu 'Synthesized from plant-derived monomers...' bổ nghĩa cho chất được tổng hợp, tức là 'the new recyclable polymer' phải đứng ngay sau dấu phẩy làm chủ ngữ (Đáp án B)."}, {"id": "e7-rw2-q5", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes (Archive #7):\n• Geothermal district heating circulates naturally warm subterranean water through insulated municipal pipes.\n• In Reykjavik, Iceland, geothermal wells supply space heating to 98% of residential buildings.\n• Transitioning from imported coal to geothermal heating between 1930 and 1970 eliminated winter smog in Reykjavik.\n• Today, the system prevents approximately 2.1 million metric tons of CO₂ emissions annually.", "question": "The student wants to emphasize both the historical and ongoing environmental benefits of Reykjavik's geothermal heating system. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Reykjavik's geothermal district heating system circulates warm subterranean water to 98% of the city's residential buildings.", "B. By replacing imported coal between 1930 and 1970, Reykjavik's geothermal heating system eliminated historical winter smog and continues to prevent 2.1 million metric tons of CO₂ emissions each year.", "C. Geothermal district heating uses insulated municipal pipes to transport subterranean water.", "D. Today, Reykjavik prevents 2.1 million metric tons of CO₂ emissions annually through district heating."], "answer": 1, "explanation": "Đáp án B kết hợp đầy đủ lợi ích môi trường trong lịch sử (xóa bỏ khói bụi than đá giai đoạn 1930–1970) VÀ lợi ích hiện tại (ngăn ngừa hàng triệu tấn CO₂ mỗi năm)."}]}, {"id": "math-m1", "name": "Section 2, Module 1: Math", "shortName": "Math Mod 1", "section": "Math", "durationMinutes": 35, "directions": "The questions in this section address a number of important math skills. Use of an integrated calculator is permitted for all questions. You may open the Reference Sheet at any time.", "questions": [{"id": "e7-m1-q1", "domain": "Algebra", "skill": "Linear Equations in One Variable", "passage": "If 5x − 4 = 2x + 29, what is the value of 4x + 5?", "question": "Select the correct value of 4x + 5.", "options": ["A. 11", "B. 45", "C. 49", "D. 55"], "answer": 2, "explanation": "Chuyển vế: 5x − 2x = 29 + 4 ⇔ 3x = 33 ⇔ x = 11. Thay x = 11 vào biểu thức 4x + 5 ta được 4(11) + 5 = 49 (Đáp án C)."}, {"id": "e7-m1-q2", "domain": "Algebra", "skill": "Systems of Two Linear Equations", "passage": "If (x, y) is the solution to the system of equations below:\n4x + 5y = 75\n5x + 4y = 78\nWhat is the value of x + y?", "question": "Calculate x + y.", "options": ["A. 15", "B. 17", "C. 20", "D. 153"], "answer": 1, "explanation": "Cộng vế theo vế hai phương trình: (4x + 5x) + (5y + 4y) = 75 + 78 ⇔ 9(x + y) = 153. Chia hai vế cho 9 ta được x + y = 17 (Đáp án B)."}, {"id": "e7-m1-q3", "domain": "Advanced Math", "skill": "Quadratic Functions & Vertex", "passage": "The function f is defined by f(x) = x² − 18x + 98. What is the minimum value of f(x)?", "question": "Find the minimum value of f(x).", "options": ["A. 9", "B. 17", "C. 98", "D. −18"], "answer": 1, "explanation": "Hoành độ đỉnh của parabol là x = −b/(2a) = 18/2 = 9 (hoặc ghép bình phương f(x) = (x − 9)² + 17). Giá trị cực tiểu của hàm số là f(9) = 17 (Đáp án B)."}, {"id": "e7-m1-q4", "domain": "Geometry and Trigonometry", "skill": "Circles in the xy-plane", "passage": "In the xy-plane, the graph of the equation x² − 6x + y² + 8y = 119 is a circle. What is the radius of the circle?", "question": "Determine the radius r.", "options": ["A. 10", "B. 12", "C. 24", "D. 144"], "answer": 1, "explanation": "Ghép bình phương hai biến: (x² − 6x + 9) + (y² + 8y + 16) = 119 + 9 + 16 ⇔ (x − 3)² + (y + 4)² = 144 = 12². Vậy bán kính đường tròn là r = 12 (Đáp án B)."}, {"id": "e7-m1-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Percentages", "passage": "A research grant of $340,000 was increased by 50% in Year 2 and then reduced by 20% in Year 3. What was the dollar amount, in thousands, of the grant in Year 3?", "question": "Calculate the Year 3 grant amount (in thousands of dollars).", "options": ["A. $442,000", "B. $408,000", "C. $340,000", "D. $390,000"], "answer": 1, "explanation": "Nhân các hệ số thay đổi liên tiếp: 340 × 1.50 × 0.80 = 340 × 1.20 = 408 (nghìn USD). Đáp án B."}]}, {"id": "math-m2", "name": "Section 2, Module 2: Math (Adaptive)", "shortName": "Math Mod 2", "section": "Math", "durationMinutes": 35, "directions": "This is the second adaptive module of Math. Check your units and review flagged questions before submitting the exam.", "questions": [{"id": "e7-m2-q1", "domain": "Algebra", "skill": "Linear Systems (No Solution Parameter)", "passage": "In the system of linear equations below, k is a constant:\n9x − 5y = 13\n27x + ky = 29\nIf the system has no solution, what is the value of k?", "question": "Find the value of the constant k.", "options": ["A. -15", "B. -5", "C. 15", "D. 10"], "answer": 0, "explanation": "Hệ phương trình vô nghiệm khi hai đường thẳng song song: 9/27 = (−5)/k ≠ 13/29 ⇔ 1/3 = (−5)/k ⇒ k = -15 (Đáp án A)."}, {"id": "e7-m2-q2", "domain": "Advanced Math", "skill": "Quadratic Equations (Vieta's Theorem)", "passage": "What is the sum of the solutions to the equation 2x² − 34x + 8 = 0?", "question": "Find the sum of the solutions.", "options": ["A. −17", "B. 4.0", "C. 17", "D. 34"], "answer": 2, "explanation": "Theo định lý Viète cho phương trình bậc hai ax² + bx + c = 0 (với Δ > 0), tổng hai nghiệm bằng −b/a = −(−34)/2 = 17 (Đáp án C)."}, {"id": "e7-m2-q3", "domain": "Advanced Math", "skill": "Exponential Growth Functions", "passage": "A bacterial colony starts with 650 cells and doubles in population every 6 hours. How many cells will be in the colony after 18 hours?", "question": "Calculate the population after 18 hours.", "options": ["A. 1950", "B. 2600", "C. 5200", "D. 10400"], "answer": 2, "explanation": "Số chu kỳ nhân đôi trong 18 giờ là 18 / 6 = 3 chu kỳ. Số lượng tế bào là P(18) = 650 × 2³ = 650 × 8 = 5200 (Đáp án C)."}, {"id": "e7-m2-q4", "domain": "Geometry and Trigonometry", "skill": "Right Triangle Trigonometry & Complementary Angles", "passage": "In right triangle PQR, angle R = 90° and cos(P) = 5/13. If triangle XYZ is similar to triangle PQR where vertices X, Y, and Z correspond to P, Q, and R, respectively, and each side of triangle XYZ is 9 times the corresponding side of triangle PQR, what is the value of sin(Y)?", "question": "Find the value of sin(Y).", "options": ["A. 5/13", "B. 12/13", "C. 45/13", "D. 13/5"], "answer": 0, "explanation": "Do tam giác XYZ đồng dạng với tam giác PQR nên góc Y = góc Q. Trong tam giác vuông PQR (P + Q = 90°), ta luôn có sin(Y) = sin(Q) = cos(P) = 5/13 (Đáp án A)."}, {"id": "e7-m2-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Weighted Mean & Statistics", "passage": "A dataset consists of 50 observations split into two groups. Group 1 contains 20 observations with a mean of 82, and Group 2 contains 30 observations with a mean of 92. What is the mean of all 50 observations combined?", "question": "Calculate the combined mean.", "options": ["A. 87", "B. 87.5", "C. 88", "D. 89"], "answer": 2, "explanation": "Tổng giá trị cả 2 nhóm là 20 × 82 + 30 × 92 = 4400. Chia cho tổng số 50 quan sát ta được trung bình chung là 88 (Đáp án C)."}]}]}, {"id": "exam-8", "number": 8, "title": "Đề thi thử Digital SAT #8 — Speed & Accuracy Benchmark", "difficulty": "Khá - Giỏi (Upper-Intermediate)", "badge": "Luyện tốc độ", "desc": "Tối ưu hóa kỹ năng phân bổ thời gian 71 giây/câu R&W và 95 giây/câu Math với các câu bẫy tư duy nhanh.", "modules": [{"id": "rw-m1", "name": "Section 1, Module 1: Reading and Writing", "shortName": "R&W Mod 1", "section": "Reading & Writing", "durationMinutes": 32, "directions": "The questions in this section address a number of important reading and writing skills. Each question includes one or more passages, which may include a table or graph. Read each passage and question carefully, and then choose the best answer to the question based on the passage(s).", "questions": [{"id": "e8-rw1-q1", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Translating Homer's Odyssey into modern verse requires balancing literal accuracy against poetic rhythm, a tension that has ______ translators for centuries. Researchers noted that these findings help refine contemporary models of classical philology translation.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. pacified", "B. preoccupied", "C. indifferent", "D. exonerated"], "answer": 1, "explanation": "'Preoccupied' (làm bận tâm, thu hút sự trăn trở) của các dịch giả suốt nhiều thế kỷ."}, {"id": "e8-rw1-q2", "domain": "Information and Ideas", "skill": "Inferences", "passage": "Most lowland humans who ascend above 4,000 meters respond to low oxygen by overproducing red blood cells, which thickens the blood and raises stroke risk. Indigenous Tibetan highlanders, however, carry a variant of the EPAS1 gene that maintains normal hemoglobin concentrations while enhancing nitric oxide blood flow, meaning that ______", "question": "Which choice most logically completes the text?", "options": ["A. Tibetan highlanders experience higher rates of altitude sickness than lowland climbers do.", "B. their evolutionary adaptation achieves efficient tissue oxygenation without the cardiovascular risks of thickened blood.", "C. the EPAS1 gene prevents nitric oxide from entering the bloodstream.", "D. hemoglobin production stops completely at elevations above 4,000 meters."], "answer": 1, "explanation": "Biến thể gen EPAS1 giúp người Tây Tạng cung cấp đủ oxy cho mô thông qua tăng lưu lượng máu mà không làm đặc máu gây nguy cơ đột quỵ (Đáp án B)."}, {"id": "e8-rw1-q3", "domain": "Information and Ideas", "skill": "Command of Evidence (Quantitative)", "passage": "Solar Microgrid Efficiency Across Three Operating Temperatures (Study #8):\n• Panel Type Alpha: 25°C = 22.4% | 45°C = 19.1%\n• Panel Type Beta (Perovskite-Silicon): 25°C = 27.8% | 45°C = 26.9%\n\nEnergy engineers report that while all photovoltaic modules lose efficiency as ambient temperatures rise, Perovskite-Silicon (Type Beta) panels exhibit both higher baseline efficiency and superior thermal stability at 45°C compared to Type Alpha panels.", "question": "Which data from the study most directly support the engineers' report?", "options": ["A. At 25°C, Type Alpha achieves 22.4% efficiency, which is higher than its efficiency at 45°C.", "B. Type Beta starts at 27.8% at 25°C and retains 26.9% at 45°C (a drop of only 0.9%), whereas Type Alpha drops from 22.4% to 19.1%.", "C. Both panel types were tested at exactly 25°C and 45°C under laboratory illumination.", "D. Type Alpha's efficiency at 45°C is 19.1%."], "answer": 1, "explanation": "Đáp án B trích dẫn đầy đủ cả hiệu suất nền cao hơn ở 25°C lẫn mức sụt giảm nhiệt độ rất nhỏ (chỉ 0.9%) ở 45°C của Type Beta so với Type Alpha."}, {"id": "e8-rw1-q4", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "In early trials of autonomous marine gliders (Deployment #8), strong subsurface currents frequently pushed the craft off their programmed survey transects. ______ engineers integrated real-time Doppler velocity logs into the navigation software, enabling the gliders to compensate for lateral drift automatically.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. In response,", "B. Nonetheless,", "C. For example,", "D. Conversely,"], "answer": 0, "hint": "Câu 1 nêu vấn đề kỹ thuật; câu 2 nêu giải pháp khắc phục của các kỹ sư.", "explanation": "'In response,' (Để giải quyết vấn đề đó / Đáp lại thực trạng đó) nối hợp lý giữa sự cố trôi dạt ở câu 1 và cải tiến phần mềm điều hướng ở câu 2 (Đáp án A)."}, {"id": "e8-rw1-q5", "domain": "Standard English Conventions", "skill": "Boundaries & Punctuation", "passage": "The archival collection at the Uppsala University Library houses over 520 medieval botanical codices ______ researchers have digitized only a third of these illuminated manuscripts for public open-access repositories.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. codices, however,", "B. codices; however,", "C. codices however", "D. codices, yet; "], "answer": 1, "explanation": "Hai mệnh đề độc lập nối với trạng từ chuyển tiếp 'however' bắt buộc dùng dấu chấm phẩy trước và dấu phẩy sau: 'codices; however,' (Đáp án B)."}]}, {"id": "rw-m2", "name": "Section 1, Module 2: Reading and Writing (Adaptive)", "shortName": "R&W Mod 2", "section": "Reading & Writing", "durationMinutes": 32, "directions": "This is the second adaptive module of Reading and Writing. Answer every question carefully; there is no penalty for guessing.", "questions": [{"id": "e8-rw2-q1", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "Text 1:\nUrban sociologist Dr. Aris Thorne contends that converting downtown arterial roads into pedestrian-only plazas invariably reduces quarterly retail revenue for ground-floor merchants, because suburban customers rely on curbside parking to visit specialty shops (Case Study #8).\n\nText 2:\nEconomist Mei-Ling Zhou analyzed point-of-sale tax receipts across twelve cities before and after pedestrianization. She found that while drive-in purchases dipped during the first month of construction, total annual retail sales rose by 22% as foot traffic and outdoor dining dwell times increased.", "question": "Based on the texts, how would Zhou (Text 2) most likely characterize Thorne's conclusion in Text 1?", "options": ["A. As an accurate reflection of long-term tax receipt data across all twelve studied cities.", "B. As an overgeneralization that overlooks how increased pedestrian foot traffic more than compensates for reduced curbside parking over a full year.", "C. As proof that outdoor dining establishments should be relocated to suburban shopping malls.", "D. As a valid critique of public transit fare structures."], "answer": 1, "explanation": "Số liệu thực tế cả năm của Zhou (doanh thu tăng nhờ khách đi bộ và ăn uống ngoài trời) bác bỏ dự đoán bi quan của Thorne vốn chỉ nhìn vào việc giảm chỗ đỗ xe (Đáp án B)."}, {"id": "e8-rw2-q2", "domain": "Information and Ideas", "skill": "Command of Evidence (Textual)", "passage": "In a study of avian vocal learning (Cohort #8), neurobiologist Dr. Lucas Vance proposes that juvenile songbirds must hear adult tutor songs during a critical developmental window not merely to copy individual notes, but to calibrate the tempo boundaries between syllables.", "question": "Which finding from Vance's experiment, if true, would most directly support his hypothesis?", "options": ["A. Juvenile songbirds raised in acoustic isolation produced all the correct note frequencies of their species but sang them with erratic, uncoordinated pauses between syllables.", "B. Adult songbirds sang more frequently during spring mornings than during autumn afternoons.", "C. Juvenile songbirds fed a high-protein diet developed larger flight muscles than control birds did.", "D. Different species of finches inhabit distinct canopy heights in tropical rainforests."], "answer": 0, "explanation": "Nếu chim non không được nghe chim trưởng thành vẫn phát ra đúng tần số nốt nhưng lại bị rối loạn khoảng nghỉ/nhịp độ giữa các âm tiết ('erratic pauses between syllables'), điều đó chứng minh trực tiếp vai trò hiệu chỉnh nhịp độ (tempo boundaries) của chim thầy (Đáp án A)."}, {"id": "e8-rw2-q3", "domain": "Standard English Conventions", "skill": "Subject-Verb Agreement & Modifiers", "passage": "Calibrating the 13 interferometer mirrors inside the underground gravitational-wave detector ______ sub-nanometer precision so that passing seismic vibrations from distant ocean waves do not mask astrophysical signals.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. require", "B. requires", "C. have required", "D. are requiring"], "answer": 1, "explanation": "Chủ ngữ chính là danh động từ (gerund phrase) 'Calibrating the ... mirrors' (ngôi thứ ba số ít), không phải 'mirrors' hay 'detector'. Do đó động từ chia số ít là 'requires' (Đáp án B)."}, {"id": "e8-rw2-q4", "domain": "Standard English Conventions", "skill": "Dangling Modifier", "passage": "Synthesized from plant-derived monomers at temperatures below 96°C, ______ ", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. chemical engineers designed the new recyclable polymer to dissolve in mild acidic solutions.", "B. the new recyclable polymer dissolves cleanly when immersed in mild acidic solutions.", "C. mild acidic solutions can dissolve the new recyclable polymer completely.", "D. a breakthrough in sustainable packaging was achieved by the research team."], "answer": 1, "explanation": "Cụm phân từ mở đầu 'Synthesized from plant-derived monomers...' bổ nghĩa cho chất được tổng hợp, tức là 'the new recyclable polymer' phải đứng ngay sau dấu phẩy làm chủ ngữ (Đáp án B)."}, {"id": "e8-rw2-q5", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes (Archive #8):\n• Geothermal district heating circulates naturally warm subterranean water through insulated municipal pipes.\n• In Reykjavik, Iceland, geothermal wells supply space heating to 98% of residential buildings.\n• Transitioning from imported coal to geothermal heating between 1930 and 1970 eliminated winter smog in Reykjavik.\n• Today, the system prevents approximately 3.1 million metric tons of CO₂ emissions annually.", "question": "The student wants to emphasize both the historical and ongoing environmental benefits of Reykjavik's geothermal heating system. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Reykjavik's geothermal district heating system circulates warm subterranean water to 98% of the city's residential buildings.", "B. By replacing imported coal between 1930 and 1970, Reykjavik's geothermal heating system eliminated historical winter smog and continues to prevent 3.1 million metric tons of CO₂ emissions each year.", "C. Geothermal district heating uses insulated municipal pipes to transport subterranean water.", "D. Today, Reykjavik prevents 3.1 million metric tons of CO₂ emissions annually through district heating."], "answer": 1, "explanation": "Đáp án B kết hợp đầy đủ lợi ích môi trường trong lịch sử (xóa bỏ khói bụi than đá giai đoạn 1930–1970) VÀ lợi ích hiện tại (ngăn ngừa hàng triệu tấn CO₂ mỗi năm)."}]}, {"id": "math-m1", "name": "Section 2, Module 1: Math", "shortName": "Math Mod 1", "section": "Math", "durationMinutes": 35, "directions": "The questions in this section address a number of important math skills. Use of an integrated calculator is permitted for all questions. You may open the Reference Sheet at any time.", "questions": [{"id": "e8-m1-q1", "domain": "Algebra", "skill": "Linear Equations in One Variable", "passage": "If 5x − 4 = 2x + 32, what is the value of 4x + 5?", "question": "Select the correct value of 4x + 5.", "options": ["A. 12", "B. 49", "C. 53", "D. 59"], "answer": 2, "explanation": "Chuyển vế: 5x − 2x = 32 + 4 ⇔ 3x = 36 ⇔ x = 12. Thay x = 12 vào biểu thức 4x + 5 ta được 4(12) + 5 = 53 (Đáp án C)."}, {"id": "e8-m1-q2", "domain": "Algebra", "skill": "Systems of Two Linear Equations", "passage": "If (x, y) is the solution to the system of equations below:\n4x + 5y = 79\n5x + 4y = 83\nWhat is the value of x + y?", "question": "Calculate x + y.", "options": ["A. 16", "B. 18", "C. 21", "D. 162"], "answer": 1, "explanation": "Cộng vế theo vế hai phương trình: (4x + 5x) + (5y + 4y) = 79 + 83 ⇔ 9(x + y) = 162. Chia hai vế cho 9 ta được x + y = 18 (Đáp án B)."}, {"id": "e8-m1-q3", "domain": "Advanced Math", "skill": "Quadratic Functions & Vertex", "passage": "The function f is defined by f(x) = x² − 20x + 119. What is the minimum value of f(x)?", "question": "Find the minimum value of f(x).", "options": ["A. 10", "B. 19", "C. 119", "D. −20"], "answer": 1, "explanation": "Hoành độ đỉnh của parabol là x = −b/(2a) = 20/2 = 10 (hoặc ghép bình phương f(x) = (x − 10)² + 19). Giá trị cực tiểu của hàm số là f(10) = 19 (Đáp án B)."}, {"id": "e8-m1-q4", "domain": "Geometry and Trigonometry", "skill": "Circles in the xy-plane", "passage": "In the xy-plane, the graph of the equation x² − 6x + y² + 8y = 144 is a circle. What is the radius of the circle?", "question": "Determine the radius r.", "options": ["A. 11", "B. 13", "C. 26", "D. 169"], "answer": 1, "explanation": "Ghép bình phương hai biến: (x² − 6x + 9) + (y² + 8y + 16) = 144 + 9 + 16 ⇔ (x − 3)² + (y + 4)² = 169 = 13². Vậy bán kính đường tròn là r = 13 (Đáp án B)."}, {"id": "e8-m1-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Percentages", "passage": "A research grant of $360,000 was increased by 50% in Year 2 and then reduced by 20% in Year 3. What was the dollar amount, in thousands, of the grant in Year 3?", "question": "Calculate the Year 3 grant amount (in thousands of dollars).", "options": ["A. $468,000", "B. $432,000", "C. $360,000", "D. $413,000"], "answer": 1, "explanation": "Nhân các hệ số thay đổi liên tiếp: 360 × 1.50 × 0.80 = 360 × 1.20 = 432 (nghìn USD). Đáp án B."}]}, {"id": "math-m2", "name": "Section 2, Module 2: Math (Adaptive)", "shortName": "Math Mod 2", "section": "Math", "durationMinutes": 35, "directions": "This is the second adaptive module of Math. Check your units and review flagged questions before submitting the exam.", "questions": [{"id": "e8-m2-q1", "domain": "Algebra", "skill": "Linear Systems (No Solution Parameter)", "passage": "In the system of linear equations below, k is a constant:\n10x − 6y = 13\n30x + ky = 29\nIf the system has no solution, what is the value of k?", "question": "Find the value of the constant k.", "options": ["A. -18", "B. -6", "C. 18", "D. 12"], "answer": 0, "explanation": "Hệ phương trình vô nghiệm khi hai đường thẳng song song: 10/30 = (−6)/k ≠ 13/29 ⇔ 1/3 = (−6)/k ⇒ k = -18 (Đáp án A)."}, {"id": "e8-m2-q2", "domain": "Advanced Math", "skill": "Quadratic Equations (Vieta's Theorem)", "passage": "What is the sum of the solutions to the equation 2x² − 38x + 9 = 0?", "question": "Find the sum of the solutions.", "options": ["A. −19", "B. 4.5", "C. 19", "D. 38"], "answer": 2, "explanation": "Theo định lý Viète cho phương trình bậc hai ax² + bx + c = 0 (với Δ > 0), tổng hai nghiệm bằng −b/a = −(−38)/2 = 19 (Đáp án C)."}, {"id": "e8-m2-q3", "domain": "Advanced Math", "skill": "Exponential Growth Functions", "passage": "A bacterial colony starts with 700 cells and doubles in population every 7 hours. How many cells will be in the colony after 21 hours?", "question": "Calculate the population after 21 hours.", "options": ["A. 2100", "B. 2800", "C. 5600", "D. 11200"], "answer": 2, "explanation": "Số chu kỳ nhân đôi trong 21 giờ là 21 / 7 = 3 chu kỳ. Số lượng tế bào là P(21) = 700 × 2³ = 700 × 8 = 5600 (Đáp án C)."}, {"id": "e8-m2-q4", "domain": "Geometry and Trigonometry", "skill": "Right Triangle Trigonometry & Complementary Angles", "passage": "In right triangle PQR, angle R = 90° and cos(P) = 6/13. If triangle XYZ is similar to triangle PQR where vertices X, Y, and Z correspond to P, Q, and R, respectively, and each side of triangle XYZ is 10 times the corresponding side of triangle PQR, what is the value of sin(Y)?", "question": "Find the value of sin(Y).", "options": ["A. 6/13", "B. 11/13", "C. 60/13", "D. 13/6"], "answer": 0, "explanation": "Do tam giác XYZ đồng dạng với tam giác PQR nên góc Y = góc Q. Trong tam giác vuông PQR (P + Q = 90°), ta luôn có sin(Y) = sin(Q) = cos(P) = 6/13 (Đáp án A)."}, {"id": "e8-m2-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Weighted Mean & Statistics", "passage": "A dataset consists of 50 observations split into two groups. Group 1 contains 20 observations with a mean of 83, and Group 2 contains 30 observations with a mean of 93. What is the mean of all 50 observations combined?", "question": "Calculate the combined mean.", "options": ["A. 88", "B. 88.5", "C. 89", "D. 90"], "answer": 2, "explanation": "Tổng giá trị cả 2 nhóm là 20 × 83 + 30 × 93 = 4450. Chia cho tổng số 50 quan sát ta được trung bình chung là 89 (Đáp án C)."}]}]}, {"id": "exam-9", "number": 9, "title": "Đề thi thử Digital SAT #9 — Pre-Exam Full Dress Rehearsal I", "difficulty": "Nâng cao (Hard)", "badge": "Tổng duyệt đợt 1", "desc": "Đề tổng duyệt toàn diện số 1 trước kỳ thi thật, bao phủ đầy đủ 8 chuyên đề cốt lõi.", "modules": [{"id": "rw-m1", "name": "Section 1, Module 1: Reading and Writing", "shortName": "R&W Mod 1", "section": "Reading & Writing", "durationMinutes": 32, "directions": "The questions in this section address a number of important reading and writing skills. Each question includes one or more passages, which may include a table or graph. Read each passage and question carefully, and then choose the best answer to the question based on the passage(s).", "questions": [{"id": "e9-rw1-q1", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "When defoliated by insects, birch saplings receive carbon compounds through underground fungal networks from neighboring fir trees, demonstrating that forest relationships are not purely ______. Researchers noted that these findings help refine contemporary models of mycorrhizal resource sharing.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. symbiotic", "B. antagonistic", "C. cooperative", "D. beneficial"], "answer": 1, "explanation": "Việc cây chia sẻ dưỡng chất cho nhau chứng minh quan hệ giữa chúng không thuần túy là 'đối kháng/cạnh tranh' (antagonistic)."}, {"id": "e9-rw1-q2", "domain": "Information and Ideas", "skill": "Inferences", "passage": "Agricultural waste such as hemp hurds and rice hulls can be inoculated with fungal mycelium, which binds the fibers into lightweight foam-like blocks within five days. Unlike petroleum-based polyurethane acoustic panels, mycelium blocks are naturally flame-retardant and fully biodegradable at the end of a building's life cycle, suggesting that ______", "question": "Which choice most logically completes the text?", "options": ["A. fungal mycelium requires synthetic plastics to maintain structural rigidity.", "B. mycelium composites offer a circular, low-carbon alternative to conventional petrochemical building insulation.", "C. polyurethane panels decompose faster than rice hulls in soil.", "D. hemp hurds cannot be grown outside tropical climates."], "answer": 1, "explanation": "Vật liệu nấm sợi vừa chống cháy tự nhiên vừa phân hủy sinh học hoàn toàn, mở ra giải pháp thay thế bền vững cho vật liệu cách âm từ dầu mỏ (Đáp án B)."}, {"id": "e9-rw1-q3", "domain": "Information and Ideas", "skill": "Command of Evidence (Quantitative)", "passage": "Solar Microgrid Efficiency Across Three Operating Temperatures (Study #9):\n• Panel Type Alpha: 25°C = 23.4% | 45°C = 20.1%\n• Panel Type Beta (Perovskite-Silicon): 25°C = 28.8% | 45°C = 27.9%\n\nEnergy engineers report that while all photovoltaic modules lose efficiency as ambient temperatures rise, Perovskite-Silicon (Type Beta) panels exhibit both higher baseline efficiency and superior thermal stability at 45°C compared to Type Alpha panels.", "question": "Which data from the study most directly support the engineers' report?", "options": ["A. At 25°C, Type Alpha achieves 23.4% efficiency, which is higher than its efficiency at 45°C.", "B. Type Beta starts at 28.8% at 25°C and retains 27.9% at 45°C (a drop of only 0.9%), whereas Type Alpha drops from 23.4% to 20.1%.", "C. Both panel types were tested at exactly 25°C and 45°C under laboratory illumination.", "D. Type Alpha's efficiency at 45°C is 20.1%."], "answer": 1, "explanation": "Đáp án B trích dẫn đầy đủ cả hiệu suất nền cao hơn ở 25°C lẫn mức sụt giảm nhiệt độ rất nhỏ (chỉ 0.9%) ở 45°C của Type Beta so với Type Alpha."}, {"id": "e9-rw1-q4", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "In early trials of autonomous marine gliders (Deployment #9), strong subsurface currents frequently pushed the craft off their programmed survey transects. ______ engineers integrated real-time Doppler velocity logs into the navigation software, enabling the gliders to compensate for lateral drift automatically.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. In response,", "B. Nonetheless,", "C. For example,", "D. Conversely,"], "answer": 0, "hint": "Câu 1 nêu vấn đề kỹ thuật; câu 2 nêu giải pháp khắc phục của các kỹ sư.", "explanation": "'In response,' (Để giải quyết vấn đề đó / Đáp lại thực trạng đó) nối hợp lý giữa sự cố trôi dạt ở câu 1 và cải tiến phần mềm điều hướng ở câu 2 (Đáp án A)."}, {"id": "e9-rw1-q5", "domain": "Standard English Conventions", "skill": "Boundaries & Punctuation", "passage": "The archival collection at the Uppsala University Library houses over 535 medieval botanical codices ______ researchers have digitized only a third of these illuminated manuscripts for public open-access repositories.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. codices, however,", "B. codices; however,", "C. codices however", "D. codices, yet; "], "answer": 1, "explanation": "Hai mệnh đề độc lập nối với trạng từ chuyển tiếp 'however' bắt buộc dùng dấu chấm phẩy trước và dấu phẩy sau: 'codices; however,' (Đáp án B)."}]}, {"id": "rw-m2", "name": "Section 1, Module 2: Reading and Writing (Adaptive)", "shortName": "R&W Mod 2", "section": "Reading & Writing", "durationMinutes": 32, "directions": "This is the second adaptive module of Reading and Writing. Answer every question carefully; there is no penalty for guessing.", "questions": [{"id": "e9-rw2-q1", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "Text 1:\nUrban sociologist Dr. Aris Thorne contends that converting downtown arterial roads into pedestrian-only plazas invariably reduces quarterly retail revenue for ground-floor merchants, because suburban customers rely on curbside parking to visit specialty shops (Case Study #9).\n\nText 2:\nEconomist Mei-Ling Zhou analyzed point-of-sale tax receipts across twelve cities before and after pedestrianization. She found that while drive-in purchases dipped during the first month of construction, total annual retail sales rose by 23% as foot traffic and outdoor dining dwell times increased.", "question": "Based on the texts, how would Zhou (Text 2) most likely characterize Thorne's conclusion in Text 1?", "options": ["A. As an accurate reflection of long-term tax receipt data across all twelve studied cities.", "B. As an overgeneralization that overlooks how increased pedestrian foot traffic more than compensates for reduced curbside parking over a full year.", "C. As proof that outdoor dining establishments should be relocated to suburban shopping malls.", "D. As a valid critique of public transit fare structures."], "answer": 1, "explanation": "Số liệu thực tế cả năm của Zhou (doanh thu tăng nhờ khách đi bộ và ăn uống ngoài trời) bác bỏ dự đoán bi quan của Thorne vốn chỉ nhìn vào việc giảm chỗ đỗ xe (Đáp án B)."}, {"id": "e9-rw2-q2", "domain": "Information and Ideas", "skill": "Command of Evidence (Textual)", "passage": "In a study of avian vocal learning (Cohort #9), neurobiologist Dr. Lucas Vance proposes that juvenile songbirds must hear adult tutor songs during a critical developmental window not merely to copy individual notes, but to calibrate the tempo boundaries between syllables.", "question": "Which finding from Vance's experiment, if true, would most directly support his hypothesis?", "options": ["A. Juvenile songbirds raised in acoustic isolation produced all the correct note frequencies of their species but sang them with erratic, uncoordinated pauses between syllables.", "B. Adult songbirds sang more frequently during spring mornings than during autumn afternoons.", "C. Juvenile songbirds fed a high-protein diet developed larger flight muscles than control birds did.", "D. Different species of finches inhabit distinct canopy heights in tropical rainforests."], "answer": 0, "explanation": "Nếu chim non không được nghe chim trưởng thành vẫn phát ra đúng tần số nốt nhưng lại bị rối loạn khoảng nghỉ/nhịp độ giữa các âm tiết ('erratic pauses between syllables'), điều đó chứng minh trực tiếp vai trò hiệu chỉnh nhịp độ (tempo boundaries) của chim thầy (Đáp án A)."}, {"id": "e9-rw2-q3", "domain": "Standard English Conventions", "skill": "Subject-Verb Agreement & Modifiers", "passage": "Calibrating the 14 interferometer mirrors inside the underground gravitational-wave detector ______ sub-nanometer precision so that passing seismic vibrations from distant ocean waves do not mask astrophysical signals.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. require", "B. requires", "C. have required", "D. are requiring"], "answer": 1, "explanation": "Chủ ngữ chính là danh động từ (gerund phrase) 'Calibrating the ... mirrors' (ngôi thứ ba số ít), không phải 'mirrors' hay 'detector'. Do đó động từ chia số ít là 'requires' (Đáp án B)."}, {"id": "e9-rw2-q4", "domain": "Standard English Conventions", "skill": "Dangling Modifier", "passage": "Synthesized from plant-derived monomers at temperatures below 98°C, ______ ", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. chemical engineers designed the new recyclable polymer to dissolve in mild acidic solutions.", "B. the new recyclable polymer dissolves cleanly when immersed in mild acidic solutions.", "C. mild acidic solutions can dissolve the new recyclable polymer completely.", "D. a breakthrough in sustainable packaging was achieved by the research team."], "answer": 1, "explanation": "Cụm phân từ mở đầu 'Synthesized from plant-derived monomers...' bổ nghĩa cho chất được tổng hợp, tức là 'the new recyclable polymer' phải đứng ngay sau dấu phẩy làm chủ ngữ (Đáp án B)."}, {"id": "e9-rw2-q5", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes (Archive #9):\n• Geothermal district heating circulates naturally warm subterranean water through insulated municipal pipes.\n• In Reykjavik, Iceland, geothermal wells supply space heating to 98% of residential buildings.\n• Transitioning from imported coal to geothermal heating between 1930 and 1970 eliminated winter smog in Reykjavik.\n• Today, the system prevents approximately 4.1 million metric tons of CO₂ emissions annually.", "question": "The student wants to emphasize both the historical and ongoing environmental benefits of Reykjavik's geothermal heating system. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Reykjavik's geothermal district heating system circulates warm subterranean water to 98% of the city's residential buildings.", "B. By replacing imported coal between 1930 and 1970, Reykjavik's geothermal heating system eliminated historical winter smog and continues to prevent 4.1 million metric tons of CO₂ emissions each year.", "C. Geothermal district heating uses insulated municipal pipes to transport subterranean water.", "D. Today, Reykjavik prevents 4.1 million metric tons of CO₂ emissions annually through district heating."], "answer": 1, "explanation": "Đáp án B kết hợp đầy đủ lợi ích môi trường trong lịch sử (xóa bỏ khói bụi than đá giai đoạn 1930–1970) VÀ lợi ích hiện tại (ngăn ngừa hàng triệu tấn CO₂ mỗi năm)."}]}, {"id": "math-m1", "name": "Section 2, Module 1: Math", "shortName": "Math Mod 1", "section": "Math", "durationMinutes": 35, "directions": "The questions in this section address a number of important math skills. Use of an integrated calculator is permitted for all questions. You may open the Reference Sheet at any time.", "questions": [{"id": "e9-m1-q1", "domain": "Algebra", "skill": "Linear Equations in One Variable", "passage": "If 5x − 4 = 2x + 35, what is the value of 4x + 5?", "question": "Select the correct value of 4x + 5.", "options": ["A. 13", "B. 53", "C. 57", "D. 63"], "answer": 2, "explanation": "Chuyển vế: 5x − 2x = 35 + 4 ⇔ 3x = 39 ⇔ x = 13. Thay x = 13 vào biểu thức 4x + 5 ta được 4(13) + 5 = 57 (Đáp án C)."}, {"id": "e9-m1-q2", "domain": "Algebra", "skill": "Systems of Two Linear Equations", "passage": "If (x, y) is the solution to the system of equations below:\n4x + 5y = 83\n5x + 4y = 88\nWhat is the value of x + y?", "question": "Calculate x + y.", "options": ["A. 17", "B. 19", "C. 22", "D. 171"], "answer": 1, "explanation": "Cộng vế theo vế hai phương trình: (4x + 5x) + (5y + 4y) = 83 + 88 ⇔ 9(x + y) = 171. Chia hai vế cho 9 ta được x + y = 19 (Đáp án B)."}, {"id": "e9-m1-q3", "domain": "Advanced Math", "skill": "Quadratic Functions & Vertex", "passage": "The function f is defined by f(x) = x² − 22x + 142. What is the minimum value of f(x)?", "question": "Find the minimum value of f(x).", "options": ["A. 11", "B. 21", "C. 142", "D. −22"], "answer": 1, "explanation": "Hoành độ đỉnh của parabol là x = −b/(2a) = 22/2 = 11 (hoặc ghép bình phương f(x) = (x − 11)² + 21). Giá trị cực tiểu của hàm số là f(11) = 21 (Đáp án B)."}, {"id": "e9-m1-q4", "domain": "Geometry and Trigonometry", "skill": "Circles in the xy-plane", "passage": "In the xy-plane, the graph of the equation x² − 6x + y² + 8y = 171 is a circle. What is the radius of the circle?", "question": "Determine the radius r.", "options": ["A. 12", "B. 14", "C. 28", "D. 196"], "answer": 1, "explanation": "Ghép bình phương hai biến: (x² − 6x + 9) + (y² + 8y + 16) = 171 + 9 + 16 ⇔ (x − 3)² + (y + 4)² = 196 = 14². Vậy bán kính đường tròn là r = 14 (Đáp án B)."}, {"id": "e9-m1-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Percentages", "passage": "A research grant of $380,000 was increased by 50% in Year 2 and then reduced by 20% in Year 3. What was the dollar amount, in thousands, of the grant in Year 3?", "question": "Calculate the Year 3 grant amount (in thousands of dollars).", "options": ["A. $494,000", "B. $456,000", "C. $380,000", "D. $436,000"], "answer": 1, "explanation": "Nhân các hệ số thay đổi liên tiếp: 380 × 1.50 × 0.80 = 380 × 1.20 = 456 (nghìn USD). Đáp án B."}]}, {"id": "math-m2", "name": "Section 2, Module 2: Math (Adaptive)", "shortName": "Math Mod 2", "section": "Math", "durationMinutes": 35, "directions": "This is the second adaptive module of Math. Check your units and review flagged questions before submitting the exam.", "questions": [{"id": "e9-m2-q1", "domain": "Algebra", "skill": "Linear Systems (No Solution Parameter)", "passage": "In the system of linear equations below, k is a constant:\n11x − 7y = 13\n33x + ky = 29\nIf the system has no solution, what is the value of k?", "question": "Find the value of the constant k.", "options": ["A. -21", "B. -7", "C. 21", "D. 14"], "answer": 0, "explanation": "Hệ phương trình vô nghiệm khi hai đường thẳng song song: 11/33 = (−7)/k ≠ 13/29 ⇔ 1/3 = (−7)/k ⇒ k = -21 (Đáp án A)."}, {"id": "e9-m2-q2", "domain": "Advanced Math", "skill": "Quadratic Equations (Vieta's Theorem)", "passage": "What is the sum of the solutions to the equation 2x² − 42x + 10 = 0?", "question": "Find the sum of the solutions.", "options": ["A. −21", "B. 5.0", "C. 21", "D. 42"], "answer": 2, "explanation": "Theo định lý Viète cho phương trình bậc hai ax² + bx + c = 0 (với Δ > 0), tổng hai nghiệm bằng −b/a = −(−42)/2 = 21 (Đáp án C)."}, {"id": "e9-m2-q3", "domain": "Advanced Math", "skill": "Exponential Growth Functions", "passage": "A bacterial colony starts with 750 cells and doubles in population every 4 hours. How many cells will be in the colony after 12 hours?", "question": "Calculate the population after 12 hours.", "options": ["A. 2250", "B. 3000", "C. 6000", "D. 12000"], "answer": 2, "explanation": "Số chu kỳ nhân đôi trong 12 giờ là 12 / 4 = 3 chu kỳ. Số lượng tế bào là P(12) = 750 × 2³ = 750 × 8 = 6000 (Đáp án C)."}, {"id": "e9-m2-q4", "domain": "Geometry and Trigonometry", "skill": "Right Triangle Trigonometry & Complementary Angles", "passage": "In right triangle PQR, angle R = 90° and cos(P) = 5/13. If triangle XYZ is similar to triangle PQR where vertices X, Y, and Z correspond to P, Q, and R, respectively, and each side of triangle XYZ is 11 times the corresponding side of triangle PQR, what is the value of sin(Y)?", "question": "Find the value of sin(Y).", "options": ["A. 5/13", "B. 12/13", "C. 55/13", "D. 13/5"], "answer": 0, "explanation": "Do tam giác XYZ đồng dạng với tam giác PQR nên góc Y = góc Q. Trong tam giác vuông PQR (P + Q = 90°), ta luôn có sin(Y) = sin(Q) = cos(P) = 5/13 (Đáp án A)."}, {"id": "e9-m2-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Weighted Mean & Statistics", "passage": "A dataset consists of 50 observations split into two groups. Group 1 contains 20 observations with a mean of 84, and Group 2 contains 30 observations with a mean of 94. What is the mean of all 50 observations combined?", "question": "Calculate the combined mean.", "options": ["A. 89", "B. 89.5", "C. 90", "D. 91"], "answer": 2, "explanation": "Tổng giá trị cả 2 nhóm là 20 × 84 + 30 × 94 = 4500. Chia cho tổng số 50 quan sát ta được trung bình chung là 90 (Đáp án C)."}]}]}, {"id": "exam-10", "number": 10, "title": "Đề thi thử Digital SAT #10 — Elite 1500+ Target Simulation", "difficulty": "Rất cao (1500+ Challenge)", "badge": "Chinh phục 1500+", "desc": "Đề tổng duyệt độ phân hóa cao nhất, tập trung vào suy luận học thuật sâu và bài toán tham số.", "modules": [{"id": "rw-m1", "name": "Section 1, Module 1: Reading and Writing", "shortName": "R&W Mod 1", "section": "Reading & Writing", "durationMinutes": 32, "directions": "The questions in this section address a number of important reading and writing skills. Each question includes one or more passages, which may include a table or graph. Read each passage and question carefully, and then choose the best answer to the question based on the passage(s).", "questions": [{"id": "e10-rw1-q1", "domain": "Craft and Structure", "skill": "Words in Context", "passage": "Once dismissed by late-twentieth-century critics as ______ monuments of raw concrete, Brutalist civic buildings are now celebrated by preservationists for their sculptural honesty. Researchers noted that these findings help refine contemporary models of architectural brutalism.", "question": "Which choice completes the text with the most logical and precise word or phrase?", "options": ["A. ornate", "B. austere", "C. flamboyant", "D. fragile"], "answer": 1, "explanation": "'Austere' (khắc khổ, lạnh lùng không trang trí) mô tả đúng định kiến trước đây về kiến trúc bê tông thô Brutalism."}, {"id": "e10-rw1-q2", "domain": "Information and Ideas", "skill": "Inferences", "passage": "Modern viewers often assume that silent films of the 1910s were projected strictly in black and white. Archival nitrate prints reveal, however, that over 80 percent of feature films from that decade were chemically tinted—amber for interior lamplight, blue for night scenes, and crimson for fire—demonstrating that ______", "question": "Which choice most logically completes the text?", "options": ["A. color functioned as an integral narrative and emotional code in cinema long before the invention of Technicolor.", "B. audiences in the 1910s preferred black-and-white newsreels over feature films.", "C. chemical tinting destroyed nitrate film stock within a single screening.", "D. silent film directors avoided filming nighttime scenes."], "answer": 0, "explanation": "Hơn 80% phim câm thập niên 1910 được nhuộm màu theo bối cảnh, chứng tỏ màu sắc đã đóng vai trò kể chuyện và tạo cảm xúc từ rất lâu trước khi có Technicolor (Đáp án A)."}, {"id": "e10-rw1-q3", "domain": "Information and Ideas", "skill": "Command of Evidence (Quantitative)", "passage": "Solar Microgrid Efficiency Across Three Operating Temperatures (Study #10):\n• Panel Type Alpha: 25°C = 21.4% | 45°C = 18.1%\n• Panel Type Beta (Perovskite-Silicon): 25°C = 26.8% | 45°C = 25.9%\n\nEnergy engineers report that while all photovoltaic modules lose efficiency as ambient temperatures rise, Perovskite-Silicon (Type Beta) panels exhibit both higher baseline efficiency and superior thermal stability at 45°C compared to Type Alpha panels.", "question": "Which data from the study most directly support the engineers' report?", "options": ["A. At 25°C, Type Alpha achieves 21.4% efficiency, which is higher than its efficiency at 45°C.", "B. Type Beta starts at 26.8% at 25°C and retains 25.9% at 45°C (a drop of only 0.9%), whereas Type Alpha drops from 21.4% to 18.1%.", "C. Both panel types were tested at exactly 25°C and 45°C under laboratory illumination.", "D. Type Alpha's efficiency at 45°C is 18.1%."], "answer": 1, "explanation": "Đáp án B trích dẫn đầy đủ cả hiệu suất nền cao hơn ở 25°C lẫn mức sụt giảm nhiệt độ rất nhỏ (chỉ 0.9%) ở 45°C của Type Beta so với Type Alpha."}, {"id": "e10-rw1-q4", "domain": "Expression of Ideas", "skill": "Transitions", "passage": "In early trials of autonomous marine gliders (Deployment #10), strong subsurface currents frequently pushed the craft off their programmed survey transects. ______ engineers integrated real-time Doppler velocity logs into the navigation software, enabling the gliders to compensate for lateral drift automatically.", "question": "Which choice completes the text with the most logical transition?", "options": ["A. In response,", "B. Nonetheless,", "C. For example,", "D. Conversely,"], "answer": 0, "hint": "Câu 1 nêu vấn đề kỹ thuật; câu 2 nêu giải pháp khắc phục của các kỹ sư.", "explanation": "'In response,' (Để giải quyết vấn đề đó / Đáp lại thực trạng đó) nối hợp lý giữa sự cố trôi dạt ở câu 1 và cải tiến phần mềm điều hướng ở câu 2 (Đáp án A)."}, {"id": "e10-rw1-q5", "domain": "Standard English Conventions", "skill": "Boundaries & Punctuation", "passage": "The archival collection at the Uppsala University Library houses over 550 medieval botanical codices ______ researchers have digitized only a third of these illuminated manuscripts for public open-access repositories.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. codices, however,", "B. codices; however,", "C. codices however", "D. codices, yet; "], "answer": 1, "explanation": "Hai mệnh đề độc lập nối với trạng từ chuyển tiếp 'however' bắt buộc dùng dấu chấm phẩy trước và dấu phẩy sau: 'codices; however,' (Đáp án B)."}]}, {"id": "rw-m2", "name": "Section 1, Module 2: Reading and Writing (Adaptive)", "shortName": "R&W Mod 2", "section": "Reading & Writing", "durationMinutes": 32, "directions": "This is the second adaptive module of Reading and Writing. Answer every question carefully; there is no penalty for guessing.", "questions": [{"id": "e10-rw2-q1", "domain": "Craft and Structure", "skill": "Cross-Text Connections", "passage": "Text 1:\nUrban sociologist Dr. Aris Thorne contends that converting downtown arterial roads into pedestrian-only plazas invariably reduces quarterly retail revenue for ground-floor merchants, because suburban customers rely on curbside parking to visit specialty shops (Case Study #10).\n\nText 2:\nEconomist Mei-Ling Zhou analyzed point-of-sale tax receipts across twelve cities before and after pedestrianization. She found that while drive-in purchases dipped during the first month of construction, total annual retail sales rose by 24% as foot traffic and outdoor dining dwell times increased.", "question": "Based on the texts, how would Zhou (Text 2) most likely characterize Thorne's conclusion in Text 1?", "options": ["A. As an accurate reflection of long-term tax receipt data across all twelve studied cities.", "B. As an overgeneralization that overlooks how increased pedestrian foot traffic more than compensates for reduced curbside parking over a full year.", "C. As proof that outdoor dining establishments should be relocated to suburban shopping malls.", "D. As a valid critique of public transit fare structures."], "answer": 1, "explanation": "Số liệu thực tế cả năm của Zhou (doanh thu tăng nhờ khách đi bộ và ăn uống ngoài trời) bác bỏ dự đoán bi quan của Thorne vốn chỉ nhìn vào việc giảm chỗ đỗ xe (Đáp án B)."}, {"id": "e10-rw2-q2", "domain": "Information and Ideas", "skill": "Command of Evidence (Textual)", "passage": "In a study of avian vocal learning (Cohort #10), neurobiologist Dr. Lucas Vance proposes that juvenile songbirds must hear adult tutor songs during a critical developmental window not merely to copy individual notes, but to calibrate the tempo boundaries between syllables.", "question": "Which finding from Vance's experiment, if true, would most directly support his hypothesis?", "options": ["A. Juvenile songbirds raised in acoustic isolation produced all the correct note frequencies of their species but sang them with erratic, uncoordinated pauses between syllables.", "B. Adult songbirds sang more frequently during spring mornings than during autumn afternoons.", "C. Juvenile songbirds fed a high-protein diet developed larger flight muscles than control birds did.", "D. Different species of finches inhabit distinct canopy heights in tropical rainforests."], "answer": 0, "explanation": "Nếu chim non không được nghe chim trưởng thành vẫn phát ra đúng tần số nốt nhưng lại bị rối loạn khoảng nghỉ/nhịp độ giữa các âm tiết ('erratic pauses between syllables'), điều đó chứng minh trực tiếp vai trò hiệu chỉnh nhịp độ (tempo boundaries) của chim thầy (Đáp án A)."}, {"id": "e10-rw2-q3", "domain": "Standard English Conventions", "skill": "Subject-Verb Agreement & Modifiers", "passage": "Calibrating the 15 interferometer mirrors inside the underground gravitational-wave detector ______ sub-nanometer precision so that passing seismic vibrations from distant ocean waves do not mask astrophysical signals.", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. require", "B. requires", "C. have required", "D. are requiring"], "answer": 1, "explanation": "Chủ ngữ chính là danh động từ (gerund phrase) 'Calibrating the ... mirrors' (ngôi thứ ba số ít), không phải 'mirrors' hay 'detector'. Do đó động từ chia số ít là 'requires' (Đáp án B)."}, {"id": "e10-rw2-q4", "domain": "Standard English Conventions", "skill": "Dangling Modifier", "passage": "Synthesized from plant-derived monomers at temperatures below 100°C, ______ ", "question": "Which choice completes the text so that it conforms to the conventions of Standard English?", "options": ["A. chemical engineers designed the new recyclable polymer to dissolve in mild acidic solutions.", "B. the new recyclable polymer dissolves cleanly when immersed in mild acidic solutions.", "C. mild acidic solutions can dissolve the new recyclable polymer completely.", "D. a breakthrough in sustainable packaging was achieved by the research team."], "answer": 1, "explanation": "Cụm phân từ mở đầu 'Synthesized from plant-derived monomers...' bổ nghĩa cho chất được tổng hợp, tức là 'the new recyclable polymer' phải đứng ngay sau dấu phẩy làm chủ ngữ (Đáp án B)."}, {"id": "e10-rw2-q5", "domain": "Expression of Ideas", "skill": "Rhetorical Synthesis", "passage": "While researching a topic, a student has taken the following notes (Archive #10):\n• Geothermal district heating circulates naturally warm subterranean water through insulated municipal pipes.\n• In Reykjavik, Iceland, geothermal wells supply space heating to 98% of residential buildings.\n• Transitioning from imported coal to geothermal heating between 1930 and 1970 eliminated winter smog in Reykjavik.\n• Today, the system prevents approximately 2.1 million metric tons of CO₂ emissions annually.", "question": "The student wants to emphasize both the historical and ongoing environmental benefits of Reykjavik's geothermal heating system. Which choice most effectively uses relevant information from the notes to accomplish this goal?", "options": ["A. Reykjavik's geothermal district heating system circulates warm subterranean water to 98% of the city's residential buildings.", "B. By replacing imported coal between 1930 and 1970, Reykjavik's geothermal heating system eliminated historical winter smog and continues to prevent 2.1 million metric tons of CO₂ emissions each year.", "C. Geothermal district heating uses insulated municipal pipes to transport subterranean water.", "D. Today, Reykjavik prevents 2.1 million metric tons of CO₂ emissions annually through district heating."], "answer": 1, "explanation": "Đáp án B kết hợp đầy đủ lợi ích môi trường trong lịch sử (xóa bỏ khói bụi than đá giai đoạn 1930–1970) VÀ lợi ích hiện tại (ngăn ngừa hàng triệu tấn CO₂ mỗi năm)."}]}, {"id": "math-m1", "name": "Section 2, Module 1: Math", "shortName": "Math Mod 1", "section": "Math", "durationMinutes": 35, "directions": "The questions in this section address a number of important math skills. Use of an integrated calculator is permitted for all questions. You may open the Reference Sheet at any time.", "questions": [{"id": "e10-m1-q1", "domain": "Algebra", "skill": "Linear Equations in One Variable", "passage": "If 5x − 4 = 2x + 38, what is the value of 4x + 5?", "question": "Select the correct value of 4x + 5.", "options": ["A. 14", "B. 57", "C. 61", "D. 67"], "answer": 2, "explanation": "Chuyển vế: 5x − 2x = 38 + 4 ⇔ 3x = 42 ⇔ x = 14. Thay x = 14 vào biểu thức 4x + 5 ta được 4(14) + 5 = 61 (Đáp án C)."}, {"id": "e10-m1-q2", "domain": "Algebra", "skill": "Systems of Two Linear Equations", "passage": "If (x, y) is the solution to the system of equations below:\n4x + 5y = 87\n5x + 4y = 93\nWhat is the value of x + y?", "question": "Calculate x + y.", "options": ["A. 18", "B. 20", "C. 23", "D. 180"], "answer": 1, "explanation": "Cộng vế theo vế hai phương trình: (4x + 5x) + (5y + 4y) = 87 + 93 ⇔ 9(x + y) = 180. Chia hai vế cho 9 ta được x + y = 20 (Đáp án B)."}, {"id": "e10-m1-q3", "domain": "Advanced Math", "skill": "Quadratic Functions & Vertex", "passage": "The function f is defined by f(x) = x² − 24x + 167. What is the minimum value of f(x)?", "question": "Find the minimum value of f(x).", "options": ["A. 12", "B. 23", "C. 167", "D. −24"], "answer": 1, "explanation": "Hoành độ đỉnh của parabol là x = −b/(2a) = 24/2 = 12 (hoặc ghép bình phương f(x) = (x − 12)² + 23). Giá trị cực tiểu của hàm số là f(12) = 23 (Đáp án B)."}, {"id": "e10-m1-q4", "domain": "Geometry and Trigonometry", "skill": "Circles in the xy-plane", "passage": "In the xy-plane, the graph of the equation x² − 6x + y² + 8y = 200 is a circle. What is the radius of the circle?", "question": "Determine the radius r.", "options": ["A. 13", "B. 15", "C. 30", "D. 225"], "answer": 1, "explanation": "Ghép bình phương hai biến: (x² − 6x + 9) + (y² + 8y + 16) = 200 + 9 + 16 ⇔ (x − 3)² + (y + 4)² = 225 = 15². Vậy bán kính đường tròn là r = 15 (Đáp án B)."}, {"id": "e10-m1-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Percentages", "passage": "A research grant of $400,000 was increased by 50% in Year 2 and then reduced by 20% in Year 3. What was the dollar amount, in thousands, of the grant in Year 3?", "question": "Calculate the Year 3 grant amount (in thousands of dollars).", "options": ["A. $520,000", "B. $480,000", "C. $400,000", "D. $459,000"], "answer": 1, "explanation": "Nhân các hệ số thay đổi liên tiếp: 400 × 1.50 × 0.80 = 400 × 1.20 = 480 (nghìn USD). Đáp án B."}]}, {"id": "math-m2", "name": "Section 2, Module 2: Math (Adaptive)", "shortName": "Math Mod 2", "section": "Math", "durationMinutes": 35, "directions": "This is the second adaptive module of Math. Check your units and review flagged questions before submitting the exam.", "questions": [{"id": "e10-m2-q1", "domain": "Algebra", "skill": "Linear Systems (No Solution Parameter)", "passage": "In the system of linear equations below, k is a constant:\n12x − 8y = 13\n36x + ky = 29\nIf the system has no solution, what is the value of k?", "question": "Find the value of the constant k.", "options": ["A. -24", "B. -8", "C. 24", "D. 16"], "answer": 0, "explanation": "Hệ phương trình vô nghiệm khi hai đường thẳng song song: 12/36 = (−8)/k ≠ 13/29 ⇔ 1/3 = (−8)/k ⇒ k = -24 (Đáp án A)."}, {"id": "e10-m2-q2", "domain": "Advanced Math", "skill": "Quadratic Equations (Vieta's Theorem)", "passage": "What is the sum of the solutions to the equation 2x² − 46x + 11 = 0?", "question": "Find the sum of the solutions.", "options": ["A. −23", "B. 5.5", "C. 23", "D. 46"], "answer": 2, "explanation": "Theo định lý Viète cho phương trình bậc hai ax² + bx + c = 0 (với Δ > 0), tổng hai nghiệm bằng −b/a = −(−46)/2 = 23 (Đáp án C)."}, {"id": "e10-m2-q3", "domain": "Advanced Math", "skill": "Exponential Growth Functions", "passage": "A bacterial colony starts with 800 cells and doubles in population every 5 hours. How many cells will be in the colony after 15 hours?", "question": "Calculate the population after 15 hours.", "options": ["A. 2400", "B. 3200", "C. 6400", "D. 12800"], "answer": 2, "explanation": "Số chu kỳ nhân đôi trong 15 giờ là 15 / 5 = 3 chu kỳ. Số lượng tế bào là P(15) = 800 × 2³ = 800 × 8 = 6400 (Đáp án C)."}, {"id": "e10-m2-q4", "domain": "Geometry and Trigonometry", "skill": "Right Triangle Trigonometry & Complementary Angles", "passage": "In right triangle PQR, angle R = 90° and cos(P) = 6/13. If triangle XYZ is similar to triangle PQR where vertices X, Y, and Z correspond to P, Q, and R, respectively, and each side of triangle XYZ is 12 times the corresponding side of triangle PQR, what is the value of sin(Y)?", "question": "Find the value of sin(Y).", "options": ["A. 6/13", "B. 11/13", "C. 72/13", "D. 13/6"], "answer": 0, "explanation": "Do tam giác XYZ đồng dạng với tam giác PQR nên góc Y = góc Q. Trong tam giác vuông PQR (P + Q = 90°), ta luôn có sin(Y) = sin(Q) = cos(P) = 6/13 (Đáp án A)."}, {"id": "e10-m2-q5", "domain": "Problem-Solving & Data Analysis", "skill": "Weighted Mean & Statistics", "passage": "A dataset consists of 50 observations split into two groups. Group 1 contains 20 observations with a mean of 85, and Group 2 contains 30 observations with a mean of 95. What is the mean of all 50 observations combined?", "question": "Calculate the combined mean.", "options": ["A. 90", "B. 90.5", "C. 91", "D. 92"], "answer": 2, "explanation": "Tổng giá trị cả 2 nhóm là 20 × 85 + 30 × 95 = 4550. Chia cho tổng số 50 quan sát ta được trung bình chung là 91 (Đáp án C)."}]}]}];
